window.DERECH_ARTICLE_SEARCH = [{"title":"מה זה בעצם טיפול רגשי בעזרת כלבים?","url":"https://derech-hakelev.com/pages/articles/emotional-therapy-with-dogs/","entries":[{"id":"article-title-e703fd7ce50f","heading":"תחילת המאמר","text":"מה זה בעצם טיפול רגשי בעזרת כלבים?"},{"id":"article-paragraph-c669cc8a6071","heading":"פתיחת המאמר","text":"כשאנשים שומעים על טיפול רגשי בעזרת כלבים, הם לפעמים מדמיינים מפגש שבו משחקים עם כלב, מלטפים אותו, מלמדים אותו פקודות ובעיקר נהנים. כל אלה בהחלט יכולים להיות חלק מהמפגש, אבל מאחוריהם יש הרבה יותר."},{"id":"article-paragraph-b7b16339197d","heading":"פתיחת המאמר","text":"בטיפול רגשי בעזרת כלבים, הכלב משתלב בתהליך הטיפולי ועוזר לנו לעבוד על קשיים רגשיים, התנהגותיים וחברתיים. לפעמים דרך משחק, לפעמים דרך אילוף ולפעמים פשוט דרך הקשר שנוצר איתו."},{"id":"article-paragraph-23967fa7c81a","heading":"פתיחת המאמר","text":"אז מה בעצם הכלב מוסיף לטיפול?"},{"id":"article-heading-0443a7279fc3","heading":"לפעמים קל יותר להיפתח כשיש כלב בחדר","text":"לפעמים קל יותר להיפתח כשיש כלב בחדר"},{"id":"article-paragraph-1b7e9844d205","heading":"לפעמים קל יותר להיפתח כשיש כלב בחדר","text":"אחד הדברים החשובים ביותר בכל טיפול הוא הקשר בין המטפל למטופל. לפני שאפשר לדבר על קשיים, פחדים או חוויות אישיות, צריך קודם כול להרגיש מספיק בטוחים."},{"id":"article-paragraph-3da2489a8463","heading":"לפעמים קל יותר להיפתח כשיש כלב בחדר","text":"אבל לא כולם מגיעים לטיפול עם רצון לדבר. יש ילדים שמתקשים להיפתח מול מבוגר זר, מתבגרים שמגיעים כי ההורים ביקשו, וגם מבוגרים שלא תמיד מרגישים בנוח לשתף אדם שהם רק הכירו."},{"id":"article-paragraph-e3d46f94b1fc","heading":"לפעמים קל יותר להיפתח כשיש כלב בחדר","text":"כאן הכלב יכול לעשות הבדל משמעותי."},{"id":"article-paragraph-f3705f17f6ec","heading":"לפעמים קל יותר להיפתח כשיש כלב בחדר","text":"במקום להתחיל בשאלות, אפשר להתחיל במשחק, בליטוף או בפעילות משותפת. תשומת הלב כבר לא מופנית רק למטופל, והמפגש הופך לפחות רשמי ומאיים."},{"id":"article-paragraph-b56259869b0e","heading":"לפעמים קל יותר להיפתח כשיש כלב בחדר","text":"מהניסיון שלי, הנוכחות של הכלב יכולה לעזור להוריד מגננות, להפחית התנגדויות וליצור קשר ראשוני בצורה טבעית ולעיתים גם מהירה יותר."},{"id":"article-heading-5a01ba7fbdaa","heading":"לא תמיד צריך לדבר על הקושי כדי לעבוד עליו","text":"לא תמיד צריך לדבר על הקושי כדי לעבוד עליו"},{"id":"article-paragraph-b538c3eb5ef7","heading":"לא תמיד צריך לדבר על הקושי כדי לעבוד עליו","text":"אחד היתרונות הגדולים של טיפול בעזרת כלבים הוא האפשרות לעבוד על דברים תוך כדי התנסות, ולא רק באמצעות שיחה."},{"id":"article-paragraph-371ab2a4b4e5","heading":"לא תמיד צריך לדבר על הקושי כדי לעבוד עליו","text":"למשל, ילד שמתקשה להתמודד עם תסכול יכול לקבל משימה ללמד את הכלב פעולה חדשה. בהתחלה הכול הולך מצוין, אבל פתאום הכלב לא משתף פעולה. הילד מנסה שוב, מתעצבן, אולי אפילו רוצה לוותר."},{"id":"article-paragraph-ddd976c89f79","heading":"לא תמיד צריך לדבר על הקושי כדי לעבוד עליו","text":"זה בדיוק הרגע שבו מתחילה העבודה הטיפולית."},{"id":"article-paragraph-57bf804686aa","heading":"לא תמיד צריך לדבר על הקושי כדי לעבוד עליו","text":"אפשר לעצור, להבין מה קרה, לזהות את הרגשות שעלו ולחשוב יחד מה אפשר לעשות אחרת. בהמשך אפשר גם לנסות שוב ולחוות הצלחה."},{"id":"article-paragraph-bc817a9ce3ab","heading":"לא תמיד צריך לדבר על הקושי כדי לעבוד עליו","text":"כך אפשר לעבוד על ויסות רגשי, דחיית סיפוקים, התמדה, ביטחון עצמי, הצבת גבולות, תקשורת ועוד."},{"id":"article-paragraph-9480d5faea85","heading":"לא תמיד צריך לדבר על הקושי כדי לעבוד עליו","text":"במקום רק לדבר על סבלנות, אנחנו מתרגלים אותה. במקום להסביר איך להתמודד עם כישלון, אנחנו פוגשים אותו בסביבה בטוחה ולומדים להתמודד איתו."},{"id":"article-heading-ac1fd8b7a9fa","heading":"לפעמים קל יותר לדבר על הכלב מאשר על עצמנו","text":"לפעמים קל יותר לדבר על הכלב מאשר על עצמנו"},{"id":"article-paragraph-6e7bedc2af61","heading":"לפעמים קל יותר לדבר על הכלב מאשר על עצמנו","text":"דרך נוספת שבה אני נעזר בכלבים בטיפול היא עבודה השלכתית."},{"id":"article-paragraph-d18237396463","heading":"לפעמים קל יותר לדבר על הכלב מאשר על עצמנו","text":"הרבה פעמים קל יותר לדבר על רגשות, מחשבות או קשיים של מישהו אחר מאשר על שלנו."},{"id":"article-paragraph-abf7ee2390e0","heading":"לפעמים קל יותר לדבר על הכלב מאשר על עצמנו","text":"למשל, אפשר לשאול ילד מה לדעתו הכלב מרגיש כשהוא מגיע למקום חדש, מה עוזר לו להרגיש בטוח או איך הוא מגיב כשלא מבינים אותו."},{"id":"article-paragraph-794586095262","heading":"לפעמים קל יותר לדבר על הכלב מאשר על עצמנו","text":"דרך השיחה על הכלב יכולים לעלות נושאים כמו פחד, בדידות, שייכות, צורך בביטחון או קושי לבקש עזרה."},{"id":"article-paragraph-ad3098c6de1f","heading":"לפעמים קל יותר לדבר על הכלב מאשר על עצמנו","text":"לפעמים השיחה נשארת על הכלב, ולפעמים היא מתפתחת באופן טבעי לשיחה על החיים של המטופל."},{"id":"article-paragraph-4c581e52574f","heading":"לפעמים קל יותר לדבר על הכלב מאשר על עצמנו","text":"היתרון הוא שלא חייבים לשאול שאלות ישירות או ללחוץ על המטופל לשתף. אפשר להתקרב לנושאים רגישים בקצב שלו, דרך משהו שמרגיש פחות מאיים."},{"id":"article-heading-1f4fe4e607d0","heading":"הכלב גם יכול לעזור לנו להירגע","text":"הכלב גם יכול לעזור לנו להירגע"},{"id":"article-paragraph-86145db44111","heading":"הכלב גם יכול לעזור לנו להירגע","text":"מעבר לקשר ולפעילות המשותפת, יש גם השפעה אפשרית של הכלב על תחושת המתח והלחץ."},{"id":"article-paragraph-ae9d77394d41","heading":"הכלב גם יכול לעזור לנו להירגע","text":"מחקרים מצאו שאינטראקציה עם כלבים עשויה להפחית תחושות של סטרס וחרדה. למשל, סקירה ומטא-אנליזה שפורסמה בשנת 2025 מצאה ירידה ברמות המתח והחרדה בקרב סטודנטים שהשתתפו בהתערבויות בעזרת כלבים."},{"id":"article-paragraph-fb16c0270827","heading":"הכלב גם יכול לעזור לנו להירגע","text":"לפעמים אפשר לראות את זה גם במפגש עצמו. מטופל שמגיע מתוח, מתיישב ליד הכלב, מלטף אותו ובהדרגה מצליח להירגע."},{"id":"article-paragraph-db4e110498cf","heading":"הכלב גם יכול לעזור לנו להירגע","text":"אבל מבחינתי, המטרה היא לא רק שהמטופל ירגיש טוב בזמן שהוא נמצא עם הכלב. המטרה היא להשתמש בחוויה הזאת כדי לעזור לו להבין מה מרגיע אותו, לזהות את הצרכים שלו ולפתח כלים שיוכל להשתמש בהם גם מחוץ לחדר הטיפולים."},{"id":"article-heading-69727beeb76f","heading":"אז מה בעצם עושים בטיפול?","text":"אז מה בעצם עושים בטיפול?"},{"id":"article-paragraph-377348ad903a","heading":"אז מה בעצם עושים בטיפול?","text":"אין שני מפגשים שנראים בדיוק אותו הדבר."},{"id":"article-paragraph-4058c8b45820","heading":"אז מה בעצם עושים בטיפול?","text":"לפעמים אנחנו משחקים עם הכלב, לפעמים מלמדים אותו משימות חדשות, לפעמים משלבים משחקים טיפוליים ולפעמים פשוט יושבים ומדברים כשהכלב נמצא לידנו."},{"id":"article-paragraph-a5898bf73eb5","heading":"אז מה בעצם עושים בטיפול?","text":"מה שחשוב הוא לא הפעילות עצמה, אלא מה שאנחנו עושים איתה."},{"id":"article-paragraph-77a33b36d9fc","heading":"אז מה בעצם עושים בטיפול?","text":"אותו משחק יכול לשמש לעבודה על ביטחון עצמי אצל מטופל אחד, על ויסות רגשי אצל מטופל אחר ועל תקשורת ושיתוף פעולה אצל מטופל שלישי."},{"id":"article-paragraph-297a7eb9cfbc","heading":"אז מה בעצם עושים בטיפול?","text":"הכול תלוי במטרות הטיפוליות, בצרכים של המטופל ובמה שעולה במהלך המפגש."},{"id":"article-paragraph-8539f4b27a23","heading":"אז מה בעצם עושים בטיפול?","text":"חשוב גם לזכור שהכלב הוא שותף לתהליך, ולא רק כלי עבודה. גם לו יש צרכים, גבולות ורצונות שחשוב לכבד. ההתייחסות הזאת בפני עצמה יכולה להפוך להזדמנות לעבודה על אמפתיה, הקשבה והתחשבות באחר."},{"id":"article-heading-1482e8bd25e1","heading":"אז האם זה באמת עובד?","text":"אז האם זה באמת עובד?"},{"id":"article-paragraph-568b8c840a81","heading":"אז האם זה באמת עובד?","text":"בשנים האחרונות מצטברים יותר מחקרים שבוחנים את התרומה של כלבים לתהליכים טיפוליים."},{"id":"article-paragraph-41adbe189bf9","heading":"אז האם זה באמת עובד?","text":"סקירות מחקריות מצביעות על פוטנציאל חיובי בתחומים כמו הפחתת מתח וחרדה, שיפור באינטראקציה חברתית ועידוד מעורבות בתהליך."},{"id":"article-paragraph-02179322c0fd","heading":"אז האם זה באמת עובד?","text":"מבחינתי, הכלב הוא לא פתרון קסם, והוא בוודאי לא מחליף את המטפל או את התהליך הטיפולי."},{"id":"article-paragraph-278cfde26b01","heading":"אז האם זה באמת עובד?","text":"אבל הוא יכול לפתוח דלתות שלפעמים קשה לפתוח באמצעות שיחה בלבד."},{"id":"article-paragraph-1c538e48c2a9","heading":"אז האם זה באמת עובד?","text":"הוא מאפשר לנו ליצור קשר, לחוות הצלחות וכישלונות, להתמודד עם תסכול, לתרגל מיומנויות ולדבר על נושאים שלא תמיד פשוט לדבר עליהם."},{"id":"article-paragraph-a20a6bdc5013","heading":"אז האם זה באמת עובד?","text":"ולפעמים, דווקא מתוך משחק פשוט עם הכלב, מתרחשת העבודה הרגשית המשמעותית ביותר."},{"id":"article-reference-6ce74fb7899d","heading":"מקורות","text":"Collier et al. (2022) סקירה שיטתית על השפעת נוכחות כלבים על הקשר הטיפולי."},{"id":"article-reference-df2a1a13067c","heading":"מקורות","text":"Sim et al. (2025) סקירה שיטתית ומטא-אנליזה על השפעת התערבויות בעזרת כלבים על מתח וחרדה בקרב סטודנטים."},{"id":"article-reference-a5d59d11cf6a","heading":"מקורות","text":"The Impact of Dog-Assisted Therapy Among Children and Adolescents with Autism Spectrum Disorder (2024) סקירה שיטתית על התערבויות בעזרת כלבים בקרב ילדים ומתבגרים על הרצף האוטיסטי."}]},{"title":"האם הכלב הוא המטפל?","url":"https://derech-hakelev.com/pages/articles/is-the-dog-the-therapist/","entries":[{"id":"article-title-406adba1f82f","heading":"תחילת המאמר","text":"האם הכלב הוא המטפל?"},{"id":"article-paragraph-5e7366581aea","heading":"פתיחת המאמר","text":"לא מעט פעמים אני נתקל באמירות כמו \"הכלב הוא המטפל האמיתי\" או \"הכלב עושה את כל העבודה\". אני יכול להבין מאיפה הן מגיעות. מי שעובד עם כלבים בטיפול מכיר את הרגעים שבהם הכלב מצליח ליצור קשר, לעורר רגש או להגיע למטופל בדרך שאנחנו כמטפלים לא תמיד מצליחים."},{"id":"article-paragraph-17724bbf8800","heading":"פתיחת המאמר","text":"אבל למרות התרומה המשמעותית של הכלב, חשוב לי להדגיש משהו: הכלב הוא לא המטפל."},{"id":"article-paragraph-107d89933c50","heading":"פתיחת המאמר","text":"הכלב הוא שותף לתהליך הטיפולי, לפעמים שותף משמעותי מאוד, אבל האחריות על התהליך, על המטרות ועל ההתערבויות נשארת אצל המטפל."},{"id":"article-paragraph-a5827b056e7b","heading":"פתיחת המאמר","text":"וההבחנה הזאת חשובה הרבה יותר ממה שאולי נדמה."},{"id":"article-heading-2a46e6d6091b","heading":"כשהכלב הופך למרכז במקום המטופל","text":"כשהכלב הופך למרכז במקום המטופל"},{"id":"article-paragraph-493e6598d77d","heading":"כשהכלב הופך למרכז במקום המטופל","text":"אחד הדברים שאני חושב שחשוב להיזהר מהם בטיפול בעזרת כלבים הוא הנטייה להתמקד יותר מדי בכלב."},{"id":"article-paragraph-a3609dca62d3","heading":"כשהכלב הופך למרכז במקום המטופל","text":"קל מאוד להישאב לזה. הרי הכלב נמצא בחדר, הוא מעורר עניין, אפשר לשחק איתו, ללמד אותו פקודות, לעשות מסלולי מכשולים ולשלב אינספור פעילויות."},{"id":"article-paragraph-4198c23db3aa","heading":"כשהכלב הופך למרכז במקום המטופל","text":"אבל האם כל פעילות כזאת היא בהכרח טיפולית?"},{"id":"article-paragraph-7ff7de299697","heading":"כשהכלב הופך למרכז במקום המטופל","text":"ממש לא."},{"id":"article-paragraph-1e7c37ba7657","heading":"כשהכלב הופך למרכז במקום המטופל","text":"נניח שמטופל מגיע עם קושי בביטחון עצמי, ואנחנו מקדישים את רוב המפגש ללימוד פקודות חדשות לכלב. יכול להיות שהוא ייהנה מאוד, ואפילו יצליח במשימה. אבל אם לא חשבנו איך הפעילות קשורה לקושי שלו, מה אנחנו רוצים לקדם באמצעותה ואיך היא משתלבת בתהליך הטיפולי, יכול להיות שבעצם העברנו שיעור אילוף מוצלח ולא מפגש טיפולי משמעותי."},{"id":"article-paragraph-a4d81b443def","heading":"כשהכלב הופך למרכז במקום המטופל","text":"וזה לא אומר שאילוף הוא לא כלי טיפולי. להפך. אני משתמש באילוף לא מעט, והוא יכול להיות כלי מצוין לעבודה על ויסות רגשי, התמדה, התמודדות עם תסכול, תקשורת וביטחון עצמי."},{"id":"article-paragraph-62907739829c","heading":"כשהכלב הופך למרכז במקום המטופל","text":"ההבדל הוא לא במה שאנחנו עושים, אלא למה אנחנו עושים את זה."},{"id":"article-paragraph-59f43fb5eefc","heading":"כשהכלב הופך למרכז במקום המטופל","text":"גם משחק פשוט עם הכלב יכול להיות התערבות טיפולית משמעותית, ולעומת זאת פעילות מורכבת ומושקעת יכולה להיות כמעט חסרת ערך טיפולי אם היא לא מותאמת לצרכים של המטופל."},{"id":"article-heading-e7b3df925980","heading":"לא כל דבר צריך לעבור דרך הכלב","text":"לא כל דבר צריך לעבור דרך הכלב"},{"id":"article-paragraph-60b34687140e","heading":"לא כל דבר צריך לעבור דרך הכלב","text":"אני חושב שזאת נקודה חשובה במיוחד."},{"id":"article-paragraph-015f00cb1976","heading":"לא כל דבר צריך לעבור דרך הכלב","text":"לפעמים, דווקא בגלל שאנחנו עוסקים בטיפול בעזרת כלבים, נוצרת תחושה שצריך לשלב את הכלב בכל פעילות, בכל שיחה ובכל נושא שעולה."},{"id":"article-paragraph-af2526283ad4","heading":"לא כל דבר צריך לעבור דרך הכלב","text":"אבל לא כל קושי צריך להפוך למשימת אילוף, ולא כל שיחה על רגשות צריכה להתחיל בשאלה \"איך לדעתך הכלב מרגיש?\"."},{"id":"article-paragraph-851c8c5427f3","heading":"לא כל דבר צריך לעבור דרך הכלב","text":"אם מטופל משתף בחוויה משמעותית שעבר, לא תמיד נכון לחפש דרך להכניס את הכלב לשיחה. לפעמים הדבר הנכון ביותר הוא פשוט להקשיב לו, להיות איתו ולתת מקום למה שהוא מביא."},{"id":"article-paragraph-409223c461c2","heading":"לא כל דבר צריך לעבור דרך הכלב","text":"כשאנחנו מתעקשים לשלב את הכלב גם כשאין לכך סיבה טיפולית, אנחנו עלולים להסיט את תשומת הלב מהמטופל, לפספס תכנים חשובים ואפילו לפגוע ברצף של התהליך."},{"id":"article-paragraph-0f362c365561","heading":"לא כל דבר צריך לעבור דרך הכלב","text":"מבחינתי, הכלב צריך לשרת את התהליך הטיפולי, ולא להפך."},{"id":"article-paragraph-e03b57279584","heading":"לא כל דבר צריך לעבור דרך הכלב","text":"זה גם אומר שלפעמים הכלב יהיה פעיל מאוד במפגש, לפעמים הוא פשוט ינוח לידנו, ולפעמים כמעט שלא נשלב אותו בכלל."},{"id":"article-paragraph-ad05aa14de14","heading":"לא כל דבר צריך לעבור דרך הכלב","text":"וזה בסדר גמור."},{"id":"article-heading-bd10000ae735","heading":"ויש דברים שהכלב יכול להביא שאנחנו לא יכולים","text":"ויש דברים שהכלב יכול להביא שאנחנו לא יכולים"},{"id":"article-paragraph-0527c71c2829","heading":"ויש דברים שהכלב יכול להביא שאנחנו לא יכולים","text":"אחרי כל זה, חשוב לי להדגיש גם את הצד השני."},{"id":"article-paragraph-0199909fe794","heading":"ויש דברים שהכלב יכול להביא שאנחנו לא יכולים","text":"יש רגעים שבהם הכלב מצליח להביא לתהליך משהו שאני כמטפל לא בהכרח יכול להביא בעצמי."},{"id":"article-paragraph-b8a423e17f96","heading":"ויש דברים שהכלב יכול להביא שאנחנו לא יכולים","text":"אני רוצה לשתף בסיפור שממחיש את זה."},{"id":"article-paragraph-204f05828d88","heading":"ויש דברים שהכלב יכול להביא שאנחנו לא יכולים","text":"ילדה בת 11 הגיעה למפגש הראשון שלה. עוד לפני המפגש קיבלתי הודעה מאמא שלה שהילדה לא רוצה להגיע."},{"id":"article-paragraph-e96db2e68a99","heading":"ויש דברים שהכלב יכול להביא שאנחנו לא יכולים","text":"כשהיא הגיעה עם אמא שלה, היה ברור שהיא ממש לא רוצה להיות שם. הצגתי את עצמי ואת הכלבים, פניתי אליה וניסיתי ליצור קשר, אבל אחרי שתי שאלות היא התחילה לבכות."},{"id":"article-paragraph-02ff6b8b6bfa","heading":"ויש דברים שהכלב יכול להביא שאנחנו לא יכולים","text":"היא אמרה שהיא לא רוצה את המפגשים, שאין שום סיבה שתהיה בהם ושהיא רוצה ללכת הביתה. גם הניסיונות שלי ושל אמא שלה לעזור לה להישאר נתקלו בהתנגדות מוחלטת."},{"id":"article-paragraph-6e2540bf2c4b","heading":"ויש דברים שהכלב יכול להביא שאנחנו לא יכולים","text":"ואז קרה משהו מעניין."},{"id":"article-paragraph-6b81214193be","heading":"ויש דברים שהכלב יכול להביא שאנחנו לא יכולים","text":"לוגאן, הכלב שלי, ניגש אליה, עלה על ברכיה וחיבק אותה. היא התחילה ללטף אותו, ולאט לאט הבכי נרגע."},{"id":"article-paragraph-ae24fcc355cf","heading":"ויש דברים שהכלב יכול להביא שאנחנו לא יכולים","text":"אני לא יודע מה בדיוק עבר לה בראש באותו רגע, וגם לא יכול לדעת מה לוגאן הרגיש או התכוון לעשות. אבל יכולתי לראות שמשהו באינטראקציה ביניהם השתנה. היא התחילה לדבר, סיפרה על הכלבה שלה, ובהדרגה נפתחה האפשרות להמשיך את המפגש."},{"id":"article-paragraph-11ecb9435ff3","heading":"ויש דברים שהכלב יכול להביא שאנחנו לא יכולים","text":"בהמשך שיחקנו, דיברנו ואפילו צחקנו."},{"id":"article-paragraph-eeaf25c86966","heading":"ויש דברים שהכלב יכול להביא שאנחנו לא יכולים","text":"בסוף המפגש אמא שלה שאלה אותה אם בשבוע הבא היא רוצה להגיע, והילדה חייכה והשיבה בחיוב."},{"id":"article-paragraph-d3a42f30ec4e","heading":"ויש דברים שהכלב יכול להביא שאנחנו לא יכולים","text":"אני חושב שהסיפור הזה ממחיש היטב את הייחודיות של הטיפול בעזרת כלבים."},{"id":"article-paragraph-1026e2369766","heading":"ויש דברים שהכלב יכול להביא שאנחנו לא יכולים","text":"באותו רגע, אחרי שהניסיונות שלי ליצור קשר לא הצליחו, לוגאן הצליח לאפשר משהו אחר. הוא לא שאל אותה למה היא בוכה, לא ניסה לשכנע אותה להישאר ולא ביקש ממנה להסביר מה היא מרגישה."},{"id":"article-paragraph-b1648a69553c","heading":"ויש דברים שהכלב יכול להביא שאנחנו לא יכולים","text":"הוא פשוט יצר איתה קשר בדרך אחרת."},{"id":"article-paragraph-dbcb8d3c8b3f","heading":"ויש דברים שהכלב יכול להביא שאנחנו לא יכולים","text":"וזה בדיוק המקום שבו הכלב יכול להיות שותף משמעותי כל כך לתהליך."},{"id":"article-heading-7868e0d97414","heading":"התפקיד שלנו הוא לדעת מה לעשות עם מה שקורה","text":"התפקיד שלנו הוא לדעת מה לעשות עם מה שקורה"},{"id":"article-paragraph-a4c77ee557af","heading":"התפקיד שלנו הוא לדעת מה לעשות עם מה שקורה","text":"אבל גם בסיפור הזה, לוגאן לא החליף את התהליך הטיפולי."},{"id":"article-paragraph-a76265a73b9b","heading":"התפקיד שלנו הוא לדעת מה לעשות עם מה שקורה","text":"הקשר שנוצר איתו אפשר לנו להתחיל לבנות קשר, להפחית את ההתנגדות הראשונית וליצור חוויה אחרת מזאת שהילדה ציפתה לה."},{"id":"article-paragraph-9c9a9663faf1","heading":"התפקיד שלנו הוא לדעת מה לעשות עם מה שקורה","text":"מכאן התפקיד שלי כמטפל היה להמשיך את העבודה, להבין את הקשיים שלה, לבנות איתה קשר טיפולי ולחשוב איך אפשר להשתמש בחוויות שנוצרות במפגשים כדי לקדם את המטרות שלה."},{"id":"article-paragraph-a3ea9163a479","heading":"התפקיד שלנו הוא לדעת מה לעשות עם מה שקורה","text":"לפעמים ההתערבות הנכונה היא ליזום פעילות עם הכלב, לפעמים לעזור למטופל לעבד חוויה שהתרחשה איתו, ולפעמים דווקא לדעת מתי לא להתערב ולתת לקשר ביניהם להתפתח."},{"id":"article-paragraph-717c9fb90112","heading":"התפקיד שלנו הוא לדעת מה לעשות עם מה שקורה","text":"חשוב גם לזכור שלא כל התנהגות של הכלב היא בהכרח התערבות טיפולית. כלבים הם בעלי חיים עם צרכים, רצונות ותגובות משלהם. לא כל פעולה שלהם נושאת משמעות רגשית עמוקה, ולא צריך לנסות למצוא משמעות כזאת בכל דבר."},{"id":"article-heading-c6084dadd67d","heading":"אז מה הופך את המפגש לטיפולי?","text":"אז מה הופך את המפגש לטיפולי?"},{"id":"article-paragraph-868bd88c17f3","heading":"אז מה הופך את המפגש לטיפולי?","text":"בעיניי, השאלה החשובה היא לא כמה הכלב השתתף במפגש, כמה פקודות המטופל הצליח ללמד אותו או כמה פעילויות הספקנו לעשות."},{"id":"article-paragraph-32406a86289d","heading":"אז מה הופך את המפגש לטיפולי?","text":"השאלה היא מה קרה למטופל במהלך המפגש, ואיך הדברים שהתרחשו בו יכולים לעזור לו גם מחוץ לחדר הטיפולים."},{"id":"article-paragraph-fd29e4153c50","heading":"אז מה הופך את המפגש לטיפולי?","text":"האם הוא הצליח להתמודד עם תסכול? האם התנסה בהצבת גבולות? האם הרגיש בטוח מספיק כדי לשתף? האם הצליח לזהות משהו חדש על עצמו?"},{"id":"article-paragraph-0e1b7425caea","heading":"אז מה הופך את המפגש לטיפולי?","text":"ולפעמים, האם פשוט הצלחנו ליצור קשר במקום שבו קודם הייתה התנגדות?"},{"id":"article-paragraph-0063e1eb0d1e","heading":"אז מה הופך את המפגש לטיפולי?","text":"אני מאמין שהייחודיות של טיפול בעזרת כלבים נמצאת בשילוב בין הידע והחשיבה המקצועית של המטפל לבין האפשרויות שהכלב מביא איתו."},{"id":"article-paragraph-a80ce99992b1","heading":"אז מה הופך את המפגש לטיפולי?","text":"הכלב לא צריך להיות במרכז המפגש כדי להיות משמעותי בו."},{"id":"article-paragraph-04bff0bae08c","heading":"אז מה הופך את המפגש לטיפולי?","text":"המטופל הוא זה שצריך להיות במרכז. תמיד."},{"id":"article-paragraph-2ed452510569","heading":"אז מה הופך את המפגש לטיפולי?","text":"והכלב? הוא יכול להיות שותף נפלא בדרך לשם."}]},{"title":"הגישה ההתפתחותית-היקשרותית בטיפול בעזרת כלבים","url":"https://derech-hakelev.com/pages/articles/developmental-attachment-dog-therapy/","entries":[{"id":"article-title-72382359eb2d","heading":"תחילת המאמר","text":"הגישה ההתפתחותית-היקשרותית בטיפול בעזרת כלבים"},{"id":"article-paragraph-6566d490308f","heading":"פתיחת המאמר","text":"למה ילד מגיב בתוקפנות כשמשהו לא מצליח לו? למה דווקא כשהוא זקוק לעזרה, הוא מתנגד לכל ניסיון לעזור לו? ולמה לפעמים, ככל שאנחנו מנסים ללמד ילד לשלוט בעצמו, כך ההתנגדות שלו רק גוברת?"},{"id":"article-paragraph-54a80b956b39","heading":"פתיחת המאמר","text":"בעבודה הטיפולית אנחנו פוגשים לא מעט התנהגויות מאתגרות. הנטייה הטבעית היא לנסות לשנות אותן: ללמד את הילד לווסת את עצמו, להתמודד עם תסכול, לשתף פעולה או להגיב אחרת."},{"id":"article-paragraph-ea38e9b1218b","heading":"פתיחת המאמר","text":"אבל הגישה ההתפתחותית-היקשרותית מציעה לנו להסתכל על הדברים מזווית קצת אחרת."},{"id":"article-paragraph-3c3c998ff316","heading":"פתיחת המאמר","text":"במקום לשאול רק איך משנים את ההתנהגות, היא מזמינה אותנו לשאול מה עומד מאחוריה, מה הילד צריך ומה יכול לעזור לו להתפתח."},{"id":"article-heading-0c36425ca7b1","heading":"מהי הגישה ההתפתחותית-היקשרותית?","text":"מהי הגישה ההתפתחותית-היקשרותית?"},{"id":"article-paragraph-7854180b8f93","heading":"מהי הגישה ההתפתחותית-היקשרותית?","text":"הגישה ההתפתחותית-היקשרותית, המזוהה בין היתר עם הפסיכולוג הקנדי ד\"ר גורדון ניופלד, נשענת על תיאוריות של התקשרות, התפתחות רגשית ותהליכי הבשלה."},{"id":"article-paragraph-9470c3adce76","heading":"מהי הגישה ההתפתחותית-היקשרותית?","text":"בבסיס הגישה עומדת ההבנה שהתפתחות רגשית היא לא רק עניין של למידת מיומנויות. היא גם תהליך של הבשלה, שמתרחש כאשר מתקיימים התנאים המתאימים."},{"id":"article-paragraph-ffdb893f3722","heading":"מהי הגישה ההתפתחותית-היקשרותית?","text":"אחד התנאים החשובים ביותר הוא תחושת ביטחון בתוך קשר."},{"id":"article-paragraph-ff5eee9b6c83","heading":"מהי הגישה ההתפתחותית-היקשרותית?","text":"כשילד מרגיש שיש מבוגר שאפשר לסמוך עליו, שמבין אותו ושנמצא לצידו גם כשהוא מתקשה, מתאפשר לו בהדרגה להתמודד עם רגשות מורכבים, לחקור, להתנסות ולפתח עצמאות."},{"id":"article-paragraph-bdda9f111692","heading":"מהי הגישה ההתפתחותית-היקשרותית?","text":"זה לא אומר שאין מקום לגבולות, להכוונה או ללמידה. אלא שהקשר והביטחון הם הבסיס שעליו אפשר לבנות את כל אלה."},{"id":"article-paragraph-a339b8475115","heading":"מהי הגישה ההתפתחותית-היקשרותית?","text":"בגישה הזאת אנחנו גם מנסים להבין את ההתנהגות כביטוי אפשרי למשהו עמוק יותר. למשל, מאחורי התפרצות כעס יכולים להסתתר תסכול, פחד, פגיעות או קושי להתמודד עם מציאות שלא תואמת את הרצונות שלנו."},{"id":"article-paragraph-7eaa0a7f71fd","heading":"מהי הגישה ההתפתחותית-היקשרותית?","text":"המטרה היא לא להצדיק כל התנהגות, אלא להבין אותה טוב יותר כדי שנוכל להגיב אליה בצורה שתסייע להתפתחות."},{"id":"article-heading-eddf2c343ecf","heading":"קודם הקשר, אחר כך העבודה","text":"קודם הקשר, אחר כך העבודה"},{"id":"article-paragraph-588f6784c7a8","heading":"קודם הקשר, אחר כך העבודה","text":"אחד הדברים שאני מתחבר אליהם בגישה הזאת הוא החשיבות שהיא נותנת לקשר."},{"id":"article-paragraph-bcbbd12b6c27","heading":"קודם הקשר, אחר כך העבודה","text":"לפעמים אנחנו ממהרים להתחיל לעבוד על המטרות הטיפוליות: ויסות רגשי, דחיית סיפוקים, הצבת גבולות או ביטחון עצמי."},{"id":"article-paragraph-6d136abb64a9","heading":"קודם הקשר, אחר כך העבודה","text":"אבל מה קורה כשהמטופל עדיין לא מרגיש בטוח איתנו? כשהוא חושש להיכשל, מתקשה לתת אמון או בכלל לא רוצה להיות בטיפול?"},{"id":"article-paragraph-1c744f837fff","heading":"קודם הקשר, אחר כך העבודה","text":"כאן בדיוק נכנס אחד היתרונות המשמעותיים של הטיפול בעזרת כלבים."},{"id":"article-paragraph-7eead00c4b25","heading":"קודם הקשר, אחר כך העבודה","text":"הכלב יכול לעזור לנו ליצור קשר בצורה טבעית יותר. במקום להתחיל בשאלות או בניסיון לדבר על הקשיים, אפשר להתחיל במשחק משותף, בליטוף או בפעילות עם הכלב."},{"id":"article-paragraph-06f4d6c06be7","heading":"קודם הקשר, אחר כך העבודה","text":"המפגש עשוי להפוך לפחות מאיים, והמטופל לא מרגיש שכל תשומת הלב מופנית אליו."},{"id":"article-paragraph-f23dafbcd334","heading":"קודם הקשר, אחר כך העבודה","text":"לפעמים הקשר עם הכלב הוא זה שמאפשר את הצעד הראשון לקראת הקשר עם המטפל."},{"id":"article-paragraph-48a827ff1591","heading":"קודם הקשר, אחר כך העבודה","text":"חשוב לי להדגיש שהכלב לא מחליף את הקשר הטיפולי. להפך, אנחנו רוצים להיעזר בקשר שנוצר איתו כדי לבנות בהדרגה גם את הקשר בין המטפל למטופל."},{"id":"article-heading-0503e77809c7","heading":"משחק הוא הרבה יותר ממשחק","text":"משחק הוא הרבה יותר ממשחק"},{"id":"article-paragraph-75250b6ce95c","heading":"משחק הוא הרבה יותר ממשחק","text":"בגישה ההתפתחותית-היקשרותית יש מקום משמעותי למשחק."},{"id":"article-paragraph-014b934c4696","heading":"משחק הוא הרבה יותר ממשחק","text":"משחק מאפשר לנו להתנסות ברגשות, בתפקידים ובמצבים שונים, בלי שנצטרך להתמודד עם כל ההשלכות שלהם במציאות."},{"id":"article-paragraph-5543eaa24039","heading":"משחק הוא הרבה יותר ממשחק","text":"דרך משחק אפשר לפגוש תסכול, פחד, תחרות, אכזבה, הצלחה וכישלון, בסביבה שבה יש מקום לטעות, לנסות שוב ולגלות דברים חדשים."},{"id":"article-paragraph-0e58257c73f7","heading":"משחק הוא הרבה יותר ממשחק","text":"וזה מתחבר מאוד לעבודה עם כלבים."},{"id":"article-paragraph-1ab78bcc399c","heading":"משחק הוא הרבה יותר ממשחק","text":"למשל, ילד שמתקשה להתמודד עם תסכול יכול להשתתף במשחק שבו הוא צריך להוביל את הכלב במסלול מסוים. הכלב לא תמיד יפעל בדיוק כפי שהילד רוצה, ולפעמים המשימה לא תצליח."},{"id":"article-paragraph-ec2c6bf44626","heading":"משחק הוא הרבה יותר ממשחק","text":"אפשר כמובן להפוך את הרגע הזה לשיעור על סבלנות או שליטה בכעסים. אבל אפשר גם להסתכל עליו אחרת."},{"id":"article-paragraph-dc8bc0fe117b","heading":"משחק הוא הרבה יותר ממשחק","text":"אולי הילד כרגע מוצף מדי מכדי ללמוד משהו? אולי הוא צריך קודם כול שנעזור לו להתמודד עם האכזבה? ואולי דווקא משחקיות, הומור או שינוי קטן במשימה יאפשרו לו להמשיך בלי להרגיש שהוא נכשל?"},{"id":"article-paragraph-896fc3ee8e7f","heading":"משחק הוא הרבה יותר ממשחק","text":"במקום להתמקד רק בהתנהגות שאנחנו רוצים לשנות, אנחנו מנסים להבין מה הילד מסוגל לשאת באותו רגע ומה יכול לעזור לו להתקדם."},{"id":"article-heading-263c4c9c5195","heading":"לא כל התנגדות היא בעיית משמעת","text":"לא כל התנגדות היא בעיית משמעת"},{"id":"article-paragraph-c7acab418b4f","heading":"לא כל התנגדות היא בעיית משמעת","text":"אחד המושגים המעניינים בגישה של ניופלד הוא רצון נגדי (Counterwill), שמתאר נטייה טבעית להתנגד כשאנחנו מרגישים שמישהו אחר מנסה לכפות עלינו את רצונו."},{"id":"article-paragraph-89be02364eb8","heading":"לא כל התנגדות היא בעיית משמעת","text":"לפעמים ילד מתנגד לא בגלל שהוא לא רוצה להשתתף או לא מסוגל לעשות את מה שמבקשים ממנו, אלא דווקא משום שהוא מרגיש שמנסים להפעיל עליו לחץ או לקחת ממנו את השליטה."},{"id":"article-paragraph-57ecd71d4a98","heading":"לא כל התנגדות היא בעיית משמעת","text":"אני נזכר בילדה בת 6 שטיפלתי בה. כבר מהמפגשים הראשונים היא הייתה משתלטת על המפגש, וכל ניסיון שלי להוביל או להציע פעילות נתקל בהתנגדות. לאורך תקופה ניסיתי לאתגר את המקום הזה, מתוך מחשבה שהיא צריכה ללמוד להתמודד גם עם מצבים שבהם היא לא זאת שמחליטה."},{"id":"article-paragraph-f6ceb30812cf","heading":"לא כל התנגדות היא בעיית משמעת","text":"אבל ככל שניסיתי להוביל, כך היא התרחקה מהתהליך."},{"id":"article-paragraph-2491ea3c1b9d","heading":"לא כל התנגדות היא בעיית משמעת","text":"באחד המפגשים החלטתי לנסות משהו אחר. אמרתי לה שהיום היא מחליטה הכול. אני לא שואל שאלות ולא בוחר מה עושים. היא קובעת."},{"id":"article-paragraph-1c3c08b5dd1d","heading":"לא כל התנגדות היא בעיית משמעת","text":"בהתחלה היא הייתה מבולבלת ואפילו שאלה למה. אבל אחרי שהבינה שאני רציני, היא התחילה לחייך, בחרה משחק והכריזה שנשחק \"המלך אמר\" (אפרופו ענייני שליטה)."},{"id":"article-paragraph-cf6ce5829283","heading":"לא כל התנגדות היא בעיית משמעת","text":"תוך כדי המשחק קרה משהו מעניין. בלי שביקשתי, היא התחילה לספר לי על השבוע שלה, ואפילו ביקשה לעבוד עם הכלבים. דברים שקודם היה קשה להגיע אליהם התחילו לקרות באופן טבעי."},{"id":"article-paragraph-ae72af0683b2","heading":"לא כל התנגדות היא בעיית משמעת","text":"זה היה אחד המפגשים המשמעותיים שהיו לנו. דווקא כשוויתרתי על הניסיון להוביל את המפגש, נוצר יותר מקום לקשר ולשיתוף פעולה."},{"id":"article-paragraph-cf867b21889a","heading":"לא כל התנגדות היא בעיית משמעת","text":"במפגש שאחריו היא כבר אמרה לי: \"גם היום אני רוצה להחליט\". וכשהגיע הזמן לבחור משחק, היא הוסיפה: \"אני רוצה שאתה תבחר\"."},{"id":"article-paragraph-6f8a844c5e3f","heading":"לא כל התנגדות היא בעיית משמעת","text":"היא לא ויתרה על הצורך שלה בשליטה כי דרשתי ממנה לעשות את זה. היא הצליחה לשחרר קצת ממנו דווקא כשהרגישה שהבחירה נמצאת בידיים שלה."},{"id":"article-paragraph-d51ec5aa2837","heading":"לא כל התנגדות היא בעיית משמעת","text":"כמובן, לא כל התנגדות היא בהכרח רצון נגדי. לפעמים היא נובעת מחרדה, מקושי בוויסות, מחוסר אמון או מצרכים אחרים. אבל הסיפור הזה מזכיר לי כמה חשוב לא למהר להיאבק בהתנגדות, אלא לנסות להבין מה עומד מאחוריה."},{"id":"article-paragraph-098fe35c7446","heading":"לא כל התנגדות היא בעיית משמעת","text":"בטיפול בעזרת כלבים יש לנו הרבה אפשרויות לעשות את זה דרך משחק, בחירה והתנסות משותפת, בלי שכל דבר יהפוך לדרישה או למשימה שצריך לבצע."},{"id":"article-heading-b41151e81947","heading":"גם לתסכול ולעצב יש מקום","text":"גם לתסכול ולעצב יש מקום"},{"id":"article-paragraph-c124dcb0bad6","heading":"גם לתסכול ולעצב יש מקום","text":"בעבודה טיפולית אנחנו רוצים לעזור למטופלים להתמודד טוב יותר עם רגשות קשים. אבל לא תמיד המטרה היא להעלים את הרגש או להפסיק אותו במהירות."},{"id":"article-paragraph-c4f1679dc220","heading":"גם לתסכול ולעצב יש מקום","text":"בגישה ההתפתחותית-היקשרותית יש חשיבות ליכולת לפגוש גם רגשות פגיעים, כמו עצב, אכזבה וחוסר אונים, במקום להישאר רק עם הכעס או ההתנגדות שמופיעים כלפי חוץ."},{"id":"article-paragraph-c2bda6b33b76","heading":"גם לתסכול ולעצב יש מקום","text":"למשל, ילד שמנסה שוב ושוב להצליח במשימה עם הכלב ולא מצליח, עלול להתפרץ בכעס ולהאשים את הכלב."},{"id":"article-paragraph-c2015a5f0fad","heading":"גם לתסכול ולעצב יש מקום","text":"אפשר לעבוד איתו על הדרך שבה הוא מבטא את הכעס, וזה בהחלט חשוב."},{"id":"article-paragraph-be6e32039337","heading":"גם לתסכול ולעצב יש מקום","text":"אבל אפשר גם לנסות להבין מה יש מתחת לכעס הזה. אולי הוא מאוד רצה להצליח? אולי קשה לו להרגיש שהוא לא מסוגל? אולי הוא מאוכזב מעצמו?"},{"id":"article-paragraph-0d0a1596007f","heading":"גם לתסכול ולעצב יש מקום","text":"לפעמים, כשהילד מצליח לפגוש את האכזבה ולקבל אותה בתוך קשר בטוח, מתאפשרת גם תגובה גמישה יותר."},{"id":"article-paragraph-43cb2dc35cc6","heading":"גם לתסכול ולעצב יש מקום","text":"התפקיד שלנו הוא לא למנוע כל תסכול, אלא לעזור למטופל לפגוש אותו בלי להישאר איתו לבד."},{"id":"article-heading-4e7bb288c889","heading":"ומה לגבי הקשר עם הכלב עצמו?","text":"ומה לגבי הקשר עם הכלב עצמו?"},{"id":"article-paragraph-10517a6fdcf5","heading":"ומה לגבי הקשר עם הכלב עצמו?","text":"הקשר עם הכלב יכול להפוך לחלק משמעותי מאוד מהתהליך."},{"id":"article-paragraph-068cc7575c5d","heading":"ומה לגבי הקשר עם הכלב עצמו?","text":"יש מטופלים שמרגישים בנוח יותר להביע חיבה כלפי הכלב, להתקרב אליו או לשתף אותו במה שעובר עליהם."},{"id":"article-paragraph-9c1ebf83f586","heading":"ומה לגבי הקשר עם הכלב עצמו?","text":"אפשר להיעזר בקשר הזה כדי לעבוד על אמון, קרבה, גבולות, אמפתיה ותחושת ביטחון."},{"id":"article-paragraph-c9d3075120a0","heading":"ומה לגבי הקשר עם הכלב עצמו?","text":"אבל חשוב להבחין בין קשר משמעותי עם כלב לבין התקשרות בטוחה עם דמות אנושית. אלה לא בהכרח אותם דברים."},{"id":"article-paragraph-891288fdc53b","heading":"ומה לגבי הקשר עם הכלב עצמו?","text":"הכלב יכול להיות מקור לנחמה ולקרבה, אבל הוא לא מחליף את הצורך בקשרים אנושיים משמעותיים."},{"id":"article-paragraph-7675336b538a","heading":"ומה לגבי הקשר עם הכלב עצמו?","text":"מבחינתי, המטרה היא לא שהמטופל יהיה תלוי בכלב כדי להרגיש בטוח, אלא שהקשר איתו יסייע לנו ליצור חוויות שאפשר יהיה בהמשך להרחיב גם לקשרים ולמצבים אחרים בחיים."},{"id":"article-paragraph-f468ca01bdac","heading":"ומה לגבי הקשר עם הכלב עצמו?","text":"יש גם חשיבות לדרך שבה אנחנו מתייחסים לכלב. כשאנחנו מכבדים את הצרכים שלו, מזהים מתי הוא רוצה להתקרב ומתי הוא זקוק למרחב, אנחנו מדגימים קשר שיש בו הקשבה, התחשבות וגבולות."},{"id":"article-heading-640d560d29fa","heading":"אז מה זה משנה בפועל?","text":"אז מה זה משנה בפועל?"},{"id":"article-paragraph-7e0fca17591d","heading":"אז מה זה משנה בפועל?","text":"הגישה ההתפתחותית-היקשרותית לא בהכרח משנה את הפעילויות שאנחנו עושים בטיפול, אלא בעיקר את הדרך שבה אנחנו מבינים אותן ואת המטרות שאנחנו מנסים לקדם."},{"id":"article-paragraph-f252c871fffa","heading":"אז מה זה משנה בפועל?","text":"אפשר להשתמש באותו משחק עם הכלב כדי ללמד ילד לחכות לתורו, אבל אפשר גם להשתמש בו כדי להבין למה כל כך קשה לו לחכות, מה קורה לו כשהוא מאבד שליטה ואיך אפשר לעזור לו לשאת את התסכול."},{"id":"article-paragraph-d1641e07ef38","heading":"אז מה זה משנה בפועל?","text":"אפשר להתמקד בכך שהילד יבצע משימה בהצלחה, ואפשר להתמקד בכך שהוא ירגיש מספיק בטוח כדי לנסות, גם אם לא יצליח."},{"id":"article-paragraph-cee37c5e00f0","heading":"אז מה זה משנה בפועל?","text":"שתי האפשרויות לא בהכרח סותרות זו את זו. השאלה היא מה המטופל צריך באותו שלב של התהליך."},{"id":"article-paragraph-83e35a44ef09","heading":"אז מה זה משנה בפועל?","text":"חשוב גם לזכור שלא כל קושי נובע מבעיה בהתקשרות, ולא כל מטופל זקוק לאותה התערבות. לפעמים יש צורך בלמידת מיומנויות מפורשת, בהדרכה התנהגותית או בהתערבויות נוספות. ההסתכלות ההתפתחותית יכולה להשתלב בהן ולעזור לנו להבין מתי ואיך נכון להשתמש בהן."},{"id":"article-heading-6c042377fbb2","heading":"לא רק לשנות התנהגות, אלא לאפשר התפתחות","text":"לא רק לשנות התנהגות, אלא לאפשר התפתחות"},{"id":"article-paragraph-6aae42f139e1","heading":"לא רק לשנות התנהגות, אלא לאפשר התפתחות","text":"אני חושב שאחד החיבורים המשמעותיים בין הגישה ההתפתחותית-היקשרותית לטיפול בעזרת כלבים הוא ההבנה שלא כל שינוי צריך להתחיל בדרישה להשתנות."},{"id":"article-paragraph-cc316399fe2f","heading":"לא רק לשנות התנהגות, אלא לאפשר התפתחות","text":"לפעמים הוא מתחיל דווקא בתחושת ביטחון, בקשר שנוצר, במשחק משותף או בחוויה שבה מותר לנו לטעות ולהיות מי שאנחנו."},{"id":"article-paragraph-8e9f30793e20","heading":"לא רק לשנות התנהגות, אלא לאפשר התפתחות","text":"הכלב יכול לעזור לנו ליצור את התנאים האלה. הוא מאפשר מפגש פחות פורמלי, מזמין למשחק ולהתנסות, ולעיתים מצליח לעורר קרבה גם במקומות שבהם שיחה ישירה פחות מתאימה."},{"id":"article-paragraph-2aac902f38b9","heading":"לא רק לשנות התנהגות, אלא לאפשר התפתחות","text":"אבל הכלב הוא לא זה שאחראי להתפתחות, וגם לא כל פעילות איתו מקדמת אותה באופן אוטומטי."},{"id":"article-paragraph-f37141b4fda8","heading":"לא רק לשנות התנהגות, אלא לאפשר התפתחות","text":"התפקיד שלנו כמטפלים הוא להבין את האדם שמולנו, לזהות את הצרכים שלו וליצור עבורו סביבה שבה הוא יוכל להרגיש בטוח, להתנסות ולהתפתח."},{"id":"article-paragraph-6a68aa5e5656","heading":"לא רק לשנות התנהגות, אלא לאפשר התפתחות","text":"כי לפעמים, לפני שאנחנו מנסים ללמד אדם להתמודד אחרת, אנחנו צריכים קודם כול לאפשר לו להרגיש מספיק בטוח כדי להתמודד."},{"id":"article-reference-0856710187ea","heading":"מקורות","text":"Gordon Neufeld – The Attachment-Based Developmental Approach. הסבר על עקרונות הגישה ההתפתחותית-היקשרותית."},{"id":"article-reference-7f3fe1e96804","heading":"מקורות","text":"Neufeld Institute – Play & Attachment. על תפקיד המשחק ביצירת קשר ובהתפתחות."},{"id":"article-reference-20828ac19596","heading":"מקורות","text":"Zilcha-Mano, Mikulincer & Shaver (2011) Pet in the Therapy Room: An Attachment Perspective on Animal-Assisted Therapy. מאמר תיאורטי המציע מסגרת להבנת טיפול בעזרת בעלי חיים דרך תיאוריית ההתקשרות."},{"id":"article-reference-ecb359c29924","heading":"מקורות","text":"Bowlby, J. (1988) A Secure Base: Parent-Child Attachment and Healthy Human Development. ספר יסוד על התקשרות וביטחון כבסיס להתפתחות."}]},{"title":"ויסות רגשי אצל ילדים - איך טיפול בעזרת כלבים יכול לעזור?","url":"https://derech-hakelev.com/pages/articles/emotional-regulation-children-dog-therapy/","entries":[{"id":"article-title-b285b2411636","heading":"תחילת המאמר","text":"ויסות רגשי אצל ילדים - איך טיפול בעזרת כלבים יכול לעזור?"},{"id":"article-paragraph-d0ad13e1a760","heading":"פתיחת המאמר","text":"הילד מתפרץ כשמשהו לא מסתדר כמו שרצה? מתקשה להפסיד במשחק? מגיב בעוצמה גדולה לתסכול או לאכזבה? לפעמים אפילו דבר קטן יכול להוביל לבכי, לכעס או להתפרצות שנראית לא פרופורציונלית למצב."},{"id":"article-paragraph-e281ee9b19e3","heading":"פתיחת המאמר","text":"לא מעט הורים מתמודדים עם מצבים כאלה. אחד הדברים המתסכלים הוא שלפעמים הילד דווקא יודע להסביר מה היה צריך לעשות אחרת. הוא יודע שלא כדאי לצעוק, להרביץ או לזרוק דברים. ובכל זאת, ברגע האמת, כשהרגש מציף אותו, הוא מתקשה לפעול אחרת."},{"id":"article-paragraph-e0a9763feb1c","heading":"פתיחת המאמר","text":"זה אחד הדברים המשמעותיים בעבודה על ויסות רגשי אצל ילדים: הפער שבין הידיעה מה נכון לעשות לבין היכולת לעשות זאת בזמן אמת."},{"id":"article-paragraph-33e69ae78308","heading":"פתיחת המאמר","text":"בטיפול רגשי בעזרת כלבים אפשר לעבוד על הפער הזה בדרך חווייתית, דרך משחק, קשר והתנסויות שמזמנות רגשות אמיתיים בתוך מרחב טיפולי בטוח."},{"id":"article-heading-dab27643f2d0","heading":"מה זה ויסות רגשי אצל ילדים?","text":"מה זה ויסות רגשי אצל ילדים?"},{"id":"article-paragraph-5bd7268a89e7","heading":"מה זה ויסות רגשי אצל ילדים?","text":"ויסות רגשי הוא היכולת לזהות רגשות, להתמודד איתם ולהשפיע על הדרך שבה אנחנו מגיבים להם."},{"id":"article-paragraph-571219a87ab0","heading":"מה זה ויסות רגשי אצל ילדים?","text":"חשוב לי להדגיש שוויסות רגשי לא אומר להיות רגועים כל הזמן. ילד שמצליח לווסת את רגשותיו הוא לא ילד שלא כועס, לא בוכה או לא מתוסכל."},{"id":"article-paragraph-eff593995fa7","heading":"מה זה ויסות רגשי אצל ילדים?","text":"לכעס, לפחד, לתסכול ולאכזבה יש מקום חשוב בחיים שלנו. המטרה היא לא להעלים אותם, אלא לפתח את היכולת לשאת אותם ולהתמודד איתם."},{"id":"article-paragraph-60c27ebf4e5d","heading":"מה זה ויסות רגשי אצל ילדים?","text":"לדוגמה, ילד יכול לכעוס מאוד כשהוא מפסיד במשחק, ועדיין להצליח להישאר במשחק. הוא יכול להיעלב מחבר מבלי להגיב באלימות, או להתאכזב כשמשהו לא מצליח ולמצוא את הכוחות לנסות שוב."},{"id":"article-paragraph-5e924579d40a","heading":"מה זה ויסות רגשי אצל ילדים?","text":"היכולות האלה מתפתחות בהדרגה. ילדים לא נולדים עם יכולת מלאה לווסת את רגשותיהם, והם זקוקים למבוגרים שיעזרו להם לעשות זאת."},{"id":"article-paragraph-cd8b58671591","heading":"מה זה ויסות רגשי אצל ילדים?","text":"לכן, כשילד מתקשה להתמודד עם הרגשות שלו, לא תמיד מדובר בבחירה להתנהג בצורה מסוימת. לפעמים היכולת הנדרשת ממנו עדיין נמצאת בתהליך התפתחות."},{"id":"article-heading-623109c655e7","heading":"איך נראים קשיי ויסות רגשי אצל ילדים?","text":"איך נראים קשיי ויסות רגשי אצל ילדים?"},{"id":"article-paragraph-4eba88c5241a","heading":"איך נראים קשיי ויסות רגשי אצל ילדים?","text":"קשיים בוויסות רגשי יכולים להתבטא בדרכים שונות."},{"id":"article-paragraph-1036b31aa14b","heading":"איך נראים קשיי ויסות רגשי אצל ילדים?","text":"יש ילדים שמגיבים בתוקפנות או בהתפרצויות זעם, ואחרים דווקא מתכנסים בתוך עצמם, נמנעים מהתמודדויות או מתקשים לשתף במה שהם מרגישים."},{"id":"article-paragraph-969fe496023f","heading":"איך נראים קשיי ויסות רגשי אצל ילדים?","text":"הקשיים יכולים לבוא לידי ביטוי במצבים כמו:"},{"id":"article-item-3b94fab79712","heading":"איך נראים קשיי ויסות רגשי אצל ילדים?","text":"התפרצויות כעס בעקבות הצבת גבולות או קבלת תשובה שלילית."},{"id":"article-item-1a605867aef7","heading":"איך נראים קשיי ויסות רגשי אצל ילדים?","text":"קושי להפסיד במשחק או להתמודד עם כישלון."},{"id":"article-item-a63b4e2dad24","heading":"איך נראים קשיי ויסות רגשי אצל ילדים?","text":"תגובות רגשיות עוצמתיות לשינויים בלתי צפויים."},{"id":"article-item-5be854ec9c31","heading":"איך נראים קשיי ויסות רגשי אצל ילדים?","text":"קושי לחכות לתור, לדחות סיפוקים או להתאפק."},{"id":"article-item-74198f69d13a","heading":"איך נראים קשיי ויסות רגשי אצל ילדים?","text":"קושי להירגע גם לאחר שהאירוע הסתיים."},{"id":"article-item-5508fedd4b57","heading":"איך נראים קשיי ויסות רגשי אצל ילדים?","text":"הימנעות מהתנסויות חדשות מתוך פחד להיכשל."},{"id":"article-paragraph-7d44513903e3","heading":"איך נראים קשיי ויסות רגשי אצל ילדים?","text":"חשוב לזכור שלא כל התפרצות מעידה על בעיה בוויסות הרגשי. ילדים חווים כעס ותסכול כחלק מההתפתחות הטבעית שלהם. השאלה היא עד כמה הקושי חוזר על עצמו, עד כמה הוא עוצמתי וכיצד הוא משפיע על התפקוד ועל מערכות היחסים של הילד."},{"id":"article-heading-53a5e290707b","heading":"איך טיפול רגשי בעזרת כלבים יכול לעזור?","text":"איך טיפול רגשי בעזרת כלבים יכול לעזור?"},{"id":"article-paragraph-8ac6ae2060c9","heading":"איך טיפול רגשי בעזרת כלבים יכול לעזור?","text":"אחד הדברים שאני אוהב בעבודה הטיפולית עם כלבים הוא שהרבה פעמים אנחנו לא צריכים ליצור באופן מלאכותי סיטואציה כדי לעבוד על קושי רגשי. הסיטואציות נוצרות מתוך הפעילות המשותפת."},{"id":"article-paragraph-ed510b5fc7f6","heading":"איך טיפול רגשי בעזרת כלבים יכול לעזור?","text":"נניח שילד מנסה ללמד את הכלב לבצע תרגיל מסוים. הוא מבקש ממנו לשבת, לעבור במסלול או לבצע משימה אחרת, אבל הכלב לא משתף פעולה כפי שציפה."},{"id":"article-paragraph-5e6a079639a2","heading":"איך טיפול רגשי בעזרת כלבים יכול לעזור?","text":"אולי הילד ינסה שוב בסבלנות. אולי יתעצבן, ירים את הקול או יחליט שהוא לא רוצה להמשיך."},{"id":"article-paragraph-1e0521c00bfd","heading":"איך טיפול רגשי בעזרת כלבים יכול לעזור?","text":"מבחוץ זו יכולה להיראות כמו פעילות פשוטה עם כלב, אבל מבחינה טיפולית מתרחש כאן משהו משמעותי."},{"id":"article-paragraph-4dc89d53d501","heading":"איך טיפול רגשי בעזרת כלבים יכול לעזור?","text":"הילד פוגש תסכול אמיתי."},{"id":"article-paragraph-77e63c60c3af","heading":"איך טיפול רגשי בעזרת כלבים יכול לעזור?","text":"עכשיו אפשר להתבונן יחד במה שקרה. מה הוא הרגיש כשהכלב לא עשה את מה שביקש? מה הוא רצה לעשות באותו רגע? האם הוא מסוגל לנסות שוב, לשנות את הדרך שבה פנה לכלב או להיעזר בי?"},{"id":"article-paragraph-fbddcab56605","heading":"איך טיפול רגשי בעזרת כלבים יכול לעזור?","text":"העבודה היא לא על כך שהכלב יבצע את התרגיל, אלא על מה שהילד עובר בדרך."},{"id":"article-heading-82d9b826d0bd","heading":"לעבוד על תסכול בלי לנסות למנוע אותו","text":"לעבוד על תסכול בלי לנסות למנוע אותו"},{"id":"article-paragraph-10dc5bde15c0","heading":"לעבוד על תסכול בלי לנסות למנוע אותו","text":"הרבה פעמים אנחנו רוצים לחסוך מילדים תסכול. אנחנו מנסים לעזור להם להצליח, למנוע מהם להפסיד או לפתור עבורם בעיות לפני שיתאכזבו."},{"id":"article-paragraph-c2e39082eadc","heading":"לעבוד על תסכול בלי לנסות למנוע אותו","text":"זה מובן, אבל היכולת להתמודד עם תסכול מתפתחת גם דרך ההתנסות בו, כשהילד מקבל תמיכה שמתאימה ליכולות שלו."},{"id":"article-paragraph-69baa9fcc962","heading":"לעבוד על תסכול בלי לנסות למנוע אותו","text":"בטיפול בעזרת כלבים יש הרבה הזדמנויות כאלה."},{"id":"article-paragraph-b434f469d676","heading":"לעבוד על תסכול בלי לנסות למנוע אותו","text":"לא כל משימה מצליחה בניסיון הראשון. לפעמים הכלב בוחר לעשות משהו אחר, לפעמים צריך לחכות, ולפעמים צריך לשנות את התוכנית."},{"id":"article-paragraph-264b28b86ee8","heading":"לעבוד על תסכול בלי לנסות למנוע אותו","text":"המטרה שלי היא לא לגרום לילד להתעצבן בכוונה, וגם לא להציף אותו מעבר למה שהוא מסוגל לשאת. המטרה היא לאפשר לו להתמודד עם אתגרים מתאימים, וללוות אותו בתוכם."},{"id":"article-paragraph-ee89b6098589","heading":"לעבוד על תסכול בלי לנסות למנוע אותו","text":"לפעמים ההישג המשמעותי ביותר במפגש הוא לא שהילד הצליח במשימה, אלא שהוא התאכזב, כעס, הצליח להתמודד עם הרגש ובחר לנסות שוב."},{"id":"article-heading-21b039df974e","heading":"ללמוד לזהות את הרגש דרך הכלב","text":"ללמוד לזהות את הרגש דרך הכלב"},{"id":"article-paragraph-090d99fa941e","heading":"ללמוד לזהות את הרגש דרך הכלב","text":"אחד השלבים החשובים בדרך לוויסות רגשי הוא היכולת להכיר את מה שאנחנו מרגישים."},{"id":"article-paragraph-add08324584e","heading":"ללמוד לזהות את הרגש דרך הכלב","text":"אצל ילדים, זה לא תמיד פשוט. לפעמים הם מרגישים כעס או פחד בעוצמה גדולה, אבל מתקשים לזהות את התחושה או להסביר מה קורה להם."},{"id":"article-paragraph-66125675f21c","heading":"ללמוד לזהות את הרגש דרך הכלב","text":"הכלבים מאפשרים לנו להתחיל את השיחה ממקום אחר."},{"id":"article-paragraph-9ef2ff95bb19","heading":"ללמוד לזהות את הרגש דרך הכלב","text":"אפשר להתבונן בכלב ולשאול: איך אנחנו יודעים שהוא מתרגש? איך הוא נראה כשהוא נינוח? מה הוא עושה כשהוא רוצה מרחב? איך אפשר לזהות שהוא מתוח?"},{"id":"article-paragraph-499a3ca2e9f0","heading":"ללמוד לזהות את הרגש דרך הכלב","text":"משם אפשר לעבור בהדרגה אל הילד."},{"id":"article-paragraph-ca4db6f9388b","heading":"ללמוד לזהות את הרגש דרך הכלב","text":"איך אתה מרגיש בגוף כשאתה כועס? מה אתה עושה כשאתה מתרגש? איך אפשר לזהות שאתה מתחיל להתעצבן, עוד לפני שהכעס נעשה חזק מאוד?"},{"id":"article-paragraph-85974b2ed2d2","heading":"ללמוד לזהות את הרגש דרך הכלב","text":"לפעמים הרבה יותר קל לילד לדבר קודם על הכלב, ורק אחר כך על עצמו."},{"id":"article-heading-6b910c7c11c1","heading":"משחק, המתנה וגמישות","text":"משחק, המתנה וגמישות"},{"id":"article-paragraph-d61ade97c203","heading":"משחק, המתנה וגמישות","text":"משחק הוא חלק משמעותי מהעבודה שלי עם ילדים, גם כשאין בו פעילות ישירה עם הכלב."},{"id":"article-paragraph-97b708114afe","heading":"משחק, המתנה וגמישות","text":"במשחק אנחנו פוגשים באופן טבעי מצבים של המתנה, הפסד, שינוי כללים, חוסר ודאות והתמודדות עם רצונות של אחרים."},{"id":"article-paragraph-29b2170bd194","heading":"משחק, המתנה וגמישות","text":"כשמשלבים גם כלב, מתווספת מערכת יחסים עם יצור חי שיש לו רצונות, צרכים וקצב משלו."},{"id":"article-paragraph-67cf9b6c1dcf","heading":"משחק, המתנה וגמישות","text":"הילד לא יכול לשלוט בכל מה שהכלב עושה. הוא צריך לפעמים לחכות, להתאים את עצמו, להתחשב ולמצוא דרך אחרת להשיג את המטרה שלו."},{"id":"article-paragraph-204f5c7608a4","heading":"משחק, המתנה וגמישות","text":"אלה הזדמנויות לעבוד על גמישות, סבלנות והתמודדות עם תסכול."},{"id":"article-paragraph-e11e4b170428","heading":"משחק, המתנה וגמישות","text":"אבל גם כאן, לא כל פעילות עם כלב היא בהכרח טיפולית. מה שהופך אותה לחלק מתהליך טיפולי הוא הקשר למטרות של הילד והאופן שבו אנחנו מתייחסים למה שמתרחש."},{"id":"article-heading-81155c2e0030","heading":"לפני שמלמדים ילד להירגע, חשוב שיהיה לו עם מי להירגע","text":"לפני שמלמדים ילד להירגע, חשוב שיהיה לו עם מי להירגע"},{"id":"article-paragraph-81de9ce20ffb","heading":"לפני שמלמדים ילד להירגע, חשוב שיהיה לו עם מי להירגע","text":"אחד הדברים החשובים בעיניי בעבודה על ויסות רגשי הוא להבין שהיכולת הזאת מתפתחת בתוך קשר."},{"id":"article-paragraph-1313101be279","heading":"לפני שמלמדים ילד להירגע, חשוב שיהיה לו עם מי להירגע","text":"כשילד מוצף רגשית, לא תמיד יש לו באותו רגע יכולת לעצור, לחשוב ולהשתמש בכלים שכבר למד."},{"id":"article-paragraph-693dd89410ca","heading":"לפני שמלמדים ילד להירגע, חשוב שיהיה לו עם מי להירגע","text":"לפעמים הוא זקוק קודם כול למבוגר שיצליח להישאר רגוע יחסית מול הסערה שלו, להבין את הקושי ולעזור לו לחזור בהדרגה למצב שבו הוא מסוגל לחשוב ולפעול."},{"id":"article-paragraph-45e7e722c1cd","heading":"לפני שמלמדים ילד להירגע, חשוב שיהיה לו עם מי להירגע","text":"התהליך הזה נקרא ויסות משותף (Co-regulation)."},{"id":"article-paragraph-b9a4cdd9c751","heading":"לפני שמלמדים ילד להירגע, חשוב שיהיה לו עם מי להירגע","text":"בטיפול, הקשר עם המטפל הוא הבסיס שמאפשר את העבודה הזאת."},{"id":"article-paragraph-5748af3d8681","heading":"לפני שמלמדים ילד להירגע, חשוב שיהיה לו עם מי להירגע","text":"הכלב יכול לעזור ביצירת קשר, לעורר תחושת ביטחון, לאפשר קרבה ולהפוך את המפגש לפחות מאיים עבור חלק מהילדים. לפעמים הנוכחות שלו גם מאפשרת לילד להביע דברים שהוא מתקשה להגיד בשיחה ישירה."},{"id":"article-paragraph-07a113fc92f7","heading":"לפני שמלמדים ילד להירגע, חשוב שיהיה לו עם מי להירגע","text":"אבל המטרה היא לא שהילד יהיה תלוי בכלב כדי להירגע. אנחנו רוצים לעזור לו לפתח, בהדרגה, את היכולת להתמודד עם רגשותיו גם במצבים אחרים בחיים."},{"id":"article-heading-c03771f69452","heading":"ומה קורה כשהילד מתפרץ דווקא במהלך הטיפול?","text":"ומה קורה כשהילד מתפרץ דווקא במהלך הטיפול?"},{"id":"article-paragraph-a5b22a965ca9","heading":"ומה קורה כשהילד מתפרץ דווקא במהלך הטיפול?","text":"גם במהלך מפגש טיפולי יכולים להיות רגעים של כעס, התנגדות, בכי או תסכול."},{"id":"article-paragraph-6c6d9411a05f","heading":"ומה קורה כשהילד מתפרץ דווקא במהלך הטיפול?","text":"מבחינתי, אלה לא בהכרח רגעים שבהם הטיפול לא הצליח. לפעמים דווקא בהם מתאפשרת עבודה משמעותית."},{"id":"article-paragraph-f7a7d43b962e","heading":"ומה קורה כשהילד מתפרץ דווקא במהלך הטיפול?","text":"כשילד מתפרץ, לא תמיד הדבר הנכון הוא למהר להסביר לו איך היה צריך להתנהג או לדרוש ממנו להירגע מיד."},{"id":"article-paragraph-19d74914cdaf","heading":"ומה קורה כשהילד מתפרץ דווקא במהלך הטיפול?","text":"לפעמים חשוב קודם כול להבין מה הציף אותו, לעזור לו לשאת את הרגש ולתת לו תחושה שהוא לא נשאר לבד עם הקושי."},{"id":"article-paragraph-d081b5aa80ae","heading":"ומה קורה כשהילד מתפרץ דווקא במהלך הטיפול?","text":"רק כשהוא פנוי לכך, אפשר לחשוב יחד על מה שהיה ולנסות להבין מה יכול לעזור בפעם הבאה."},{"id":"article-paragraph-8d1e2f02eb1f","heading":"ומה קורה כשהילד מתפרץ דווקא במהלך הטיפול?","text":"כמובן, חלק מהאחריות שלי במפגשים היא גם לשמור על הכלבים. אם הילד מוצף מאוד, חשוב לדאוג למרחב בטוח עבור כולם ולא לצפות מהכלב לשאת התנהגות שעלולה להלחיץ אותו או לפגוע בו."},{"id":"article-heading-d32ad1172084","heading":"איך אפשר לעזור לילד לפתח ויסות רגשי גם בבית?","text":"איך אפשר לעזור לילד לפתח ויסות רגשי גם בבית?"},{"id":"article-paragraph-0e466af0a5e6","heading":"איך אפשר לעזור לילד לפתח ויסות רגשי גם בבית?","text":"העבודה על ויסות רגשי לא מסתיימת בחדר הטיפול, ולהורים יש תפקיד משמעותי מאוד בתהליך."},{"id":"article-paragraph-409d68c02370","heading":"איך אפשר לעזור לילד לפתח ויסות רגשי גם בבית?","text":"כשהילד כועס, אפשר לנסות לראות מעבר להתנהגות ולהבין מה הוא חווה. זה לא אומר לוותר על גבולות או לקבל פגיעה באחרים."},{"id":"article-paragraph-df769a220e54","heading":"איך אפשר לעזור לילד לפתח ויסות רגשי גם בבית?","text":"אפשר להגיד לילד שמותר לו לכעוס, אבל אסור לו להרביץ. אפשר להבין שהוא מאוכזב ובו בזמן לשמור על הגבול שהצבנו."},{"id":"article-paragraph-fd047a96296d","heading":"איך אפשר לעזור לילד לפתח ויסות רגשי גם בבית?","text":"כשהוא מוצף, כדאי להתאים את התגובה למצב שלו. לפעמים הוא זקוק לנוכחות ולסיוע ברגיעה יותר משהוא זקוק להסבר."},{"id":"article-paragraph-3943ec22c6d9","heading":"איך אפשר לעזור לילד לפתח ויסות רגשי גם בבית?","text":"אחרי שהסערה חולפת, אפשר לחזור יחד למה שקרה, לזהות את הקושי ולחשוב על דרכים נוספות להתמודד."},{"id":"article-paragraph-7b55fedd17cb","heading":"איך אפשר לעזור לילד לפתח ויסות רגשי גם בבית?","text":"חשוב גם לשים לב להצלחות הקטנות: ילד שהצליח לחכות עוד רגע, שלא ויתר אחרי כישלון, שביקש עזרה במקום להתפרץ או שהצליח לחזור למשחק לאחר שהתאכזב."},{"id":"article-paragraph-145ef11bf572","heading":"איך אפשר לעזור לילד לפתח ויסות רגשי גם בבית?","text":"ההצלחות האלה הן חלק מתהליך ההתפתחות, גם אם מבחוץ הן לא תמיד נראות גדולות."},{"id":"article-heading-ebbc5c9360e0","heading":"לסיכום – המטרה היא לא ילד שלא כועס","text":"לסיכום – המטרה היא לא ילד שלא כועס"},{"id":"article-paragraph-a8c7db91ba15","heading":"לסיכום – המטרה היא לא ילד שלא כועס","text":"כשאנחנו עובדים על ויסות רגשי אצל ילדים, אנחנו לא מנסים להעלים את הכעס, הפחד או התסכול."},{"id":"article-paragraph-b5cdee9c7096","heading":"לסיכום – המטרה היא לא ילד שלא כועס","text":"אנחנו רוצים לעזור לילדים להכיר את הרגשות שלהם, לשאת אותם, להיעזר באחרים כשצריך ולפתח בהדרגה את היכולת לבחור איך להגיב."},{"id":"article-paragraph-0f4100162119","heading":"לסיכום – המטרה היא לא ילד שלא כועס","text":"בטיפול רגשי בעזרת כלבים, הקשר עם הכלב, המשחק וההתנסויות המשותפות מאפשרים לפגוש את הקשיים האלה בדרך חווייתית."},{"id":"article-paragraph-2d4c1628aa15","heading":"לסיכום – המטרה היא לא ילד שלא כועס","text":"לא רק לדבר על תסכול, אלא להתמודד איתו. לא רק להסביר מהי סבלנות, אלא להתנסות בה. ולא רק ללמוד מה נכון לעשות כשכועסים, אלא לקבל הזדמנות לפתח את היכולת הזאת בתוך קשר טיפולי."}]},{"title":"מה כלבים עושים לנו? היתרונות של הקשר עם כלבים והשפעתם על הטיפול הרגשי","url":"https://derech-hakelev.com/articles/benefits-of-dogs-for-humans/","entries":[{"id":"article-title-ca554036d016","heading":"תחילת המאמר","text":"מה כלבים עושים לנו? היתרונות של הקשר עם כלבים והשפעתם על הטיפול הרגשי"},{"id":"article-paragraph-a2131b561b64","heading":"פתיחת המאמר","text":"מי שחי עם כלב מכיר את ההרגשה הזאת. חוזרים הביתה אחרי יום עמוס, הכלב מגיע לקבל את פנינו, ולפעמים עצם המפגש איתו כבר משנה משהו בהרגשה שלנו."},{"id":"article-paragraph-799d51422abb","heading":"פתיחת המאמר","text":"גם בעבודה הטיפולית שלי אני פוגש את ההשפעה הזאת. ילדים שמגיעים למפגש ומיד מחפשים את הכלב, אנשים שמרגישים בנוח לדבר כשהכלב נמצא לידם, ולפעמים גם רגעים שבהם נוכחות שקטה של כלב מאפשרת משהו שקשה להשיג בשיחה ישירה."},{"id":"article-paragraph-5bc63701ecca","heading":"פתיחת המאמר","text":"אבל מה באמת עומד מאחורי הקשר הזה? האם כלבים יכולים להפחית לחץ? האם הם משפיעים על מצב הרוח, על הבריאות הגופנית ועל הקשרים החברתיים שלנו? ומה הופך את הנוכחות שלהם למשמעותית כל כך דווקא בטיפול רגשי?"},{"id":"article-paragraph-9a288e954478","heading":"פתיחת המאמר","text":"בעשרים השנים האחרונות הצטברו מחקרים רבים שבחנו את הקשר בין בני אדם לכלבים. חלקם בדקו את ההשפעה של גידול כלב בבית, אחרים בחנו מפגשים קצרים עם כלבים, ומחקרים נוספים התמקדו בהתערבויות טיפוליות המשלבות כלבים."},{"id":"article-paragraph-b2708d6e3c7f","heading":"פתיחת המאמר","text":"התמונה שעולה מהם מעניינת: הקשר עם כלבים עשוי להשפיע עלינו בכמה מישורים במקביל - גופני, רגשי, חברתי וטיפולי."},{"id":"article-heading-18d9ddeb8240","heading":"כלבים יכולים לעזור לנו להירגע ולהפחית מתח","text":"כלבים יכולים לעזור לנו להירגע ולהפחית מתח"},{"id":"article-paragraph-7b47a1075bca","heading":"כלבים יכולים לעזור לנו להירגע ולהפחית מתח","text":"אחד התחומים הנחקרים ביותר הוא ההשפעה של מפגש עם כלבים על מתח ולחץ."},{"id":"article-paragraph-ec7819736a80","heading":"כלבים יכולים לעזור לנו להירגע ולהפחית מתח","text":"בשנת 2019 פורסם מחקר שבו השתתפו 249 סטודנטים. החוקרים חילקו אותם לקבוצות שונות: חלקם ליטפו כלבים וחתולים במשך עשר דקות, אחרים צפו באינטראקציה עם בעלי החיים, וקבוצות נוספות צפו בתמונות או המתינו."},{"id":"article-paragraph-2fdbf465725c","heading":"כלבים יכולים לעזור לנו להירגע ולהפחית מתח","text":"אצל המשתתפים שליטפו את בעלי החיים נמצאו לאחר הפעילות רמות נמוכות יותר של קורטיזול, הורמון המעורב בתגובת הגוף ללחץ, בהשוואה לקבוצות האחרות."},{"id":"article-paragraph-84baea222c94","heading":"כלבים יכולים לעזור לנו להירגע ולהפחית מתח","text":"גם סקירה מחקרית משנת 2025, שכללה 14 מחקרים בניתוח הכמותי, מצאה שהתערבויות בעזרת כלבים הפחיתו מתח וחרדה בקרב סטודנטים."},{"id":"article-paragraph-8d30649af4a3","heading":"כלבים יכולים לעזור לנו להירגע ולהפחית מתח","text":"הממצאים האלה מעניינים במיוחד משום שהם מצביעים על כך שההשפעה של מפגש עם בעל חיים אינה מתבטאת רק בתחושה סובייקטיבית של רוגע. בחלק מהמחקרים נמצאו גם שינויים במדדים גופניים הקשורים ללחץ."},{"id":"article-paragraph-fb39384fc004","heading":"כלבים יכולים לעזור לנו להירגע ולהפחית מתח","text":"מבחינה טיפולית, זה משמעותי. אדם שמגיע למפגש כשהוא מתוח, דרוך או חרד עשוי להתקשות להיפתח ולשתף. אם הנוכחות של הכלב מסייעת לו להרגיש מעט יותר בנוח, לפעמים כבר נוצר בסיס טוב יותר לעבודה."},{"id":"article-heading-8f780bd94738","heading":"הקשר עם כלבים משפיע גם על הגוף","text":"הקשר עם כלבים משפיע גם על הגוף"},{"id":"article-paragraph-1cc178a91fda","heading":"הקשר עם כלבים משפיע גם על הגוף","text":"ההשפעה של כלבים אינה מוגבלת לתחום הרגשי."},{"id":"article-paragraph-75379950c63b","heading":"הקשר עם כלבים משפיע גם על הגוף","text":"מחקרים שבדקו את בריאותם של בעלי כלבים מצאו קשר בין גידול כלב לבין פעילות גופנית מוגברת. הדבר לא מפתיע במיוחד: כלבים זקוקים לטיולים, לתנועה וליציאה מהבית, ולעיתים הם גורמים גם לבעליהם להיות פעילים יותר."},{"id":"article-paragraph-79cada9663af","heading":"הקשר עם כלבים משפיע גם על הגוף","text":"מטא־אנליזה משנת 2023, שהתבססה על 49 מחקרים, מצאה קשר חיובי בין גידול חיות מחמד לבין רמות הפעילות הגופנית של בעליהן."},{"id":"article-paragraph-0e3710ae90fc","heading":"הקשר עם כלבים משפיע גם על הגוף","text":"מחקרים אחרים בחנו גם את הקשר בין בעלות על כלבים לבריאות הלב וכלי הדם."},{"id":"article-paragraph-6c35651e383d","heading":"הקשר עם כלבים משפיע גם על הגוף","text":"סקירה ומטא-אנליזה שפורסמה בשנת 2019 בכתב עת של איגוד הלב האמריקאי כללה נתונים של כ-3.8 מיליון משתתפים. החוקרים מצאו שבעלות על כלב הייתה קשורה לסיכון נמוך יותר לתמותה במהלך תקופות המעקב, ובפרט לתמותה ממחלות לב וכלי דם."},{"id":"article-paragraph-0647bce0f24d","heading":"הקשר עם כלבים משפיע גם על הגוף","text":"חשוב להבחין כאן בין קשר סטטיסטי לבין השפעה ישירה: המחקר אינו מוכיח שעצם אימוץ הכלב הוא הסיבה לשיפור בבריאות. אבל הוא מחזק את העניין המחקרי בקשר שבין כלבים, אורח חיים פעיל ובריאות האדם."},{"id":"article-heading-5ff51dab5668","heading":"מה קורה במוח כשאנחנו יוצרים קשר עם כלב?","text":"מה קורה במוח כשאנחנו יוצרים קשר עם כלב?"},{"id":"article-paragraph-176c3729e479","heading":"מה קורה במוח כשאנחנו יוצרים קשר עם כלב?","text":"בשנת 2015 פורסם בכתב העת המדעי Science מחקר מעניין במיוחד על הקשר בין כלבים לבעליהם."},{"id":"article-paragraph-57089c71fc86","heading":"מה קורה במוח כשאנחנו יוצרים קשר עם כלב?","text":"החוקרים בחנו את התפקיד של אוקסיטוצין - הורמון המעורב, בין היתר, בקשרים חברתיים ובהתנהגויות של קרבה."},{"id":"article-paragraph-71ae5c84bfc8","heading":"מה קורה במוח כשאנחנו יוצרים קשר עם כלב?","text":"הם מצאו שכאשר כלבים ובעליהם הביטו זה בזה, משך המבט של הכלב היה קשור לעלייה ברמות האוקסיטוצין אצל הבעלים. החוקרים מצאו גם ראיות לתהליך הדדי של מבט וקשר בין הכלב לאדם."},{"id":"article-paragraph-3fc27f5db7c6","heading":"מה קורה במוח כשאנחנו יוצרים קשר עם כלב?","text":"הממצא הזה מציע הסבר ביולוגי לאחד הדברים שמרגישים באופן אינטואיטיבי בקשר עם כלבים: לפעמים לא צריך לעשות הרבה. מספיק מבט, קרבה או אינטראקציה פשוטה כדי לחוות תחושה משמעותית של קשר."},{"id":"article-paragraph-6efd6ccd311f","heading":"מה קורה במוח כשאנחנו יוצרים קשר עם כלב?","text":"כמובן, קשר רגשי הוא תהליך מורכב בהרבה מהפרשה של הורמון אחד, אבל המחקר הזה ממחיש עד כמה היחסים בין בני אדם לכלבים יכולים לערב מנגנונים ביולוגיים הקשורים לקרבה חברתית."},{"id":"article-heading-490318af1b0b","heading":"כלבים יכולים לעזור לנו ליצור קשרים חברתיים","text":"כלבים יכולים לעזור לנו ליצור קשרים חברתיים"},{"id":"article-paragraph-cdbbddafe4f3","heading":"כלבים יכולים לעזור לנו ליצור קשרים חברתיים","text":"כלבים לא משפיעים רק על הקשר שלנו איתם. לפעמים הם משפיעים גם על הקשרים שלנו עם אנשים אחרים."},{"id":"article-paragraph-04976dacaec7","heading":"כלבים יכולים לעזור לנו ליצור קשרים חברתיים","text":"מי שמטייל עם כלב מכיר את זה היטב: אנשים שלא היו פונים אלינו ברחוב עוצרים כדי לשאול עליו, ללטף אותו או לספר על הכלב שלהם."},{"id":"article-paragraph-c3b1ff70534a","heading":"כלבים יכולים לעזור לנו ליצור קשרים חברתיים","text":"לי אישית יש חברויות טובות שנוצרו בזכות הטיולים עם הכלבים."},{"id":"article-paragraph-e6f25d53c70a","heading":"כלבים יכולים לעזור לנו ליצור קשרים חברתיים","text":"מחקר משנת 2021 בחן את הקשר בין גידול כלבים, טיולים איתם והון חברתי - כלומר, קשרים, אמון ותחושת חיבור בין אנשים בקהילה."},{"id":"article-paragraph-f7cad2af0e6c","heading":"כלבים יכולים לעזור לנו ליצור קשרים חברתיים","text":"הכלב יכול להפוך למעין גורם מתווך שמקל על יצירת אינטראקציה חברתית."},{"id":"article-paragraph-7ecd543cc71c","heading":"כלבים יכולים לעזור לנו ליצור קשרים חברתיים","text":"בעבודה טיפולית יש לכך משמעות מיוחדת."},{"id":"article-paragraph-2e17b3f1473c","heading":"כלבים יכולים לעזור לנו ליצור קשרים חברתיים","text":"לא תמיד קל לילד או למבוגר להגיע למפגש עם אדם שאינו מכיר ולהתחיל לדבר על עצמו. הכלב יכול ליצור נושא משותף, לאפשר פעילות משותפת ולהפחית את הצורך בשיחה ישירה כבר מהרגע הראשון."},{"id":"article-paragraph-4b5bbf3d16d7","heading":"כלבים יכולים לעזור לנו ליצור קשרים חברתיים","text":"במקום להתחיל בשאלה \"איך אתה מרגיש?\", אפשר להתחיל מהיכרות עם הכלב, ממשחק או מפעילות פשוטה."},{"id":"article-paragraph-fe81a7130de1","heading":"כלבים יכולים לעזור לנו ליצור קשרים חברתיים","text":"לעיתים דווקא הדרך העקיפה הזאת מאפשרת לקשר הטיפולי להתפתח בצורה טבעית יותר."},{"id":"article-heading-92938ef56a59","heading":"כלבים, מצב רוח ותחושת בדידות","text":"כלבים, מצב רוח ותחושת בדידות"},{"id":"article-paragraph-10eb35999906","heading":"כלבים, מצב רוח ותחושת בדידות","text":"עבור אנשים רבים, כלב הוא חלק משמעותי מחיי היום-יום: מישהו שמחכה בבית, זקוק לנו, מלווה אותנו בשגרה ונמצא איתנו גם בתקופות קשות."},{"id":"article-paragraph-b0d602b5987d","heading":"כלבים, מצב רוח ותחושת בדידות","text":"בתחום המחקרי, אחת השאלות היא האם מפגשים עם בעלי חיים יכולים לתרום לרווחה הנפשית, במיוחד אצל אנשים מבוגרים או אנשים המתמודדים עם קשיים רגשיים."},{"id":"article-paragraph-a49e6eddc3f3","heading":"כלבים, מצב רוח ותחושת בדידות","text":"מטא-אנליזה שפורסמה בשנת 2026 ובחנה התערבויות בעזרת בעלי חיים בקרב מבוגרים בגיל השלישי מצאה שיפור בתסמיני דיכאון ובתפקוד הקוגניטיבי."},{"id":"article-paragraph-a7f34bb8bcd1","heading":"כלבים, מצב רוח ותחושת בדידות","text":"מבחינתי, אחד הדברים המעניינים בקשר עם כלב הוא העובדה שהוא מזמן גם קשר וגם עשייה. אנחנו לא רק מקבלים ממנו תשומת לב, אלא גם אחראים לו, דואגים לצרכיו ופועלים יחד איתו."},{"id":"article-paragraph-22ff1abd4669","heading":"כלבים, מצב רוח ותחושת בדידות","text":"לכן, כאשר משלבים כלבים בתהליך טיפולי, אפשר לעבוד לא רק דרך מגע וקרבה, אלא גם דרך פעילות, אחריות, יוזמה והתנסות."},{"id":"article-heading-4a310cfc2d1b","heading":"איך כלבים יכולים לעזור לילדים?","text":"איך כלבים יכולים לעזור לילדים?"},{"id":"article-paragraph-3c5e11193bda","heading":"איך כלבים יכולים לעזור לילדים?","text":"ילדים רבים נמשכים באופן טבעי לכלבים. הם רוצים ללטף, לשחק, להוביל אותם, ללמד אותם תרגילים ולבלות בקרבתם."},{"id":"article-paragraph-f2aab2065ef7","heading":"איך כלבים יכולים לעזור לילדים?","text":"המשיכה הזאת יכולה ליצור הזדמנויות משמעותיות גם בתחומים רגשיים וחברתיים."},{"id":"article-paragraph-b3d79d83b0f6","heading":"איך כלבים יכולים לעזור לילדים?","text":"בשנת 2025 פורסמה סקירה שיטתית של 30 מחקרים שבחנו התערבויות בעזרת בעלי חיים בקרב ילדים בגיל בית הספר. בסקירה נמצאו ממצאים חיוביים בתחומי התפקוד החברתי-רגשי, ההתנהגות והלמידה."},{"id":"article-paragraph-835ae4e72711","heading":"איך כלבים יכולים לעזור לילדים?","text":"בעבודה עם כלבים, אפשר להפוך את התחומים האלה לחלק מהתנסות ממשית."},{"id":"article-paragraph-79ae749a738b","heading":"איך כלבים יכולים לעזור לילדים?","text":"ילד שמנסה ללמד כלב תרגיל עשוי לפגוש תסכול כשהכלב לא מצליח. ילד שמכין לכלב מסלול מכשולים צריך לפעמים להתאים את התוכנית שלו למציאות. וילד שמתקשה להמתין יכול לתרגל סבלנות בתוך פעילות שיש לו מוטיבציה להשתתף בה."},{"id":"article-paragraph-70c81cd24d0b","heading":"איך כלבים יכולים לעזור לילדים?","text":"המשמעות היא שלא חייבים לדבר באופן ישיר על כל קושי כדי לעבוד עליו."},{"id":"article-paragraph-fbd1dba7da8e","heading":"איך כלבים יכולים לעזור לילדים?","text":"לפעמים הסיטואציה הטיפולית עצמה מאפשרת לילד לפגוש את הקושי, ובעזרת המטפל ללמוד להתמודד איתו בדרך אחרת."},{"id":"article-heading-2030e7a2d1bf","heading":"כלבים וילדים על הרצף האוטיסטי","text":"כלבים וילדים על הרצף האוטיסטי"},{"id":"article-paragraph-e3a8d3329800","heading":"כלבים וילדים על הרצף האוטיסטי","text":"אחד התחומים שבהם נחקרה העבודה בעזרת כלבים הוא התערבויות עם ילדים ובני נוער על הרצף האוטיסטי."},{"id":"article-paragraph-d44793c50cc2","heading":"כלבים וילדים על הרצף האוטיסטי","text":"סקירה שיטתית משנת 2024, שהתמקדה בטיפול בעזרת כלבים, כללה 19 מאמרים. בחלק גדול מהמחקרים דווח על שיפור בתקשורת ובאינטראקציה חברתית."},{"id":"article-paragraph-ef226029de36","heading":"כלבים וילדים על הרצף האוטיסטי","text":"במחקרים מסוימים נמצאו גם שינויים חיוביים במדדים רגשיים והתנהגותיים."},{"id":"article-paragraph-c2ba60ae24d4","heading":"כלבים וילדים על הרצף האוטיסטי","text":"אחת האפשרויות שמציעים החוקרים היא שהכלב יכול לשמש גורם שמושך את תשומת הלב ומעודד אינטראקציה."},{"id":"article-paragraph-4a7a7d1275eb","heading":"כלבים וילדים על הרצף האוטיסטי","text":"אפשר להבין זאת גם דרך ההתנסות: הפעילות עם הכלב יוצרת סיבה משותפת לתקשר, לשתף פעולה, להתבונן, להגיב ולפעול יחד."},{"id":"article-paragraph-bb07252205be","heading":"כלבים וילדים על הרצף האוטיסטי","text":"גם כאן חשוב לראות את הילד ואת הצרכים הייחודיים שלו. המטרה אינה ללמד כל ילד להתנהג בדרך מסוימת, אלא להבין אילו יכולות הוא רוצה לפתח וכיצד הקשר והפעילות עם הכלב יכולים לסייע לו."},{"id":"article-heading-57612f31b6fb","heading":"הקלה על כאב ומתח במצבים רפואיים","text":"הקלה על כאב ומתח במצבים רפואיים"},{"id":"article-paragraph-3f90a2a3b3bc","heading":"הקלה על כאב ומתח במצבים רפואיים","text":"תחום נוסף שבו נחקרו התערבויות בעזרת בעלי חיים הוא בתי חולים ומסגרות רפואיות."},{"id":"article-paragraph-01f8e7c8d707","heading":"הקלה על כאב ומתח במצבים רפואיים","text":"עבור ילדים, אשפוז עשוי להיות חוויה מאיימת: סביבה לא מוכרת, בדיקות, כאב, פרידה מהשגרה ולעיתים גם פחד מהטיפול הרפואי."},{"id":"article-paragraph-093f17b092a2","heading":"הקלה על כאב ומתח במצבים רפואיים","text":"סקירה ומטא-אנליזה משנת 2021 בחנה שמונה מחקרים שכללו יחד 348 ילדים ובני נוער מאושפזים."},{"id":"article-paragraph-66aeb39fad2a","heading":"הקלה על כאב ומתח במצבים רפואיים","text":"החוקרים מצאו שבקבוצות שקיבלו התערבות בעזרת בעלי חיים נמדדו רמות כאב נמוכות יותר בהשוואה לקבוצות הביקורת."},{"id":"article-paragraph-f28b6ff4efe3","heading":"הקלה על כאב ומתח במצבים רפואיים","text":"הממצא הזה מעניין משום שהוא מדגים את האפשרות של מפגש עם בעל חיים לשמש מרכיב תומך גם במצבים שבהם הקושי אינו רק רגשי, אלא קשור לחוויה גופנית ממשית."},{"id":"article-heading-c33a9de62408","heading":"כלבים בהתמודדות עם פוסט טראומה","text":"כלבים בהתמודדות עם פוסט טראומה"},{"id":"article-paragraph-c219fdf84b59","heading":"כלבים בהתמודדות עם פוסט טראומה","text":"בעשור האחרון גבר גם העניין המחקרי בכלבי שירות עבור אנשים המתמודדים עם הפרעת דחק פוסט טראומטית (PTSD)."},{"id":"article-paragraph-9669a6502843","heading":"כלבים בהתמודדות עם פוסט טראומה","text":"מחקר שפורסם בשנת 2024 בכתב העת JAMA Network Open בחן 156 אנשי צבא ויוצאי צבא אמריקאים המתמודדים עם PTSD."},{"id":"article-paragraph-ae7e2ca6bf81","heading":"כלבים בהתמודדות עם פוסט טראומה","text":"החוקרים השוו בין אנשים שקיבלו כלב שירות פסיכיאטרי לצד הטיפול הרגיל שלהם, לבין אנשים שהמשיכו לקבל טיפול רגיל ללא כלב שירות בתקופת המחקר."},{"id":"article-paragraph-7324120f1abe","heading":"כלבים בהתמודדות עם פוסט טראומה","text":"לאחר שלושה חודשים, הקבוצה שקיבלה כלבי שירות הציגה חומרה נמוכה יותר של תסמיני PTSD ותפקוד פסיכו-חברתי טוב יותר."},{"id":"article-paragraph-05cf53ebd5dd","heading":"כלבים בהתמודדות עם פוסט טראומה","text":"חשוב להבחין בין כלב שירות שמלווה אדם בחיי היום-יום לבין כלב המשתלב במפגש טיפולי. אלה התערבויות שונות, עם מטרות ותפקידים שונים."},{"id":"article-paragraph-fe0f54f2f0d7","heading":"כלבים בהתמודדות עם פוסט טראומה","text":"עם זאת, המחקר ממחיש את הפוטנציאל של קשר מתמשך עם כלב כחלק ממערך התמיכה באנשים המתמודדים עם מצוקה נפשית."},{"id":"article-heading-e9f3a8dea3d6","heading":"אז מה מיוחד בכלבים דווקא בטיפול רגשי?","text":"אז מה מיוחד בכלבים דווקא בטיפול רגשי?"},{"id":"article-paragraph-4a3418eea8b2","heading":"אז מה מיוחד בכלבים דווקא בטיפול רגשי?","text":"עד עכשיו עסקנו בהשפעות האפשריות של כלבים על הגוף, על הרגש ועל הקשרים החברתיים."},{"id":"article-paragraph-cf567d1509b9","heading":"אז מה מיוחד בכלבים דווקא בטיפול רגשי?","text":"אבל יש שאלה נוספת שמעניינת אותי במיוחד כמטפל: מה הופך את כל היתרונות האלה למשמעותיים בתוך חדר הטיפול?"},{"id":"article-paragraph-39f66318c486","heading":"אז מה מיוחד בכלבים דווקא בטיפול רגשי?","text":"בעיניי, התשובה נמצאת בשילוב בין הקשר שנוצר עם הכלב לבין האפשרויות שהקשר הזה פותח."},{"id":"article-paragraph-46be39099d00","heading":"אז מה מיוחד בכלבים דווקא בטיפול רגשי?","text":"ראשית, הכלב יכול לעזור ביצירת הקשר הראשוני. עבור ילדים ומבוגרים שמתקשים לתת אמון או להרגיש בנוח בטיפול, הכלב יכול לשמש גשר לקשר עם המטפל."},{"id":"article-paragraph-e6d3978ca22d","heading":"אז מה מיוחד בכלבים דווקא בטיפול רגשי?","text":"שנית, הכלב מאפשר ביטוי רגשי גם בלי שיחה ישירה. לפעמים קל יותר לדבר על מה שהכלב מרגיש, על הקושי שלו או על מה שהוא צריך, ורק בהמשך לחבר את הדברים לחוויה האישית שלנו."},{"id":"article-paragraph-33266954fff3","heading":"אז מה מיוחד בכלבים דווקא בטיפול רגשי?","text":"שלישית, הכלב מזמן התנסויות אמיתיות. הוא לא תמיד משתף פעולה, יש לו רצונות וצרכים משלו, והוא מגיב למה שמתרחש סביבו. לכן אפשר לפגוש במהלך הפעילות רגשות כמו תסכול, התרגשות, פחד, הצלחה וגאווה."},{"id":"article-paragraph-9dbe0effb833","heading":"אז מה מיוחד בכלבים דווקא בטיפול רגשי?","text":"ורביעית, הכלב מאפשר לשלב משחק, תנועה וקשר בתוך אותו מפגש. לא כל אדם מתחבר לטיפול שמתבסס בעיקר על שיחה. עבור חלק מהמטופלים, דווקא העשייה המשותפת היא שמאפשרת בהמשך גם שיח רגשי עמוק יותר."},{"id":"article-heading-a3b439588bc7","heading":"לסיכום - הרבה מעבר לחברו הטוב של האדם","text":"לסיכום - הרבה מעבר לחברו הטוב של האדם"},{"id":"article-paragraph-25af5ca1a73d","heading":"לסיכום - הרבה מעבר לחברו הטוב של האדם","text":"המחקרים מהשנים האחרונות מלמדים שהקשר בין בני אדם לכלבים עשוי להיות משמעותי הרבה מעבר להנאה ולחברות."},{"id":"article-paragraph-be997516c412","heading":"לסיכום - הרבה מעבר לחברו הטוב של האדם","text":"הוא קשור להפחתת מתח, לתהליכים ביולוגיים של קרבה וקשר, לפעילות גופנית, להזדמנויות חברתיות וליתרונות אפשריים במגוון התערבויות טיפוליות."},{"id":"article-paragraph-50616ad5df63","heading":"לסיכום - הרבה מעבר לחברו הטוב של האדם","text":"בעיניי, הייחוד של הכלב בטיפול אינו נמצא רק ביכולת שלו לעורר רוגע או שמחה."},{"id":"article-paragraph-32adb86dbd0a","heading":"לסיכום - הרבה מעבר לחברו הטוב של האדם","text":"הוא נמצא בכך שהכלב הוא יצור חי שאפשר ליצור איתו קשר, לפעול לצידו, להתמודד איתו עם אתגרים ולחוות דרכו מצבים רגשיים אמיתיים."},{"id":"article-paragraph-b301c962620d","heading":"לסיכום - הרבה מעבר לחברו הטוב של האדם","text":"כאשר כל אלה משתלבים בתוך קשר טיפולי מקצועי ומותאם, הם יכולים להפוך לחלק משמעותי מתהליך של שינוי והתפתחות."},{"id":"article-reference-c5a93b9de9bc","heading":"מקורות","text":"Pendry & Vandagriff (2019) מחקר אקראי על השפעת מפגש עם בעלי חיים על רמות קורטיזול בקרב סטודנטים."},{"id":"article-reference-bdd0b8524c34","heading":"מקורות","text":"Sim et al. (2025) סקירה שיטתית ומטא־אנליזה על הפחתת מתח וחרדה באמצעות התערבויות עם כלבים בקרב סטודנטים."},{"id":"article-reference-86745eaf7205","heading":"מקורות","text":"Nagasawa et al. (2015) מחקר ב־Science על מבט הדדי ואוקסיטוצין בקשר בין כלבים לבני אדם."},{"id":"article-reference-959ba36a6eed","heading":"מקורות","text":"Martins et al. (2023) מטא־אנליזה על גידול חיות מחמד, פעילות גופנית ובריאות נפשית."},{"id":"article-reference-34946b9d4fc8","heading":"מקורות","text":"Kramer et al. (2019) מטא־אנליזה על בעלות על כלבים והקשר לתמותה ולבריאות הלב."},{"id":"article-reference-2d2530b65140","heading":"מקורות","text":"Koohsari et al. (2021) מחקר על בעלות על כלבים, טיולים והון חברתי."},{"id":"article-reference-2ac5b7eec80f","heading":"מקורות","text":"Moe et al. (2025) סקירה שיטתית על התערבויות בעזרת בעלי חיים בילדים בגיל בית הספר."},{"id":"article-reference-3564f9a0ce08","heading":"מקורות","text":"Galvany-López et al. (2024) סקירה שיטתית על טיפול בעזרת כלבים בקרב ילדים ובני נוער על הרצף האוטיסטי."},{"id":"article-reference-1b80674ae9ce","heading":"מקורות","text":"Feng et al. (2021) סקירה ומטא־אנליזה על התערבויות בעזרת בעלי חיים בקרב ילדים מאושפזים."},{"id":"article-reference-31ccc27158aa","heading":"מקורות","text":"Leighton et al. (2024) מחקר מבוקר על כלבי שירות פסיכיאטריים בקרב אנשי צבא עם PTSD."},{"id":"article-reference-194017e05ac2","heading":"מקורות","text":"Shoesmith et al. (2025) סקירה שיטתית על התערבויות בעזרת כלבים בקרב ילדים ומבוגרים עם קשיים נפשיים או נוירו־התפתחותיים."},{"id":"article-reference-3a19d75406a4","heading":"מקורות","text":"Lv et al. (2026) סקירה שיטתית ומטא־אנליזה על התערבויות בעזרת בעלי חיים חיים ורובוטיים, תסמיני דיכאון ותפקוד קוגניטיבי בגיל השלישי."}]},{"title":"התמודדות עם תסכול אצל ילדים - למה זה כל כך קשה ואיך אפשר לעזור?","url":"https://derech-hakelev.com/pages/articles/frustration-children-dog-therapy/","entries":[{"id":"article-title-1574d71159f5","heading":"תחילת המאמר","text":"התמודדות עם תסכול אצל ילדים - למה זה כל כך קשה ואיך אפשר לעזור?"},{"id":"article-paragraph-c72c30a2d189","heading":"פתיחת המאמר","text":"הילד מתעצבן כשהוא מפסיד במשחק? מוותר על משימה ברגע שהוא לא מצליח? מתפרץ כשאומרים לו לא, או כשהדברים לא מתרחשים בדיוק כפי שרצה?"},{"id":"article-paragraph-983d7dd57c01","heading":"פתיחת המאמר","text":"תסכול הוא אחד הרגשות שאנחנו פוגשים כמעט בכל יום, ובכל גיל. אנחנו מתכננים משהו שלא מצליח, רוצים דבר שאנחנו לא יכולים לקבל, מנסים להשיג מטרה ונתקלים בקושי."},{"id":"article-paragraph-fc8297610bfd","heading":"פתיחת המאמר","text":"אצל ילדים, התסכול יכול להתבטא בצורה עוצמתית במיוחד. לפעמים מדובר בבכי, בכעס או בהתפרצות, ולפעמים דווקא בהסתגרות, בוויתור מהיר או בהימנעות מניסיון נוסף."},{"id":"article-paragraph-8e3362313772","heading":"פתיחת המאמר","text":"אבל חשוב לי להתחיל דווקא מהנקודה הזאת: תסכול הוא לא דבר רע. הוא חלק טבעי ובלתי נפרד מהחיים, ויש לו גם תפקיד חשוב בהתפתחות שלנו."},{"id":"article-paragraph-5fdcf8e25453","heading":"פתיחת המאמר","text":"השאלה היא לא איך אנחנו מונעים מילדים להרגיש תסכול, אלא איך אנחנו עוזרים להם לפתח את היכולת להתמודד איתו."},{"id":"article-heading-f0e45ce32538","heading":"מה זה בכלל תסכול?","text":"מה זה בכלל תסכול?"},{"id":"article-paragraph-d3cb22e64ab4","heading":"מה זה בכלל תסכול?","text":"תסכול הוא התחושה שמתעוררת כשמשהו שאנחנו רוצים או מנסים להשיג לא מתאפשר לנו."},{"id":"article-paragraph-053793307e42","heading":"מה זה בכלל תסכול?","text":"למשל, ילד שרוצה להמשיך לשחק אבל צריך ללכת לישון, ילד שמנסה לבנות מגדל והמגדל נופל שוב ושוב, או ילד שרוצה להצטרף למשחק והחברים לא משתפים אותו."},{"id":"article-paragraph-605b8067bb81","heading":"מה זה בכלל תסכול?","text":"בכל המצבים האלה יש פער בין מה שהילד רוצה שיקרה לבין מה שקורה בפועל."},{"id":"article-paragraph-cbe9b4dd2f7b","heading":"מה זה בכלל תסכול?","text":"תסכול יכול לעורר כעס, אכזבה, עצב, חוסר אונים ולעיתים גם רצון לוותר או להתרחק."},{"id":"article-paragraph-54aaa7a8e025","heading":"מה זה בכלל תסכול?","text":"יש משהו חשוב בתסכול: פעמים רבות הוא זה שמניע אותנו לפעול. כשמשהו לא מצליח, התסכול יכול לגרום לנו לנסות שוב, להשקיע יותר מאמץ, לחפש פתרון אחר או לבקש עזרה."},{"id":"article-paragraph-b0d05c6f8627","heading":"מה זה בכלל תסכול?","text":"אבל כשהתסכול נעשה גדול מדי, או כשהילד מתקשה לשאת אותו, הוא יכול גם להוביל לתגובות שפוגעות בו ובסביבה שלו."},{"id":"article-heading-d122ff1b1963","heading":"איך נראה קושי בהתמודדות עם תסכול אצל ילדים?","text":"איך נראה קושי בהתמודדות עם תסכול אצל ילדים?"},{"id":"article-paragraph-413eab4705ca","heading":"איך נראה קושי בהתמודדות עם תסכול אצל ילדים?","text":"לא כל הילדים מבטאים תסכול באותה הדרך."},{"id":"article-paragraph-f824670cd825","heading":"איך נראה קושי בהתמודדות עם תסכול אצל ילדים?","text":"יש ילדים שכשהם לא מצליחים משהו, הם מתעצבנים מאוד, צועקים, בוכים או זורקים חפצים. אחרים יאמרו מיד \"אני לא יודע\", \"אני לא מצליח\" או \"זה משחק מטומטם\", ויוותרו לפני שבאמת ניסו."},{"id":"article-paragraph-8f3630eb266e","heading":"איך נראה קושי בהתמודדות עם תסכול אצל ילדים?","text":"יש גם ילדים שהתסכול שלהם פחות נראה לעין. הם עשויים להימנע ממשחקים שבהם אפשר להפסיד, לא לרצות לנסות דברים חדשים או להתרחק ממצבים שבהם הם לא בטוחים שיצליחו."},{"id":"article-paragraph-62ddf0c244ab","heading":"איך נראה קושי בהתמודדות עם תסכול אצל ילדים?","text":"לעיתים נראה קושי סביב מצבים כמו:"},{"id":"article-item-c0af932a7011","heading":"איך נראה קושי בהתמודדות עם תסכול אצל ילדים?","text":"הפסד במשחק או כישלון במשימה."},{"id":"article-item-bbde1eb90ae5","heading":"איך נראה קושי בהתמודדות עם תסכול אצל ילדים?","text":"קבלת תשובה שלילית מההורים."},{"id":"article-item-d8e85679a00f","heading":"איך נראה קושי בהתמודדות עם תסכול אצל ילדים?","text":"המתנה או דחיית סיפוקים."},{"id":"article-item-c1160d6fb902","heading":"איך נראה קושי בהתמודדות עם תסכול אצל ילדים?","text":"שינוי בתוכניות או חוסר שליטה במצב."},{"id":"article-item-55e006050dd2","heading":"איך נראה קושי בהתמודדות עם תסכול אצל ילדים?","text":"קושי חברתי, דחייה או ריב עם חבר."},{"id":"article-item-233d9ee37ba4","heading":"איך נראה קושי בהתמודדות עם תסכול אצל ילדים?","text":"תחושה שמישהו אחר לא מבין אותם או לא מקשיב להם."},{"id":"article-paragraph-063d5ae621fb","heading":"איך נראה קושי בהתמודדות עם תסכול אצל ילדים?","text":"מה שמשותף למצבים האלה הוא שהילד פוגש מציאות שלא מתאימה למה שהוא רצה או ציפה."},{"id":"article-heading-46400be5bce6","heading":"מתי תסכול הוא דבר טבעי, ומתי הוא הופך לבעיה?","text":"מתי תסכול הוא דבר טבעי, ומתי הוא הופך לבעיה?"},{"id":"article-paragraph-87fb17bd2754","heading":"מתי תסכול הוא דבר טבעי, ומתי הוא הופך לבעיה?","text":"לפעמים הורים מודאגים מכך שהילד שלהם מתוסכל בקלות. אבל עצם העובדה שילד מתוסכל, בוכה או אפילו כועס מאוד, לא אומרת בהכרח שיש בעיה."},{"id":"article-paragraph-768a48568d95","heading":"מתי תסכול הוא דבר טבעי, ומתי הוא הופך לבעיה?","text":"ילדים עדיין מפתחים את היכולת להתמודד עם רגשות חזקים. ילד בן שלוש שמתקשה לקבל תשובה שלילית נמצא בשלב התפתחותי אחר לגמרי מילד בן עשר שמגיב באותה הדרך."},{"id":"article-paragraph-2217b67cf673","heading":"מתי תסכול הוא דבר טבעי, ומתי הוא הופך לבעיה?","text":"לכן, השאלה היא לא רק האם הילד מתוסכל, אלא איך הוא מתמודד עם התסכול, באיזו תדירות זה קורה, כמה זמן לוקח לו להתאושש ועד כמה הדבר משפיע על חייו."},{"id":"article-paragraph-5dbdbdd41c20","heading":"מתי תסכול הוא דבר טבעי, ומתי הוא הופך לבעיה?","text":"כשילד מתפרץ בעוצמה כמעט בכל פעם שמשהו לא מצליח, פוגע בעצמו או באחרים, נמנע באופן קבוע מהתמודדויות, או כשהקושי פוגע בלימודים, בחברויות ובמשפחה, כדאי להתייחס אליו ולבחון האם הוא זקוק לעזרה."},{"id":"article-paragraph-42c3e36eb6fb","heading":"מתי תסכול הוא דבר טבעי, ומתי הוא הופך לבעיה?","text":"לעומת זאת, ילד שמתאכזב, בוכה קצת, כועס ולאחר מכן מצליח להמשיך הלאה, אינו בהכרח ילד שמתקשה בוויסות. לפעמים הוא פשוט ילד שחווה תסכול ומבטא אותו."},{"id":"article-paragraph-e01435be5d63","heading":"מתי תסכול הוא דבר טבעי, ומתי הוא הופך לבעיה?","text":"המטרה שלנו לא צריכה להיות לגדל ילדים שלא מתוסכלים, אלא ילדים שמסוגלים לפגוש תסכול ולהתמודד איתו."},{"id":"article-heading-5388eda12b26","heading":"למה יש ילדים שמתקשים יותר להתמודד עם תסכול?","text":"למה יש ילדים שמתקשים יותר להתמודד עם תסכול?"},{"id":"article-paragraph-f09b9cea2a83","heading":"למה יש ילדים שמתקשים יותר להתמודד עם תסכול?","text":"היכולת להתמודד עם תסכול מושפעת ממספר גורמים."},{"id":"article-paragraph-8fc8ffb10834","heading":"למה יש ילדים שמתקשים יותר להתמודד עם תסכול?","text":"יש ילדים שמלכתחילה חווים רגשות בעוצמה גבוהה יותר, או מתקשים יותר לעכב תגובה. אחרים מתקשים בגמישות מחשבתית, בהמתנה, בהתמודדות עם חוסר ודאות או בקבלת שינויים."},{"id":"article-paragraph-b71662e349b4","heading":"למה יש ילדים שמתקשים יותר להתמודד עם תסכול?","text":"לפעמים גם הניסיון שהילד צבר משפיע. ילד שחווה הרבה כישלונות, ביקורת או תחושה שהוא לא מספיק טוב, עשוי להגיע להתנסות חדשה כשהוא כבר מצפה שלא יצליח."},{"id":"article-paragraph-a7bba17f3e28","heading":"למה יש ילדים שמתקשים יותר להתמודד עם תסכול?","text":"במצבים כאלה, אפילו קושי קטן עלול לעורר תגובה חזקה."},{"id":"article-paragraph-643beb4051f5","heading":"למה יש ילדים שמתקשים יותר להתמודד עם תסכול?","text":"גם לאופן שבו המבוגרים מגיבים לתסכול יש משמעות. אם אנחנו ממהרים תמיד לפתור לילד כל קושי, הוא עלול לקבל פחות הזדמנויות להתנסות בהתמודדות. מצד שני, אם בכל פעם שהוא מתוסכל הוא פוגש כעס, ביקורת או חוסר סבלנות, התסכול המקורי עלול להפוך לחוויה קשה עוד יותר."},{"id":"article-paragraph-4c7ef900744f","heading":"למה יש ילדים שמתקשים יותר להתמודד עם תסכול?","text":"לכן, לא מספיק ללמד ילד מה לעשות כשהוא מתוסכל. חשוב גם להבין מה עומד מאחורי הקושי שלו, ומה הוא צריך מאיתנו באותו רגע."},{"id":"article-heading-5b5eaed03208","heading":"מה הקשר בין תסכול להיקשרות?","text":"מה הקשר בין תסכול להיקשרות?"},{"id":"article-paragraph-24481ba123d0","heading":"מה הקשר בין תסכול להיקשרות?","text":"אחד הדברים המרכזיים בגישה ההתפתחותית-היקשרותית הוא ההבנה שהתפתחות רגשית מתרחשת בתוך קשר."},{"id":"article-paragraph-d4054fc070be","heading":"מה הקשר בין תסכול להיקשרות?","text":"כשילד פוגש משהו שהוא לא מצליח לשנות, הוא זקוק לא פעם למבוגר שיכול להיות איתו בתוך האכזבה, הכעס או חוסר האונים."},{"id":"article-paragraph-0c5a4329510d","heading":"מה הקשר בין תסכול להיקשרות?","text":"לפי הגישה של גורדון ניופלד, לתסכול יש כמה כיוונים אפשריים."},{"id":"article-paragraph-dc58b79caf20","heading":"מה הקשר בין תסכול להיקשרות?","text":"לפעמים הוא מניע אותנו לשנות את המצב: לנסות שוב, להתאמץ או למצוא דרך אחרת."},{"id":"article-paragraph-873da75eb103","heading":"מה הקשר בין תסכול להיקשרות?","text":"אבל לפעמים אנחנו פוגשים משהו שאי אפשר לשנות. במקרה כזה, ההתפתחות אינה נמצאת בעוד ניסיון להילחם במציאות, אלא ביכולת להרגיש את האכזבה, לקבל את מה שלא ניתן לשנות ולהסתגל."},{"id":"article-paragraph-66df64f64f33","heading":"מה הקשר בין תסכול להיקשרות?","text":"אפשר לראות זאת אצל ילד שמאוד רוצה לקבל משהו, אבל הדבר פשוט אינו אפשרי. לפעמים הוא ינסה להתווכח, לכעוס או לשנות את דעתו של ההורה. בהמשך, אם הוא יוכל לפגוש את האכזבה ולהרגיש בטוח בקשר, תיתכן תנועה מהכעס אל העצב והקבלה."},{"id":"article-paragraph-a9cae44b8344","heading":"מה הקשר בין תסכול להיקשרות?","text":"מבחינתי, זה אחד הדברים החשובים בעבודה עם ילדים: לא כל קושי צריך לפתור, ולא כל תסכול צריך להעלים."},{"id":"article-paragraph-0fa7f87cdfe6","heading":"מה הקשר בין תסכול להיקשרות?","text":"לפעמים צריך לעזור לילד לגלות שהוא מסוגל להתמודד גם עם דברים שלא מתרחשים כפי שהיה רוצה."},{"id":"article-paragraph-797e8c535822","heading":"מה הקשר בין תסכול להיקשרות?","text":"הקשר הבטוח עם המבוגר הוא מה שמאפשר לילד לפגוש את הרגשות האלה מבלי להרגיש שהוא נשאר איתם לבד."},{"id":"article-paragraph-f090375d0b46","heading":"מה הקשר בין תסכול להיקשרות?","text":"לקריאה נוספת: הגישה ההתפתחותית-היקשרותית בטיפול בעזרת כלבים."},{"id":"article-heading-7fa4ea504bb7","heading":"איך אני עובד על התמודדות עם תסכול בטיפול בעזרת כלבים?","text":"איך אני עובד על התמודדות עם תסכול בטיפול בעזרת כלבים?"},{"id":"article-paragraph-5c609e1d4e08","heading":"איך אני עובד על התמודדות עם תסכול בטיפול בעזרת כלבים?","text":"אחד הדברים שאני אוהב בעבודה עם כלבים הוא האפשרות ליצור התנסויות שבהן הילד פוגש רגשות אמיתיים, ולא רק מדבר עליהם באופן תיאורטי."},{"id":"article-paragraph-b4250e798946","heading":"איך אני עובד על התמודדות עם תסכול בטיפול בעזרת כלבים?","text":"אבל יש נקודה שחשוב לי להדגיש: אני לא מתחיל לעבוד באופן מכוון על תסכול במפגשים הראשונים."},{"id":"article-paragraph-9bdf6df812d4","heading":"איך אני עובד על התמודדות עם תסכול בטיפול בעזרת כלבים?","text":"לפני שאנחנו מציבים לילד אתגרים, חשוב קודם כול לבסס את הקשר הטיפולי."},{"id":"article-paragraph-8c9b927b7090","heading":"איך אני עובד על התמודדות עם תסכול בטיפול בעזרת כלבים?","text":"אני רוצה שהילד ירגיש בנוח איתי, שיכיר אותי, שירגיש שהוא יכול לסמוך עליי ושגם אם משהו לא יצליח, הוא עדיין נמצא במקום בטוח."},{"id":"article-paragraph-e3275a48ff45","heading":"איך אני עובד על התמודדות עם תסכול בטיפול בעזרת כלבים?","text":"רק כשהקשר מספיק יציב, וכשאני מעריך שאפשר לפגוש תסכול מבלי שהדבר יערער את תחושת הביטחון של הילד בקשר, אני מתחיל לשלב התנסויות מכוונות."},{"id":"article-paragraph-9967651322f2","heading":"איך אני עובד על התמודדות עם תסכול בטיפול בעזרת כלבים?","text":"וגם אז, המטרה היא לא להציף את הילד, אלא ליצור קושי שאפשר להתמודד איתו, לדבר עליו וללמוד ממנו."},{"id":"article-heading-09c2dd1473ac","heading":"מה קורה כשהכלב פשוט לא מצליח?","text":"מה קורה כשהכלב פשוט לא מצליח?"},{"id":"article-paragraph-1862c17a0a8b","heading":"איך אני עובד על התמודדות עם תסכול בטיפול בעזרת כלבים?","text":"אחת הפעילויות שאני משתמש בהן היא עבודה עם הכלבים על ביצוע תרגילים."},{"id":"article-paragraph-d983c3f24ea1","heading":"איך אני עובד על התמודדות עם תסכול בטיפול בעזרת כלבים?","text":"אני יכול לבקש מהילד ללמד כלב לבצע גלגול. בהתחלה נעבוד עם כלב שמכיר את התרגיל. זה לא בהכרח יהיה קל, אבל בסופו של דבר הילד בדרך כלל מצליח."},{"id":"article-paragraph-a7eebcf451d5","heading":"איך אני עובד על התמודדות עם תסכול בטיפול בעזרת כלבים?","text":"לאחר מכן אני יכול לבקש ממנו לנסות את אותו התרגיל עם ליאו, כלב שלא יודע לבצע גלגול."},{"id":"article-paragraph-8c97823cca31","heading":"איך אני עובד על התמודדות עם תסכול בטיפול בעזרת כלבים?","text":"אני יודע מראש שהתרגיל לא צפוי להצליח, אבל הילד עדיין לא יודע את זה."},{"id":"article-paragraph-ab06c1186760","heading":"איך אני עובד על התמודדות עם תסכול בטיפול בעזרת כלבים?","text":"במהלך הפעילות אני מתבונן במה שמתרחש."},{"id":"article-paragraph-57e466d59947","heading":"איך אני עובד על התמודדות עם תסכול בטיפול בעזרת כלבים?","text":"כמה זמן הוא מנסה? האם הוא מתעצבן? האם הוא מוותר מהר? האם הוא מנסה לשנות את הדרך שבה הוא מסביר לכלב? האם הוא מבקש עזרה?"},{"id":"article-paragraph-fe42a8ec7c09","heading":"איך אני עובד על התמודדות עם תסכול בטיפול בעזרת כלבים?","text":"אחרי ההתנסות, כשהילד פנוי לשיחה, אני יכול לשאול אותו מה הוא הרגיש."},{"id":"article-paragraph-1b095d026617","heading":"איך אני עובד על התמודדות עם תסכול בטיפול בעזרת כלבים?","text":"ואז אנחנו מדברים גם על ליאו."},{"id":"article-paragraph-eb5233b66f79","heading":"איך אני עובד על התמודדות עם תסכול בטיפול בעזרת כלבים?","text":"איך לדעתך הוא הרגיש? האם יכול להיות שגם הוא התקשה? הרי יכול להיות שהוא רצה לשתף פעולה, אבל פשוט לא הבין מה מצפים ממנו."},{"id":"article-paragraph-924e0e4b6f7d","heading":"איך אני עובד על התמודדות עם תסכול בטיפול בעזרת כלבים?","text":"אני מסביר לילד שליאו לא יודע לבצע את התרגיל הזה, ושבחרתי בפעילות כדי שנוכל לפגוש יחד תחושה שנקראת תסכול ולדבר עליה."},{"id":"article-paragraph-3c10c16e1c6a","heading":"איך אני עובד על התמודדות עם תסכול בטיפול בעזרת כלבים?","text":"כאן מתחילה מבחינתי העבודה המשמעותית."},{"id":"article-heading-6fb89cb1a823","heading":"גם הילד וגם הכלב יכולים לפגוש תסכול","text":"גם הילד וגם הכלב יכולים לפגוש תסכול"},{"id":"article-paragraph-11bb1d4c7733","heading":"איך אני עובד על התמודדות עם תסכול בטיפול בעזרת כלבים?","text":"לפעמים קל יותר לילד להבין את מה שקרה דווקא דרך הניסיון להתבונן בכלב."},{"id":"article-paragraph-25dbaa1f8318","heading":"איך אני עובד על התמודדות עם תסכול בטיפול בעזרת כלבים?","text":"אפשר לשאול אותו: מה לדעתך קרה לליאו כשהוא לא הצליח להבין אותך? איך הוא הרגיש כשניסית שוב ושוב? מה לדעתך היה יכול לעזור לו?"},{"id":"article-paragraph-4fe70858bd19","heading":"איך אני עובד על התמודדות עם תסכול בטיפול בעזרת כלבים?","text":"אנחנו לא יכולים לדעת בוודאות מה הכלב הרגיש, אבל אנחנו כן יכולים להתבונן בהתנהגות שלו ולחשוב על האפשרויות."},{"id":"article-paragraph-91d96b8ec972","heading":"איך אני עובד על התמודדות עם תסכול בטיפול בעזרת כלבים?","text":"ואז אנחנו חוזרים לילד."},{"id":"article-paragraph-263f71961e3b","heading":"איך אני עובד על התמודדות עם תסכול בטיפול בעזרת כלבים?","text":"מה אתה הרגשת כשהוא לא הצליח? זה הזכיר לך מצב אחר? מתי עוד אתה מרגיש ככה? מה אתה עושה בדרך כלל כשמשהו לא מצליח לך?"},{"id":"article-paragraph-ac5f567f72aa","heading":"איך אני עובד על התמודדות עם תסכול בטיפול בעזרת כלבים?","text":"כך התסכול הופך ממשהו שהילד חווה במהלך המשחק לנושא שאפשר לזהות, להבין ולדבר עליו."},{"id":"article-heading-06ae64f0e0ad","heading":"אנחנו לא תמיד בוחרים אם להרגיש תסכול, אבל אפשר ללמוד איך להגיב אליו","text":"אנחנו לא תמיד בוחרים אם להרגיש תסכול, אבל אפשר ללמוד איך להגיב אליו"},{"id":"article-paragraph-eb058068ddbd","heading":"אנחנו לא תמיד בוחרים אם להרגיש תסכול, אבל אפשר ללמוד איך להגיב אליו","text":"זה אולי המסר המרכזי שאני מנסה להעביר לילדים."},{"id":"article-paragraph-cd2de9c28ff6","heading":"אנחנו לא תמיד בוחרים אם להרגיש תסכול, אבל אפשר ללמוד איך להגיב אליו","text":"אנחנו לא יכולים להבטיח שלא נרגיש תסכול. זה פשוט בלתי אפשרי."},{"id":"article-paragraph-0da7a764828e","heading":"אנחנו לא תמיד בוחרים אם להרגיש תסכול, אבל אפשר ללמוד איך להגיב אליו","text":"כולנו נפגוש שוב ושוב מצבים שבהם הדברים לא מתרחשים כפי שרצינו."},{"id":"article-paragraph-8a0187ac02ec","heading":"אנחנו לא תמיד בוחרים אם להרגיש תסכול, אבל אפשר ללמוד איך להגיב אליו","text":"אבל אפשר לפתח את היכולת לשים לב למה שאנחנו עושים עם התחושה הזאת."},{"id":"article-paragraph-b21a85a8bc1f","heading":"אנחנו לא תמיד בוחרים אם להרגיש תסכול, אבל אפשר ללמוד איך להגיב אליו","text":"אחת השאלות שאני אוהב לעבוד איתן היא:"},{"id":"article-paragraph-a4b7586be122","heading":"אנחנו לא תמיד בוחרים אם להרגיש תסכול, אבל אפשר ללמוד איך להגיב אליו","text":"האם הדרך שבה אני עומד להגיב עכשיו תגרום לי להרגיש טוב יותר או פחות טוב? האם היא תגדיל את התסכול שלי, או תעזור לי להתמודד איתו?"},{"id":"article-paragraph-9f6c75541dcb","heading":"אנחנו לא תמיד בוחרים אם להרגיש תסכול, אבל אפשר ללמוד איך להגיב אליו","text":"נחזור רגע לליאו."},{"id":"article-paragraph-d6109ed7a8a5","heading":"אנחנו לא תמיד בוחרים אם להרגיש תסכול, אבל אפשר ללמוד איך להגיב אליו","text":"ניסינו ללמד אותו לעשות גלגול והוא לא הצליח."},{"id":"article-paragraph-08f68b26a34a","heading":"אנחנו לא תמיד בוחרים אם להרגיש תסכול, אבל אפשר ללמוד איך להגיב אליו","text":"אפשר להתעצבן עליו, לצעוק שהוא לא מקשיב, להגיד שהוא כלב מעצבן ולהפסיק את הפעילות בכעס."},{"id":"article-paragraph-373a36ba071f","heading":"אנחנו לא תמיד בוחרים אם להרגיש תסכול, אבל אפשר ללמוד איך להגיב אליו","text":"אבל מה יקרה אז? האם נרגיש פחות מתוסכלים? האם ליאו יבין טוב יותר מה רצינו?"},{"id":"article-paragraph-e1101df8c465","heading":"אנחנו לא תמיד בוחרים אם להרגיש תסכול, אבל אפשר ללמוד איך להגיב אליו","text":"סביר להניח שלא. הכעס עלול רק להגביר את המתח של שנינו."},{"id":"article-paragraph-f158ddaa630f","heading":"אנחנו לא תמיד בוחרים אם להרגיש תסכול, אבל אפשר ללמוד איך להגיב אליו","text":"לעומת זאת, אפשר לנסות משהו אחר."},{"id":"article-paragraph-05cda50fa8de","heading":"אנחנו לא תמיד בוחרים אם להרגיש תסכול, אבל אפשר ללמוד איך להגיב אליו","text":"לעצור רגע, ללטף את ליאו אם הוא מעוניין במגע, להגיד לו \"לא נורא\", ולבחור לעשות יחד תרגיל אחר שהוא כן יודע."},{"id":"article-paragraph-1b7aaa721377","heading":"אנחנו לא תמיד בוחרים אם להרגיש תסכול, אבל אפשר ללמוד איך להגיב אליו","text":"פתאום שנינו יכולים לחוות הצלחה. אנחנו מסיימים את הפעילות בתחושה נעימה יותר, במקום להמשיך להיאבק במשהו שלא מצליח."},{"id":"article-paragraph-ec6c3cdaa4a4","heading":"אנחנו לא תמיד בוחרים אם להרגיש תסכול, אבל אפשר ללמוד איך להגיב אליו","text":"זאת בדיוק המיומנות שאני רוצה לעזור לילד לפתח."},{"id":"article-paragraph-a0b761d25faa","heading":"אנחנו לא תמיד בוחרים אם להרגיש תסכול, אבל אפשר ללמוד איך להגיב אליו","text":"לא להימנע מכל קושי, ולא לוותר אוטומטית בכל פעם שמשהו לא עובד, אלא להבין מתי כדאי לנסות שוב, מתי כדאי לשנות דרך ומתי נכון לקבל שמשהו פשוט לא אפשרי כרגע."},{"id":"article-heading-6358f8298bb4","heading":"אפשר ללמוד להתמודד עם תסכול גם דרך משחק","text":"אפשר ללמוד להתמודד עם תסכול גם דרך משחק"},{"id":"article-paragraph-44b889b444df","heading":"אפשר ללמוד להתמודד עם תסכול גם דרך משחק","text":"דרך נוספת שבה אני עובד על התמודדות עם תסכול היא משחק."},{"id":"article-paragraph-f5ccc1071bf2","heading":"אפשר ללמוד להתמודד עם תסכול גם דרך משחק","text":"למשל, יש לי משחק שבו צריך להניח דמויות קטנות של כלבים על מבנה עץ לא יציב. זורקים קובייה, ובהתאם למספר שיוצא צריך להניח כלב על המבנה, בלי שייפול."},{"id":"article-paragraph-9ce491799eaf","heading":"אפשר ללמוד להתמודד עם תסכול גם דרך משחק","text":"במהלך המשחק אני יכול ליצור הפרעה קטנה ומבוקרת, למשל להזיז את המבנה כך שחלק ממנו יתפרק."},{"id":"article-paragraph-a7b11bf4ae82","heading":"אפשר ללמוד להתמודד עם תסכול גם דרך משחק","text":"זאת סיטואציה שיכולה לעורר הרבה תסכול."},{"id":"article-paragraph-ac7e7e68cdbe","heading":"אפשר ללמוד להתמודד עם תסכול גם דרך משחק","text":"הילד השקיע, ניסה להצליח, ופתאום מישהו אחר מפריע לו."},{"id":"article-paragraph-c682e9c392c7","heading":"אפשר ללמוד להתמודד עם תסכול גם דרך משחק","text":"כשהקשר מאפשר זאת, אפשר להשתמש ברגע הזה כדי לבדוק יחד מה קרה."},{"id":"article-paragraph-1a5714dbb31b","heading":"אפשר ללמוד להתמודד עם תסכול גם דרך משחק","text":"מה הרגשת כשהפלתי לך את המבנה? מה רצית לעשות? האם רצית לכעוס עליי, לצעוק או להחזיר לי?"},{"id":"article-paragraph-e43e47004728","heading":"אפשר ללמוד להתמודד עם תסכול גם דרך משחק","text":"ואז אנחנו חושבים על האפשרויות."},{"id":"article-paragraph-371af4d938eb","heading":"אפשר ללמוד להתמודד עם תסכול גם דרך משחק","text":"אפשר להתעצבן עליי ולהתחיל לריב איתי. יכול להיות שזה יוביל לכך שגם אני אתעצבן, והמשחק ייהרס לגמרי."},{"id":"article-paragraph-242e0b7259b4","heading":"אפשר ללמוד להתמודד עם תסכול גם דרך משחק","text":"אבל אולי אפשר להגיב אחרת. למשל, להגיד לי שזה מפריע, לבקש שאפסיק או אפילו להזמין אותי לעזור לבנות מחדש."},{"id":"article-paragraph-e87eb673f7f8","heading":"אפשר ללמוד להתמודד עם תסכול גם דרך משחק","text":"כך אפשר לעבור מריב ומאבק לניסיון לפתור את הבעיה."},{"id":"article-paragraph-c387d8dddb0f","heading":"אפשר ללמוד להתמודד עם תסכול גם דרך משחק","text":"כמובן, חשוב שההתנסות תישאר משחקית, מותאמת ונסבלת עבור הילד. אם היא פוגעת בתחושת הביטחון או מציפה אותו מעבר ליכולתו, היא כבר לא משרתת את המטרה הטיפולית."},{"id":"article-heading-a7e5aa1f0bc1","heading":"איך לוקחים את מה שקרה במשחק לחיים האמיתיים?","text":"איך לוקחים את מה שקרה במשחק לחיים האמיתיים?"},{"id":"article-paragraph-6eb46285c813","heading":"איך לוקחים את מה שקרה במשחק לחיים האמיתיים?","text":"הפעילות עם הכלב או המשחק הם רק נקודת ההתחלה."},{"id":"article-paragraph-a7bb579d772e","heading":"איך לוקחים את מה שקרה במשחק לחיים האמיתיים?","text":"אחרי שהילד הצליח לזהות את התסכול בתוך המפגש, אנחנו מנסים לחבר את הדברים לחיים שלו."},{"id":"article-paragraph-a5aadcb9b9b2","heading":"איך לוקחים את מה שקרה במשחק לחיים האמיתיים?","text":"אני יכול לשאול אותו מתי לאחרונה הרגיש תסכול בבית או בבית הספר."},{"id":"article-paragraph-e82d1a300c0f","heading":"איך לוקחים את מה שקרה במשחק לחיים האמיתיים?","text":"למשל, כשהוא רב עם חבר."},{"id":"article-paragraph-8fc7e6a5a4ab","heading":"איך לוקחים את מה שקרה במשחק לחיים האמיתיים?","text":"החבר עשה משהו שהכעיס אותו, והוא בתגובה הרביץ לו."},{"id":"article-paragraph-35c7a34622eb","heading":"איך לוקחים את מה שקרה במשחק לחיים האמיתיים?","text":"אנחנו יכולים לנסות להבין מה קרה שם: מה הוא רצה שיקרה? מה עורר את התסכול? האם התגובה שלו פתרה את הבעיה? האם הוא הרגיש טוב יותר אחריה, או שבסופו של דבר מצא את עצמו גם כועס, גם רב עם החבר וגם מסתבך?"},{"id":"article-paragraph-ef741a94e09e","heading":"איך לוקחים את מה שקרה במשחק לחיים האמיתיים?","text":"או מצב אחר: אמא אמרה לו לא."},{"id":"article-paragraph-81cca862a606","heading":"איך לוקחים את מה שקרה במשחק לחיים האמיתיים?","text":"הוא כעס, צעק ושבר משהו."},{"id":"article-paragraph-d29d80912d96","heading":"איך לוקחים את מה שקרה במשחק לחיים האמיתיים?","text":"האם זה עזר לו לקבל את מה שרצה? מה קרה אחר כך? האם הייתה דרך אחרת שבה יכול היה לבטא את הכעס שלו מבלי לפגוע בעצמו או באחרים?"},{"id":"article-paragraph-f3371c8c7a50","heading":"איך לוקחים את מה שקרה במשחק לחיים האמיתיים?","text":"המטרה היא לא לגרום לילד להרגיש אשם על מה שעשה, אלא לעזור לו לפתח מודעות ואפשרויות נוספות."},{"id":"article-paragraph-9efdf7def00a","heading":"איך לוקחים את מה שקרה במשחק לחיים האמיתיים?","text":"לפעמים נגלה שהתגובה שלו רק הגבירה את התסכול המקורי. ולפעמים הוא ילמד שדווקא בקשת עזרה, שיחה, התרחקות רגעית או שינוי בתוכנית יכולים לעזור לו להתמודד טוב יותר."},{"id":"article-heading-09661640b920","heading":"איך הורים יכולים לעזור לילדים להתמודד עם תסכול?","text":"איך הורים יכולים לעזור לילדים להתמודד עם תסכול?"},{"id":"article-paragraph-12efdbfa18c8","heading":"איך הורים יכולים לעזור לילדים להתמודד עם תסכול?","text":"אני חושב שאחת הטעויות שאנחנו יכולים לעשות כמבוגרים היא לנסות למנוע מהילדים שלנו כל תסכול."},{"id":"article-paragraph-f5a3bc9afc24","heading":"איך הורים יכולים לעזור לילדים להתמודד עם תסכול?","text":"זה מובן. קשה לנו לראות את הילדים שלנו מאוכזבים, עצובים או כועסים, ולפעמים הרבה יותר פשוט לפתור עבורם את הבעיה."},{"id":"article-paragraph-02f3e85c5443","heading":"איך הורים יכולים לעזור לילדים להתמודד עם תסכול?","text":"אבל אם נפתור עבורם כל קושי, נפספס הזדמנויות שבהן הם יכולים לגלות שהם מסוגלים להתמודד."},{"id":"article-paragraph-68881b994a5c","heading":"איך הורים יכולים לעזור לילדים להתמודד עם תסכול?","text":"מצד שני, גם להשאיר ילד לבד עם תסכול גדול מדי לא בהכרח יעזור לו לפתח את היכולת הזאת."},{"id":"article-paragraph-1ed6da55fc17","heading":"איך הורים יכולים לעזור לילדים להתמודד עם תסכול?","text":"המפתח נמצא במידה רבה בקשר ובתמיכה שאנחנו מספקים."},{"id":"article-paragraph-23699e00b051","heading":"איך הורים יכולים לעזור לילדים להתמודד עם תסכול?","text":"כשהילד מתוסכל, אפשר קודם כול לתת מקום למה שהוא מרגיש. להבין שהוא באמת רצה משהו, שזה באמת מאכזב או שהמשימה באמת קשה לו. לעזור לו לתת שם לרגש שהוא חווה עכשיו - \"אני רואה שאתה מתוסכל, זה באמת יכול להיות מאוד מתסכל כשאנחנו לא מקבלים את מה שרצינו\"."},{"id":"article-paragraph-ca646930d230","heading":"איך הורים יכולים לעזור לילדים להתמודד עם תסכול?","text":"זה לא אומר שחייבים לוותר על הגבול שהצבנו."},{"id":"article-paragraph-4e7987c93310","heading":"איך הורים יכולים לעזור לילדים להתמודד עם תסכול?","text":"אפשר להבין את הכעס שלו ובו בזמן להישאר עם ההחלטה שלנו."},{"id":"article-paragraph-8752810bc687","heading":"איך הורים יכולים לעזור לילדים להתמודד עם תסכול?","text":"כשהילד רגוע מספיק, אפשר לחשוב איתו יחד על מה שקרה. מה הוא הרגיש? מה ניסה להשיג? האם הדרך שבה הגיב עזרה לו? ומה יוכל לעשות אחרת בפעם הבאה?"},{"id":"article-paragraph-3c0131ab7099","heading":"איך הורים יכולים לעזור לילדים להתמודד עם תסכול?","text":"חשוב גם לזכור שלא תמיד צריך ללמד משהו באותו רגע."},{"id":"article-paragraph-553014aeabad","heading":"איך הורים יכולים לעזור לילדים להתמודד עם תסכול?","text":"כשהילד מוצף מאוד, לפעמים הוא זקוק בעיקר למבוגר שיהיה איתו, יעזור לו להירגע ולא יהפוך את התסכול המקורי לעוד מאבק."},{"id":"article-paragraph-cbfeae5435e3","heading":"איך הורים יכולים לעזור לילדים להתמודד עם תסכול?","text":"אחר כך, כשהוא פנוי לכך, אפשר לחזור ולדבר."},{"id":"article-heading-501269f79116","heading":"לסיכום – לא צריך למנוע תסכול, צריך ללמוד להתמודד איתו","text":"לסיכום – לא צריך למנוע תסכול, צריך ללמוד להתמודד איתו"},{"id":"article-paragraph-53c6d0227ac9","heading":"לסיכום – לא צריך למנוע תסכול, צריך ללמוד להתמודד איתו","text":"תסכול הוא חלק מהחיים. הוא מופיע בכל גיל, בכל מערכת יחסים וכמעט בכל תחום."},{"id":"article-paragraph-213be57ccd62","heading":"לסיכום – לא צריך למנוע תסכול, צריך ללמוד להתמודד איתו","text":"אנחנו לא יכולים להבטיח לילדים שלנו שהכול יצליח להם, שכולם יסכימו איתם או שתמיד יקבלו את מה שהם רוצים."},{"id":"article-paragraph-279ee66a858b","heading":"לסיכום – לא צריך למנוע תסכול, צריך ללמוד להתמודד איתו","text":"אבל אנחנו כן יכולים לעזור להם לפתח את היכולת להתמודד עם מציאות שלא תמיד מתאימה לרצונות שלהם."},{"id":"article-paragraph-5a8238c6ad4e","heading":"לסיכום – לא צריך למנוע תסכול, צריך ללמוד להתמודד איתו","text":"בטיפול רגשי בעזרת כלבים, אני מנסה ליצור הזדמנויות שבהן ילדים יכולים לפגוש תסכול, לזהות אותו, להבין איך הם מגיבים אליו ולגלות דרכים נוספות להתמודד."},{"id":"article-paragraph-0c984220e00d","heading":"לסיכום – לא צריך למנוע תסכול, צריך ללמוד להתמודד איתו","text":"אבל כל זה מתחיל בקשר."},{"id":"article-paragraph-55ee3db083e1","heading":"לסיכום – לא צריך למנוע תסכול, צריך ללמוד להתמודד איתו","text":"רק כשהילד מרגיש מספיק בטוח, אפשר לאפשר לו להתמודד עם קושי מבלי שהכישלון יהפוך לאיום על תחושת הערך שלו או על הקשר הטיפולי."},{"id":"article-paragraph-8df1f87b9d84","heading":"לסיכום – לא צריך למנוע תסכול, צריך ללמוד להתמודד איתו","text":"המטרה היא לא שילדים יפסיקו להרגיש תסכול. המטרה היא שהם יגלו שגם כשהדברים לא מסתדרים כפי שרצו, הם מסוגלים להתמודד, למצוא דרכים אחרות ולהמשיך הלאה."}]},{"title":"סבלנות ודחיית סיפוקים אצל ילדים - איך מפתחים את היכולת לחכות?","url":"https://derech-hakelev.com/pages/articles/patience-delayed-gratification-children/","entries":[{"id":"article-title-a66b02bb2b08","heading":"תחילת המאמר","text":"סבלנות ודחיית סיפוקים אצל ילדים - איך מפתחים את היכולת לחכות?"},{"id":"article-paragraph-8a8f735cb3da","heading":"פתיחת המאמר","text":"הילד מתקשה לחכות לתור שלו? רוצה לקבל הכול כאן ועכשיו? מתעצבן כשאומרים לו שצריך לחכות, או מתקשה להתאפק גם כשהוא יודע שכדאי לו?"},{"id":"article-paragraph-05383ddf780f","heading":"פתיחת המאמר","text":"סבלנות ודחיית סיפוקים הן יכולות שאנחנו משתמשים בהן כמעט בכל תחום בחיים. הן מאפשרות לנו להתמודד עם רצונות שלא מתממשים מיד, להשקיע מאמץ במטרות ארוכות טווח ולהתנהל גם כשהדברים לא קורים בדיוק בקצב שהיינו רוצים."},{"id":"article-paragraph-060081fc6207","heading":"פתיחת המאמר","text":"אבל אנחנו לא נולדים עם היכולות האלה כשהן מפותחות."},{"id":"article-paragraph-27f0c8e963e2","heading":"פתיחת המאמר","text":"תינוק שרעב רוצה לאכול עכשיו. הוא לא מבין שאמא מכינה לו בקבוק ושבעוד כמה דקות האוכל יהיה מוכן. גם אם נסביר לו שכדאי לחכות בסבלנות, זה לא ממש יעזור."},{"id":"article-paragraph-3768995c18e8","heading":"פתיחת המאמר","text":"עם השנים, ככל שאנחנו מתפתחים, אנחנו לומדים בהדרגה להתמודד עם ההמתנה, לדחות רצונות מסוימים ולבחור לפעמים במה שישתלם לנו יותר בהמשך."},{"id":"article-paragraph-a6d4f858f292","heading":"פתיחת המאמר","text":"אצל חלק מהילדים היכולת הזאת מתפתחת בקלות יחסית, ואצל אחרים היא דורשת יותר זמן, תמיכה והתנסות."},{"id":"article-paragraph-86ff6a528283","heading":"פתיחת המאמר","text":"אז איך אפשר לעזור לילדים לפתח סבלנות ודחיית סיפוקים? ואיך אפשר לעבוד על היכולות האלה דווקא דרך טיפול רגשי בעזרת כלבים?"},{"id":"article-heading-37c4448cbb20","heading":"מה ההבדל בין סבלנות לדחיית סיפוקים?","text":"מה ההבדל בין סבלנות לדחיית סיפוקים?"},{"id":"article-paragraph-270e0193fb71","heading":"מה ההבדל בין סבלנות לדחיית סיפוקים?","text":"סבלנות היא היכולת לשאת המתנה, קושי או עיכוב מבלי לאבד מיד את היכולת להתמודד עם המצב."},{"id":"article-paragraph-45d3731c8860","heading":"מה ההבדל בין סבלנות לדחיית סיפוקים?","text":"למשל, לחכות בתור, להמשיך לנסות משהו שלא מצליח בפעם הראשונה או להתמודד עם מצב שבו הדברים מתקדמים לאט יותר ממה שהיינו רוצים."},{"id":"article-paragraph-bbf289534add","heading":"מה ההבדל בין סבלנות לדחיית סיפוקים?","text":"דחיית סיפוקים היא יכולת מעט שונה: היכולת לוותר על סיפוק מיידי, או לדחות אותו, כדי להשיג משהו אחר בהמשך."},{"id":"article-paragraph-386f0d303c01","heading":"מה ההבדל בין סבלנות לדחיית סיפוקים?","text":"למשל, ילד שמעדיף לשמור את דמי הכיס שלו במשך כמה שבועות כדי לקנות משהו שהוא מאוד רוצה, במקום לבזבז אותם מיד על משהו קטן."},{"id":"article-paragraph-325c2d0c4e75","heading":"מה ההבדל בין סבלנות לדחיית סיפוקים?","text":"שתי היכולות קשורות לוויסות עצמי, לשליטה בדחפים וליכולת שלנו לפעול בהתאם למטרות שלנו, גם כשיש משהו שמושך אותנו לעשות אחרת באותו רגע."},{"id":"article-heading-2cd5842218e4","heading":"למה סבלנות ודחיית סיפוקים כל כך חשובות?","text":"למה סבלנות ודחיית סיפוקים כל כך חשובות?"},{"id":"article-paragraph-29b80e5b19f2","heading":"למה סבלנות ודחיית סיפוקים כל כך חשובות?","text":"לפעמים אנחנו חושבים על סבלנות בעיקר בהקשר של ילדים: לחכות בתור, לא להתפרץ לדברי אחרים או להמתין עד שההורה יתפנה."},{"id":"article-paragraph-61e2112902f8","heading":"למה סבלנות ודחיית סיפוקים כל כך חשובות?","text":"אבל ככל שאנחנו מתבגרים, אנחנו מבינים עד כמה היכולת הזאת משמעותית כמעט בכל תחום בחיים."},{"id":"article-paragraph-f4893d137b93","heading":"למה סבלנות ודחיית סיפוקים כל כך חשובות?","text":"בלימודים, אנחנו צריכים להשקיע ולהתאמץ גם כשלא רואים תוצאה מיידית. בעבודה, אנחנו צריכים לפעמים להתמיד לאורך זמן עד שמגיעים להישגים. בזוגיות ובמערכות יחסים ובטח שבהורות, אנחנו נדרשים להקשיב, להתפשר ולהתמודד עם העובדה שלא תמיד הרצונות שלנו מתממשים מיד."},{"id":"article-paragraph-933e93ffe928","heading":"למה סבלנות ודחיית סיפוקים כל כך חשובות?","text":"היכולת לחכות, להתאפק ולהתמיד גם כשקשה מאפשרת לנו לפעול בהתאם למה שחשוב לנו, ולא רק בהתאם למה שאנחנו רוצים באותו רגע."},{"id":"article-paragraph-faed7e507792","heading":"למה סבלנות ודחיית סיפוקים כל כך חשובות?","text":"אבל חשוב לי להדגיש: סבלנות היא לא היכולת לשתוק, לציית או לוותר על הרצונות שלנו. היא היכולת להתמודד עם ההמתנה ועם הקושי, ולבחור כיצד לפעול."},{"id":"article-heading-f8837502338a","heading":"איך מתפתחת היכולת לדחות סיפוקים אצל ילדים?","text":"איך מתפתחת היכולת לדחות סיפוקים אצל ילדים?"},{"id":"article-paragraph-830871326494","heading":"איך מתפתחת היכולת לדחות סיפוקים אצל ילדים?","text":"כמו יכולות רגשיות והתפתחותיות רבות, גם סבלנות ודחיית סיפוקים מתפתחות בהדרגה."},{"id":"article-paragraph-113f7c8fc482","heading":"איך מתפתחת היכולת לדחות סיפוקים אצל ילדים?","text":"בתחילת החיים, תינוקות תלויים מאוד במבוגרים כדי לספק את הצרכים שלהם ולעזור להם להירגע. כשהם רעבים, עייפים או לא מרגישים בנוח, הם זקוקים למישהו שיענה לצורך שלהם."},{"id":"article-paragraph-0e89ff567c8c","heading":"איך מתפתחת היכולת לדחות סיפוקים אצל ילדים?","text":"עם הזמן, ילדים מתחילים להבין שלא כל דבר יכול לקרות מיד."},{"id":"article-paragraph-82bd1f3ffeb4","heading":"איך מתפתחת היכולת לדחות סיפוקים אצל ילדים?","text":"בהתחלה הם מסוגלים להמתין לזמן קצר מאוד, ובהמשך יכולים ללמוד לחכות יותר, להתמודד עם הסחות דעת ולמצוא דרכים שיעזרו להם בזמן ההמתנה."},{"id":"article-paragraph-405f61166b15","heading":"איך מתפתחת היכולת לדחות סיפוקים אצל ילדים?","text":"ההתפתחות הזאת קשורה בין היתר להבשלה של יכולות כמו ויסות רגשי, קשב, תכנון ועיכוב תגובה."},{"id":"article-paragraph-5094f39bf5a2","heading":"איך מתפתחת היכולת לדחות סיפוקים אצל ילדים?","text":"סקירה מחקרית רחבה שפורסמה בשנת 2023 בכתב העת Developmental Review, והתבססה על 136 מאמרי סקירה ומטא-אנליזות, בחנה את התפתחות הוויסות העצמי מהינקות ועד גיל ההתבגרות."},{"id":"article-paragraph-0d478539757b","heading":"איך מתפתחת היכולת לדחות סיפוקים אצל ילדים?","text":"הסקירה מתארת כיצד הוויסות מתפתח מתהליך שתלוי מאוד בעזרת המבוגרים בתחילת החיים, ליכולת עצמאית ומורכבת יותר ככל שהילד גדל. היא גם מדגישה את תפקידם של ההורים, המורים והסביבה החברתית בהתפתחות היכולת הזאת."},{"id":"article-paragraph-69d9e62359cd","heading":"איך מתפתחת היכולת לדחות סיפוקים אצל ילדים?","text":"ההתפתחות לא מתרחשת אצל כולם באותו הקצב."},{"id":"article-paragraph-ace4b9be5fc0","heading":"איך מתפתחת היכולת לדחות סיפוקים אצל ילדים?","text":"גם הסביבה והקשרים של הילד משפיעים על התהליך. ילד שמקבל תמיכה כשהוא מתקשה ושיש לו הזדמנויות מותאמות להתמודד עם המתנה, יכול לפתח בהדרגה יותר כלים להתמודדות."},{"id":"article-paragraph-5868d1e6bd09","heading":"איך מתפתחת היכולת לדחות סיפוקים אצל ילדים?","text":"ולא פחות חשוב, גם אצל מבוגרים היכולת הזאת אינה מושלמת. כולנו מכירים רגעים שבהם קשה לנו להתאפק, לחכות או לדחות משהו שאנחנו מאוד רוצים."},{"id":"article-paragraph-bc453db71216","heading":"איך מתפתחת היכולת לדחות סיפוקים אצל ילדים?","text":"לקריאה נוספת: הגישה ההתפתחותית־היקשרותית בטיפול בעזרת כלבים – על החשיבות של קשר וביטחון בהתפתחות הרגשית של ילדים."},{"id":"article-heading-5e04db0d9591","heading":"מתי קושי בדחיית סיפוקים הוא טבעי ומתי הוא הופך לבעיה?","text":"מתי קושי בדחיית סיפוקים הוא טבעי ומתי הוא הופך לבעיה?"},{"id":"article-paragraph-62a0064a7f2b","heading":"מתי קושי בדחיית סיפוקים הוא טבעי ומתי הוא הופך לבעיה?","text":"לא כל ילד שמתקשה לחכות הוא ילד שיש לו בעיה."},{"id":"article-paragraph-aa9eb998ae30","heading":"מתי קושי בדחיית סיפוקים הוא טבעי ומתי הוא הופך לבעיה?","text":"ילד קטן שמתקשה לחכות לממתק או מתעצבן כשצריך להפסיק משחק מתנהג לעיתים באופן שמתאים לגילו ולשלב ההתפתחותי שלו."},{"id":"article-paragraph-4edb86fec583","heading":"מתי קושי בדחיית סיפוקים הוא טבעי ומתי הוא הופך לבעיה?","text":"גם ילדים גדולים יותר יכולים להתקשות במיוחד כשהם עייפים, רעבים, מתרגשים או נמצאים במצב רגשי מורכב."},{"id":"article-paragraph-f0c30ee4981b","heading":"מתי קושי בדחיית סיפוקים הוא טבעי ומתי הוא הופך לבעיה?","text":"השאלה היא עד כמה הקושי חוזר על עצמו ועד כמה הוא משפיע על החיים של הילד."},{"id":"article-paragraph-b7dac89c83bc","heading":"מתי קושי בדחיית סיפוקים הוא טבעי ומתי הוא הופך לבעיה?","text":"למשל, ילד שמתקשה כמעט תמיד לחכות לתורו, מתפרץ שוב ושוב לדברי אחרים, מתקשה להשלים משימות שדורשות התמדה או מגיב בעוצמה גדולה בכל פעם שלא מקבל מיד את מה שרצה."},{"id":"article-paragraph-3114dd09157f","heading":"מתי קושי בדחיית סיפוקים הוא טבעי ומתי הוא הופך לבעיה?","text":"אם הקשיים האלה פוגעים באופן משמעותי בלימודים, בחברויות או בהתנהלות בבית, כדאי להבין מה עומד מאחוריהם."},{"id":"article-paragraph-67ee02444c77","heading":"מתי קושי בדחיית סיפוקים הוא טבעי ומתי הוא הופך לבעיה?","text":"לפעמים מדובר בקושי בוויסות רגשי, לפעמים בקשיי קשב או בתפקודים ניהוליים, ולפעמים יש גורמים אחרים שמשפיעים על יכולתו של הילד להמתין."},{"id":"article-paragraph-fd9b3222f11d","heading":"מתי קושי בדחיית סיפוקים הוא טבעי ומתי הוא הופך לבעיה?","text":"המטרה היא לא לצפות מכל ילד להיות סבלני כל הזמן, אלא להבין מה מתאים לשלב ההתפתחותי שלו ואיך אפשר לעזור לו להתקדם."},{"id":"article-paragraph-bcca9f8e6961","heading":"מתי קושי בדחיית סיפוקים הוא טבעי ומתי הוא הופך לבעיה?","text":"אפשר לקרוא על כך גם במאמר ויסות רגשי אצל ילדים – איך טיפול בעזרת כלבים יכול לעזור?."},{"id":"article-heading-dcf53e94505c","heading":"מה אפשר ללמוד ממבחן המרשמלו?","text":"מה אפשר ללמוד ממבחן המרשמלו?"},{"id":"article-paragraph-24d74288d0f4","heading":"מה אפשר ללמוד ממבחן המרשמלו?","text":"אחד הניסויים המוכרים ביותר בפסיכולוגיה הוא מבחן המרשמלו, שפותח במסגרת מחקריו של הפסיכולוג וולטר מישל."},{"id":"article-paragraph-c1f6b337fc32","heading":"מה אפשר ללמוד ממבחן המרשמלו?","text":"בניסוי המפורסם, הציעו לילדים לקבל ממתק אחד מיד, או להמתין זמן מסוים ולקבל שני ממתקים בהמשך."},{"id":"article-paragraph-265458798d23","heading":"מה אפשר ללמוד ממבחן המרשמלו?","text":"הילדים היו צריכים להתמודד עם בחירה: האם לקחת עכשיו משהו שהם רוצים, או לחכות כדי לקבל יותר אחר כך?"},{"id":"article-paragraph-718874700686","heading":"מה אפשר ללמוד ממבחן המרשמלו?","text":"החוקרים התעניינו לא רק בשאלה כמה זמן הילדים מצליחים לחכות, אלא גם בדרכים שבהן הם מתמודדים עם ההמתנה."},{"id":"article-paragraph-190511dab048","heading":"מה אפשר ללמוד ממבחן המרשמלו?","text":"חלק מהילדים ניסו להסיח את דעתם, חלקם הסתכלו לכיוון אחר, וחלקם מצאו דרכים שונות להעביר את הזמן."},{"id":"article-paragraph-4e3f36a2b7cb","heading":"מה אפשר ללמוד ממבחן המרשמלו?","text":"הניסוי הזה הפך למוכר מאוד, בין היתר משום שמחקרים מוקדמים מצאו קשר בין היכולת לחכות בילדות לבין הישגים בהמשך החיים."},{"id":"article-paragraph-8ca77ec92fe1","heading":"מה אפשר ללמוד ממבחן המרשמלו?","text":"אבל מחקרי המשך הציגו תמונה מורכבת יותר."},{"id":"article-paragraph-70dc5771fa55","heading":"מה אפשר ללמוד ממבחן המרשמלו?","text":"בשנת 2018 פורסם מחקר שבחן מחדש את הקשר בין דחיית סיפוקים בילדות לבין הישגים בגיל ההתבגרות. החוקרים מצאו שהקשר נחלש משמעותית כאשר מביאים בחשבון את הרקע המשפחתי, היכולות המוקדמות והסביבה שבה הילד גדל."},{"id":"article-paragraph-fb2fab12944c","heading":"מה אפשר ללמוד ממבחן המרשמלו?","text":"במחקר נוסף שפורסם בשנת 2024, ועקב אחר 702 משתתפים עד גיל 26, נמצא שהביצועים במבחן המרשמלו בילדות לא ניבאו באופן מהימן את ההישגים, הבריאות וההתנהגות בבגרות."},{"id":"article-paragraph-8cb76bd1c504","heading":"מה אפשר ללמוד ממבחן המרשמלו?","text":"המשמעות היא שהמבחן לא קובע את עתידו של הילד, ושהיכולת לחכות מושפעת גם מהסביבה ומהנסיבות."},{"id":"article-paragraph-3a3a5c422796","heading":"מה אפשר ללמוד ממבחן המרשמלו?","text":"מבחינתי, הדבר המעניין ביותר במבחן הוא דווקא האפשרות להשתמש בו כדי להבין מה עוזר לילד לחכות, מה מקשה עליו ואילו אסטרטגיות הוא יכול לפתח."},{"id":"article-heading-6231c7cf21df","heading":"איך אני עובד על סבלנות ודחיית סיפוקים בטיפול בעזרת כלבים?","text":"איך אני עובד על סבלנות ודחיית סיפוקים בטיפול בעזרת כלבים?"},{"id":"article-paragraph-b2eb7dbf37ab","heading":"איך אני עובד על סבלנות ודחיית סיפוקים בטיפול בעזרת כלבים?","text":"אחת הדרכים שאני אוהב לעבוד על היכולות האלה היא דווקא דרך הכלבים."},{"id":"article-paragraph-12af21687471","heading":"איך אני עובד על סבלנות ודחיית סיפוקים בטיפול בעזרת כלבים?","text":"כשחושבים על זה, גם לכלבים לא תמיד קל לחכות."},{"id":"article-paragraph-8580d9ef323c","heading":"איך אני עובד על סבלנות ודחיית סיפוקים בטיפול בעזרת כלבים?","text":"הם רוצים להגיע לאוכל, לרוץ אחרי כדור, לקבל חטיף, לצאת לטיול או לגשת למשהו שמעניין אותם."},{"id":"article-paragraph-bf5d2ec7d0c1","heading":"איך אני עובד על סבלנות ודחיית סיפוקים בטיפול בעזרת כלבים?","text":"וכאן נוצרת הזדמנות מעניינת: במקום להסביר לילד רק למה חשוב לחכות בסבלנות, אנחנו יכולים להתנסות בזה יחד עם הכלבים."},{"id":"article-paragraph-74fc54bd10ba","heading":"איך אני עובד על סבלנות ודחיית סיפוקים בטיפול בעזרת כלבים?","text":"במהלך הפעילות הילד גם לומד לעזור לכלב להתמודד עם ההמתנה, וגם מקבל הזדמנות להתבונן בקושי שלו עצמו."},{"id":"article-heading-0ff7b63115e0","heading":"מתחילים מ\"להישאר\"","text":"מתחילים מ\"להישאר\""},{"id":"article-paragraph-7f6f3fead9ba","heading":"איך אני עובד על סבלנות ודחיית סיפוקים בטיפול בעזרת כלבים?","text":"אחת הפעילויות הראשונות שאנחנו עושים היא עבודה על הפקודה \"להישאר\"."},{"id":"article-paragraph-6ebf3aaf868d","heading":"איך אני עובד על סבלנות ודחיית סיפוקים בטיפול בעזרת כלבים?","text":"אנחנו מבקשים מהכלב לשבת או לשכב, ולאחר מכן להישאר במקום בזמן שאנחנו מתרחקים ממנו."},{"id":"article-paragraph-1224ea4351f7","heading":"איך אני עובד על סבלנות ודחיית סיפוקים בטיפול בעזרת כלבים?","text":"בהתחלה מתרחקים ממש מעט, חוזרים אל הכלב ומחזקים אותו על ההצלחה. בהדרגה אפשר להגדיל את המרחק ואת משך ההמתנה, בהתאם ליכולת שלו."},{"id":"article-paragraph-18378cf28e61","heading":"איך אני עובד על סבלנות ודחיית סיפוקים בטיפול בעזרת כלבים?","text":"לכאורה מדובר בתרגיל אילוף פשוט, אבל אפשר ללמוד ממנו לא מעט."},{"id":"article-paragraph-af611c6a83e7","heading":"איך אני עובד על סבלנות ודחיית סיפוקים בטיפול בעזרת כלבים?","text":"לכלב לא תמיד קל להישאר במקום. הוא אולי רוצה ללכת אחרי הילד, להתקרב אליו או להתחיל לשחק."},{"id":"article-paragraph-81b751635b2e","heading":"איך אני עובד על סבלנות ודחיית סיפוקים בטיפול בעזרת כלבים?","text":"הילד צריך ללמוד להתקדם בהדרגה, לתת לכלב הוראות ברורות ולא לצפות ממנו להצליח מיד במשימה קשה מדי."},{"id":"article-paragraph-206ad02bb1b3","heading":"איך אני עובד על סבלנות ודחיית סיפוקים בטיפול בעזרת כלבים?","text":"גם הילד עצמו נדרש לסבלנות."},{"id":"article-paragraph-12f12dc9548e","heading":"איך אני עובד על סבלנות ודחיית סיפוקים בטיפול בעזרת כלבים?","text":"לפעמים הכלב קם לפני הזמן, לפעמים צריך לחזור על התרגיל, ולפעמים ההתקדמות איטית יותר ממה שהילד ציפה."},{"id":"article-paragraph-5c0445b25191","heading":"איך אני עובד על סבלנות ודחיית סיפוקים בטיפול בעזרת כלבים?","text":"כך אנחנו בעצם עובדים על סבלנות משני הכיוונים: גם של הכלב וגם של הילד."},{"id":"article-heading-58d8704bfd73","heading":"עוברים ל\"לא לגעת\"","text":"עוברים ל\"לא לגעת\""},{"id":"article-paragraph-59f3007f3ae4","heading":"איך אני עובד על סבלנות ודחיית סיפוקים בטיפול בעזרת כלבים?","text":"אחרי שהילד והכלב מתנסים בהמתנה, אפשר לעבור לפעילות נוספת: \"לא לגעת\"."},{"id":"article-paragraph-730fb77dcdb3","heading":"איך אני עובד על סבלנות ודחיית סיפוקים בטיפול בעזרת כלבים?","text":"אנחנו מניחים חטיף במקום נגיש לכלב ומבקשים ממנו להמתין ולא לקחת אותו עד שניתן לו אישור."},{"id":"article-paragraph-2697fd4e5570","heading":"איך אני עובד על סבלנות ודחיית סיפוקים בטיפול בעזרת כלבים?","text":"ככל שהכלב לומד את התרגיל, אפשר להעלות בהדרגה את רמת הקושי. למשל, להניח את החטיף קרוב יותר אליו או על כף הרגל שלו, אם הוא כבר מכיר את התרגיל ומרגיש איתו בנוח."},{"id":"article-paragraph-0533dac0740f","heading":"איך אני עובד על סבלנות ודחיית סיפוקים בטיפול בעזרת כלבים?","text":"אפשר גם להכין יחד ציור מאוכל הכלבים בזמן שהכלב מחכה, ובסיום לתת לו אישור לאכול את הציור בהנאה."},{"id":"article-paragraph-97a706d8da74","heading":"איך אני עובד על סבלנות ודחיית סיפוקים בטיפול בעזרת כלבים?","text":"מבחינת הכלב, יש כאן משהו שהוא רוצה מאוד, נמצא ממש מולו, ובכל זאת הוא נדרש לחכות."},{"id":"article-paragraph-c5c342d98c71","heading":"איך אני עובד על סבלנות ודחיית סיפוקים בטיפול בעזרת כלבים?","text":"זה מזכיר לא מעט מצבים שאנחנו פוגשים בחיים."},{"id":"article-paragraph-271122ea7e94","heading":"איך אני עובד על סבלנות ודחיית סיפוקים בטיפול בעזרת כלבים?","text":"לפעמים אנחנו רוצים משהו עכשיו, אבל יודעים שכדאי לחכות. לפעמים אנחנו צריכים להתאפק כדי להגיע למטרה גדולה יותר."},{"id":"article-paragraph-0345cde067d9","heading":"איך אני עובד על סבלנות ודחיית סיפוקים בטיפול בעזרת כלבים?","text":"אחד הדברים המעניינים בפעילות הוא לראות איך הילד מגיב כשהכלב מתקשה."},{"id":"article-paragraph-9c35389e948f","heading":"איך אני עובד על סבלנות ודחיית סיפוקים בטיפול בעזרת כלבים?","text":"האם הוא מתעצבן כשהכלב לוקח את החטיף לפני הזמן? האם הוא מוכן להתחיל שוב? האם הוא מבין שצריך להקל על הכלב כדי לעזור לו להצליח?"},{"id":"article-paragraph-ba020c8c191f","heading":"איך אני עובד על סבלנות ודחיית סיפוקים בטיפול בעזרת כלבים?","text":"כך הפעילות לא עוסקת רק ביכולת של הכלב לדחות סיפוקים, אלא גם ביכולת של הילד להתמודד עם תהליך שמצריך סבלנות."},{"id":"article-heading-634ff2bf809f","heading":"מה קורה כשמוסיפים הסחות דעת?","text":"מה קורה כשמוסיפים הסחות דעת?"},{"id":"article-paragraph-3516fd1cf136","heading":"איך אני עובד על סבלנות ודחיית סיפוקים בטיפול בעזרת כלבים?","text":"בשלב הבא אפשר להכניס לתרגילים גם גירויים שמקשים על ההמתנה."},{"id":"article-paragraph-6470c1790748","heading":"איך אני עובד על סבלנות ודחיית סיפוקים בטיפול בעזרת כלבים?","text":"למשל, בזמן שהכלב מתרגל \"להישאר\", אני יכול לגלגל כדור במרחק מסוים או ליצור גירוי אחר שמושך את תשומת הלב שלו."},{"id":"article-paragraph-e1297d571567","heading":"איך אני עובד על סבלנות ודחיית סיפוקים בטיפול בעזרת כלבים?","text":"עכשיו, כשהכדור מתגלגל לידו, הרבה יותר קשה לו להתאפק."},{"id":"article-paragraph-e9ffdf06da9d","heading":"איך אני עובד על סבלנות ודחיית סיפוקים בטיפול בעזרת כלבים?","text":"כמובן, אנחנו מעלים את רמת הקושי בהדרגה ומתאימים אותה לכלב. המטרה היא לא להכשיל או להלחיץ אותו, אלא לאפשר לו ללמוד ולהצליח."},{"id":"article-paragraph-c7899be591cd","heading":"איך אני עובד על סבלנות ודחיית סיפוקים בטיפול בעזרת כלבים?","text":"אחרי ההתנסות אנחנו מדברים על מה שקרה."},{"id":"article-paragraph-365175cd79da","heading":"איך אני עובד על סבלנות ודחיית סיפוקים בטיפול בעזרת כלבים?","text":"למה היה לכלב קל יותר לחכות קודם? מה השתנה כשהכדור הופיע? האם יש גם דברים שמקשים עלינו לחכות?"},{"id":"article-paragraph-abc9e3e4b141","heading":"איך אני עובד על סבלנות ודחיית סיפוקים בטיפול בעזרת כלבים?","text":"למשל, הרבה יותר קשה לחכות לממתק כשהוא מונח ממש מולנו, מאשר כשהוא נמצא בארון. קשה יותר להתרכז בשיעורי הבית כשהטלפון כל הזמן מצפצף לידנו."},{"id":"article-paragraph-1cc385f9da02","heading":"איך אני עובד על סבלנות ודחיית סיפוקים בטיפול בעזרת כלבים?","text":"וכאן אנחנו מתחילים לחשוב לא רק על היכולת להתאפק, אלא גם על הדברים שמשפיעים עליה."},{"id":"article-heading-bb0aa1b0df90","heading":"מה עוזר לנו לחכות בסבלנות?","text":"מה עוזר לנו לחכות בסבלנות?"},{"id":"article-paragraph-4eb03652da74","heading":"מה עוזר לנו לחכות בסבלנות?","text":"אחרי שהילד התנסה בפעילויות עם הכלבים, אנחנו מנסים להבין יחד מה יכול לעזור גם לו."},{"id":"article-paragraph-01a6c8baaad6","heading":"מה עוזר לנו לחכות בסבלנות?","text":"אחת האפשרויות היא הסחת דעת."},{"id":"article-paragraph-b3fc5b4c5e75","heading":"מה עוזר לנו לחכות בסבלנות?","text":"לפעמים, כשאנחנו מחכים למשהו, עצם המחשבה עליו הופכת את ההמתנה לקשה יותר. אם אנחנו מוצאים משהו אחר להתעסק בו, הזמן יכול לעבור בקלות רבה יותר."},{"id":"article-paragraph-5ab58395b7ad","heading":"מה עוזר לנו לחכות בסבלנות?","text":"מחקר שפורסם בשנת 2023 בחן 144 ילדים בני כחמש, בזמן שביצעו משימה של דחיית סיפוקים."},{"id":"article-paragraph-a57ec920f2fa","heading":"מה עוזר לנו לחכות בסבלנות?","text":"החוקרים התבוננו לא רק בשאלה האם הילדים הצליחו לחכות, אלא גם בהתנהגות שלהם בזמן ההמתנה: תנועות הגוף, דיבור עצמי, מידת ההתמקדות בפרס והדרכים שבהן ניסו להתמודד עם הרצון לקבל אותו."},{"id":"article-paragraph-09130dac8a59","heading":"מה עוזר לנו לחכות בסבלנות?","text":"המחקר הראה שיש משמעות גם לאופן שבו הילד מתמודד בזמן ההמתנה, ולא רק למשך הזמן שהוא מצליח לחכות."},{"id":"article-paragraph-0e8cb8ab4672","heading":"מה עוזר לנו לחכות בסבלנות?","text":"וזה מתחבר מאוד לעבודה שלי עם הילדים. אני רוצה להבין לא רק אם הילד הצליח להתאפק, אלא איך הוא עשה את זה ומה עזר לו."},{"id":"article-paragraph-578cabb6ca49","heading":"מה עוזר לנו לחכות בסבלנות?","text":"אפשרות נוספת היא חלוקת הזמן לחלקים קטנים."},{"id":"article-paragraph-918e0892ff58","heading":"מה עוזר לנו לחכות בסבלנות?","text":"לילד עשוי להיות קשה לחשוב שהוא צריך לחכות עוד חצי שעה. אבל אם נחלק את הזמן לכמה שלבים, ונתמקד בכל פעם בחלק קטן, ההמתנה עשויה להרגיש אפשרית יותר."},{"id":"article-paragraph-bfab3a1d3d72","heading":"מה עוזר לנו לחכות בסבלנות?","text":"גם הבנת המטרה יכולה לעזור."},{"id":"article-paragraph-b9a53c943f2f","heading":"מה עוזר לנו לחכות בסבלנות?","text":"כשאנחנו יודעים למה אנחנו מחכים ומה אנחנו עשויים להרוויח מההמתנה, לפעמים קל יותר להתאפק."},{"id":"article-paragraph-77c4a2cd94bb","heading":"מה עוזר לנו לחכות בסבלנות?","text":"ילד שחוסך כסף כדי לקנות משהו שהוא מאוד רוצה עשוי למצוא יותר מוטיבציה לא לבזבז אותו מיד. ילד שרוצה להצליח במשימה מסוימת עשוי להיות מוכן להשקיע בה יותר זמן כשהוא מבין מה הוא מנסה להשיג."},{"id":"article-paragraph-7488e6c1fb93","heading":"מה עוזר לנו לחכות בסבלנות?","text":"אבל לא תמיד צריך רק להתאמץ יותר."},{"id":"article-paragraph-878a7ea94fde","heading":"מה עוזר לנו לחכות בסבלנות?","text":"לפעמים הדרך הטובה ביותר להתמודד עם פיתוי היא דווקא לשנות את הסביבה: להרחיק את הדבר שמסיח את דעתנו, לבחור פעילות אחרת בזמן ההמתנה או לבקש עזרה ממישהו."},{"id":"article-heading-fa4b9958aa8f","heading":"מבחן המרשמלו בתוך המפגש הטיפולי","text":"מבחן המרשמלו בתוך המפגש הטיפולי"},{"id":"article-paragraph-d4b25f6c8177","heading":"מבחן המרשמלו בתוך המפגש הטיפולי","text":"אחת הפעילויות שאני משלב לפעמים היא גרסה משחקית של מבחן המרשמלו."},{"id":"article-paragraph-26f451bf3fd0","heading":"מבחן המרשמלו בתוך המפגש הטיפולי","text":"אני יכול להציע לילד עוגייה אחת עכשיו, או שתי עוגיות אם יבחר לחכות זמן קצר בזמן שאני יוצא מהחדר או מתרחק, בהתאם לגילו ולמידת הביטחון שלו."},{"id":"article-paragraph-29eec34c521a","heading":"מבחן המרשמלו בתוך המפגש הטיפולי","text":"הילד יכול לבחור אם להמתין או לקחת את העוגייה מיד."},{"id":"article-paragraph-9780602781f1","heading":"מבחן המרשמלו בתוך המפגש הטיפולי","text":"אבל מבחינתי, השאלה המעניינת אינה רק אם הוא הצליח לחכות."},{"id":"article-paragraph-e2cee84f7d4e","heading":"מבחן המרשמלו בתוך המפגש הטיפולי","text":"אני רוצה להבין מה קרה במהלך ההמתנה."},{"id":"article-paragraph-fb34934002df","heading":"מבחן המרשמלו בתוך המפגש הטיפולי","text":"האם היה לו קשה? האם הוא חשב כל הזמן על העוגייה? האם ניסה להעסיק את עצמו במשהו אחר? האם עזר לו לדעת שבסוף יקבל שתי עוגיות?"},{"id":"article-paragraph-a9870e2c02d1","heading":"מבחן המרשמלו בתוך המפגש הטיפולי","text":"גם אם הוא בחר לא לחכות, זאת יכולה להיות הזדמנות לשיחה."},{"id":"article-paragraph-9a525b4c781c","heading":"מבחן המרשמלו בתוך המפגש הטיפולי","text":"אנחנו יכולים לחשוב יחד מה היה עוזר לו, מה הפך את ההמתנה לקשה, והאם היה רוצה לנסות דרך אחרת בפעם הבאה."},{"id":"article-paragraph-9838539802ef","heading":"מבחן המרשמלו בתוך המפגש הטיפולי","text":"המטרה היא לא לתת לילד ציון על כוח הרצון שלו, אלא להשתמש במשחק כדי להכיר טוב יותר את הדרך שבה הוא מתמודד עם רצונות והמתנה."},{"id":"article-heading-8c49edd839fb","heading":"איך מחברים את ההתנסות לחיים של הילד?","text":"איך מחברים את ההתנסות לחיים של הילד?"},{"id":"article-paragraph-5adf51f94757","heading":"איך מחברים את ההתנסות לחיים של הילד?","text":"הפעילויות עם הכלבים והמשחקים הן רק חלק מהתהליך."},{"id":"article-paragraph-f1b16115e64a","heading":"איך מחברים את ההתנסות לחיים של הילד?","text":"אחרי שהילד התנסה בהמתנה ובדחיית סיפוקים, אנחנו מנסים לחבר את הדברים למצבים שהוא פוגש ביום-יום."},{"id":"article-paragraph-b0802dfe75d6","heading":"איך מחברים את ההתנסות לחיים של הילד?","text":"למשל, ילד שמתקשה לחכות לתורו במשחק עם חברים."},{"id":"article-paragraph-759d2518a643","heading":"איך מחברים את ההתנסות לחיים של הילד?","text":"מה הוא מרגיש כשהוא צריך לחכות? מה מקשה עליו? האם יש משהו שהוא יכול לעשות בזמן ההמתנה כדי שיהיה לו קל יותר?"},{"id":"article-paragraph-67db5358b167","heading":"איך מחברים את ההתנסות לחיים של הילד?","text":"או ילד שרוצה לקבל משהו מההורים שלו מיד, ומתקשה להתמודד עם זה שאומרים לו שיצטרך לחכות."},{"id":"article-paragraph-802f91e71543","heading":"איך מחברים את ההתנסות לחיים של הילד?","text":"אנחנו יכולים לחשוב יחד מה הוא יכול לעשות במקום להתעצבן, האם יש דרך להעביר את הזמן, והאם כדאי לחלק את ההמתנה לשלבים."},{"id":"article-paragraph-76d7b9158e99","heading":"איך מחברים את ההתנסות לחיים של הילד?","text":"אפשר לדבר גם על הצלחות."},{"id":"article-paragraph-92191ad5dce9","heading":"איך מחברים את ההתנסות לחיים של הילד?","text":"מתי הצלחת לחכות למשהו שרצית מאוד? איך עשית את זה? מה עזר לך? איך הרגשת אחר כך?"},{"id":"article-paragraph-bea36e148f84","heading":"איך מחברים את ההתנסות לחיים של הילד?","text":"לפעמים דווקא הזיכרון של הצלחות קודמות עוזר לילד להבין שיש לו יכולת להתמודד, גם אם לא תמיד קל לו להשתמש בה."},{"id":"article-paragraph-a6ef540e4215","heading":"איך מחברים את ההתנסות לחיים של הילד?","text":"כשההמתנה מעוררת כעס או ויתור, היא גם מתחברת לנושא רחב יותר של התמודדות עם תסכול אצל ילדים. במאמר הזה אני מרחיב על הדרך שבה אפשר לעבוד עם ילדים על תחושת התסכול ועל הבחירה כיצד להגיב אליה."},{"id":"article-heading-222c10cf7880","heading":"איך הורים יכולים לעזור לילדים לפתח סבלנות ודחיית סיפוקים?","text":"איך הורים יכולים לעזור לילדים לפתח סבלנות ודחיית סיפוקים?"},{"id":"article-paragraph-281e60388d0b","heading":"איך הורים יכולים לעזור לילדים לפתח סבלנות ודחיית סיפוקים?","text":"אחד הדברים החשובים הוא לזכור שמדובר ביכולת שמתפתחת, ולא במשהו שאפשר פשוט לדרוש מהילד לעשות."},{"id":"article-paragraph-8233cf1f0090","heading":"איך הורים יכולים לעזור לילדים לפתח סבלנות ודחיית סיפוקים?","text":"כשאנחנו אומרים לילד \"תהיה סבלני\", אנחנו לא בהכרח נותנים לו את הכלים שיעזרו לו לחכות."},{"id":"article-paragraph-b6aaf05b2e7b","heading":"איך הורים יכולים לעזור לילדים לפתח סבלנות ודחיית סיפוקים?","text":"במקום זאת, אפשר לעזור לו בצורה מותאמת."},{"id":"article-paragraph-e405ca727c07","heading":"איך הורים יכולים לעזור לילדים לפתח סבלנות ודחיית סיפוקים?","text":"למשל, להתחיל מהמתנות קצרות שהוא מסוגל לעמוד בהן, ובהדרגה לאפשר לו להתנסות בהמתנות ארוכות יותר."},{"id":"article-paragraph-080ebf9f7272","heading":"איך הורים יכולים לעזור לילדים לפתח סבלנות ודחיית סיפוקים?","text":"אפשר להכין אותו מראש למה שעומד לקרות, להסביר כמה זמן יצטרך לחכות ולעזור לו למצוא משהו לעשות בזמן הזה."},{"id":"article-paragraph-1cfa9786b12e","heading":"איך הורים יכולים לעזור לילדים לפתח סבלנות ודחיית סיפוקים?","text":"אפשר גם לתת מקום לקושי שלו."},{"id":"article-paragraph-4a3f210d9016","heading":"איך הורים יכולים לעזור לילדים לפתח סבלנות ודחיית סיפוקים?","text":"\"אני יודע שאתה ממש רוצה את זה עכשיו. זה באמת קשה לחכות. בוא נחשוב מה יכול לעזור לך בינתיים.\""},{"id":"article-paragraph-7a728bc8e954","heading":"איך הורים יכולים לעזור לילדים לפתח סבלנות ודחיית סיפוקים?","text":"לא חייבים להיענות מיד לכל רצון, אבל גם לא צריך להפוך כל המתנה למבחן כוח רצון."},{"id":"article-paragraph-98a68b0d70bc","heading":"איך הורים יכולים לעזור לילדים לפתח סבלנות ודחיית סיפוקים?","text":"לפעמים הילד זקוק לעזרה שלנו כדי להתמודד עם הקושי."},{"id":"article-paragraph-8d6231e0a47e","heading":"איך הורים יכולים לעזור לילדים לפתח סבלנות ודחיית סיפוקים?","text":"וכדאי לשים לב גם להצלחות הקטנות: כשהוא הצליח לחכות עוד רגע, כשהתאפק למרות שהיה לו קשה, או כשהצליח להשקיע זמן ומאמץ במשהו שלא נתן לו סיפוק מיידי."},{"id":"article-paragraph-6fd042e27693","heading":"איך הורים יכולים לעזור לילדים לפתח סבלנות ודחיית סיפוקים?","text":"אלה הזדמנויות לעזור לו לזהות את הכוחות והיכולות שמתפתחים אצלו."},{"id":"article-heading-a778e20f590c","heading":"לסיכום - ללמוד לחכות, ולא רק להתאפק","text":"לסיכום - ללמוד לחכות, ולא רק להתאפק"},{"id":"article-paragraph-1238d6f3910e","heading":"לסיכום - ללמוד לחכות, ולא רק להתאפק","text":"סבלנות ודחיית סיפוקים הן יכולות חשובות שמלוות אותנו לאורך כל החיים."},{"id":"article-paragraph-b970da1b9316","heading":"לסיכום - ללמוד לחכות, ולא רק להתאפק","text":"הן מאפשרות לנו להתמיד, להשקיע, להתמודד עם קשיים ולפעול גם למען מטרות שלא נותנות לנו תוצאה מיידית."},{"id":"article-paragraph-856ab38fea7f","heading":"לסיכום - ללמוד לחכות, ולא רק להתאפק","text":"אבל היכולות האלה לא מופיעות בבת אחת. הן מתפתחות בהדרגה, בתוך קשר, בעזרת התנסות ותמיכה."},{"id":"article-paragraph-6acedeb75526","heading":"לסיכום - ללמוד לחכות, ולא רק להתאפק","text":"בטיפול רגשי בעזרת כלבים, אני אוהב להשתמש בפעילויות כמו \"להישאר\" ו\"לא לגעת\" כדי לאפשר לילדים להתנסות בהמתנה, לראות איך הכלבים מתמודדים איתה ולחשוב יחד על מה שעוזר ומה שמקשה."},{"id":"article-paragraph-de3fbc416c2e","heading":"לסיכום - ללמוד לחכות, ולא רק להתאפק","text":"משם אנחנו מנסים לקחת את הדברים למצבים האמיתיים שהילד פוגש בבית, בבית הספר ועם חברים."},{"id":"article-paragraph-baecf61fcc62","heading":"לסיכום - ללמוד לחכות, ולא רק להתאפק","text":"המטרה היא לא שהילד יצליח להתאפק תמיד, אלא שהוא יפתח בהדרגה את היכולת להתמודד עם ההמתנה, להבין מה עוזר לו ולבחור מתי כדאי לחכות גם כשמשהו אחר מושך אותו לפעול מיד."},{"id":"article-reference-205468b36b87","heading":"מקורות","text":"Development and socialization of self-regulation from infancy to adolescence (2023) סקירת־על שפורסמה ב־Developmental Review, המבוססת על 136 מאמרי סקירה ומטא־אנליזות. עוסקת בהתפתחות הוויסות העצמי מהינקות ועד גיל ההתבגרות, ובתפקידם של מבוגרים והסביבה החברתית."},{"id":"article-reference-b2b002601a21","heading":"מקורות","text":"Raghunathan et al. (2023) – What children do while they wait: The role of self-control strategies in delaying gratification מחקר שנערך בקרב 144 ילדים ובחן את ההתנהגויות והאסטרטגיות שבהן הם משתמשים בזמן המתנה לפרס."},{"id":"article-reference-07d786e1a8cf","heading":"מקורות","text":"Watts, Duncan & Quan (2018) – Revisiting the Marshmallow Test מחקר שבחן מחדש את הקשר בין דחיית סיפוקים בילדות לבין הישגים והתנהגות בגיל ההתבגרות, תוך התייחסות להשפעת הרקע המשפחתי והסביבה."},{"id":"article-reference-db1ce3e777e6","heading":"מקורות","text":"Sperber et al. (2024) – Delay of gratification and adult outcomes: The Marshmallow Test does not reliably predict adult functioning מחקר אורך שבחן 702 משתתפים עד גיל 26, ומצא שהביצועים במבחן המרשמלו בילדות אינם מנבאים באופן מהימן תפקוד והישגים בבגרות."}]},{"title":"טיפול בעזרת כלבים לילדים על הרצף האוטיסטי שאינם מדברים - תקשורת, ויסות חושי וקשר בלי מילים","url":"https://derech-hakelev.com/pages/articles/non-speaking-autistic-children-dog-therapy/","entries":[{"id":"article-title-ae3a8166b2a0","heading":"תחילת המאמר","text":"טיפול בעזרת כלבים לילדים על הרצף האוטיסטי שאינם מדברים - תקשורת, ויסות חושי וקשר בלי מילים"},{"id":"article-paragraph-dd164ca96e37","heading":"פתיחת המאמר","text":"כשאנחנו חושבים על טיפול רגשי, הרבה פעמים אנחנו חושבים על שיחה. המטפל שואל, המטופל מספר, ודרך המילים אפשר להבין מה הוא מרגיש, מה קשה לו ומה עובר עליו."},{"id":"article-paragraph-bfbcb063d818","heading":"פתיחת המאמר","text":"אבל מה קורה כשהילד לא מדבר? או כשהיכולת שלו להשתמש בשפה מילולית מוגבלת מאוד?"},{"id":"article-paragraph-1e7a9992b346","heading":"פתיחת המאמר","text":"האם אפשר לעבוד איתו על תקשורת, על קשר, על ויסות רגשי ועל מיומנויות חברתיות גם בלי לנהל שיחה?"},{"id":"article-paragraph-9c315dc3dfdc","heading":"פתיחת המאמר","text":"במסגרת העבודה שלי בכלבנות טיפולית בגנים בעדי נגב - כפר שיקומי וטיפולי לאנשים בעלי מוגבלויות, יצא לי לעבוד עם ילדים על הרצף האוטיסטי, חלקם ילדים שאינם משתמשים בדיבור או שמשתמשים במילים מעטות מאוד."},{"id":"article-paragraph-d7e905cabbd2","heading":"פתיחת המאמר","text":"העבודה עם הילדים האלה דרשה ממני להתאים את הפעילויות ואת הדרך שבה אני מתקשר איתם. פחות הסברים ושיחות ארוכות, ויותר פעילות מוחשית, חזרתיות, משחק, חוויה חושית והתבוננות בתגובות של הילד."},{"id":"article-paragraph-87c0832038f6","heading":"פתיחת המאמר","text":"אחד הדברים המשמעותיים שלמדתי מהעבודה הזאת הוא שהיעדר דיבור אינו אומר היעדר תקשורת. גם כשילד לא אומר במילים מה הוא רוצה או מרגיש, הוא עדיין יכול להביע את עצמו בדרכים רבות."},{"id":"article-paragraph-92626d308ed5","heading":"פתיחת המאמר","text":"וכאן, בעיניי, לכלבים יש משהו מיוחד להציע."},{"id":"article-heading-623387dc7703","heading":"מה מאפיין ילדים על הרצף האוטיסטי שאינם מדברים?","text":"מה מאפיין ילדים על הרצף האוטיסטי שאינם מדברים?"},{"id":"article-paragraph-aa3598041dfc","heading":"מה מאפיין ילדים על הרצף האוטיסטי שאינם מדברים?","text":"אוטיזם הוא מצב נוירו-התפתחותי שמתבטא, בין היתר, בהבדלים בתקשורת ובאינטראקציה חברתית, בדפוסי התנהגות ותחומי עניין, ולעיתים גם באופן שבו האדם חווה ומעבד מידע חושי."},{"id":"article-paragraph-a51a7702f6a3","heading":"מה מאפיין ילדים על הרצף האוטיסטי שאינם מדברים?","text":"אבל חשוב לזכור שהרצף האוטיסטי מגוון מאוד."},{"id":"article-paragraph-bbe0d775aa70","heading":"מה מאפיין ילדים על הרצף האוטיסטי שאינם מדברים?","text":"יש ילדים שמדברים באופן שוטף, ילדים שמשתמשים במילים בודדות, וילדים שכמעט אינם משתמשים בדיבור בכלל."},{"id":"article-paragraph-696179ba2759","heading":"מה מאפיין ילדים על הרצף האוטיסטי שאינם מדברים?","text":"גם בין ילדים שאינם מדברים יכולים להיות הבדלים גדולים. ילד אחד עשוי להבין הוראות מילוליות מורכבות, ואחר יזדקק להמחשה חזותית. ילד אחד יתקשר באמצעות הצבעה או מחוות, ואחר ייעזר בתמונות, בסמלים או במכשיר תקשורת."},{"id":"article-paragraph-fd8be049f06a","heading":"מה מאפיין ילדים על הרצף האוטיסטי שאינם מדברים?","text":"לכן אני מעדיף להתייחס ליכולת התקשורתית של כל ילד בנפרד, ולא להניח שאם הוא אינו מדבר, הוא גם אינו מבין."},{"id":"article-paragraph-23dac0f29534","heading":"מה מאפיין ילדים על הרצף האוטיסטי שאינם מדברים?","text":"העובדה שילד לא יכול להביע משהו במילים אינה אומרת שאין לו מחשבות, רצונות, רגשות או יכולת לבחור."},{"id":"article-paragraph-63061d4da003","heading":"מה מאפיין ילדים על הרצף האוטיסטי שאינם מדברים?","text":"המטרה שלנו היא למצוא דרכים שיאפשרו לו להביע אותם, להבין אותו וליצור איתו קשר."},{"id":"article-heading-316821574864","heading":"תקשורת לא חייבת להיות מילולית","text":"תקשורת לא חייבת להיות מילולית"},{"id":"article-paragraph-1ca75f95d1ad","heading":"תקשורת לא חייבת להיות מילולית","text":"אחד הדברים המרכזיים בעבודה עם ילדים שאינם מדברים הוא ללמוד לזהות את הדרכים האחרות שבהן הם מתקשרים."},{"id":"article-paragraph-ab6cb2d7fb2a","heading":"תקשורת לא חייבת להיות מילולית","text":"תקשורת יכולה להתבטא במבט, בהושטת יד, בהצבעה, בהבעות פנים, בתנועות גוף, בקולות או בבחירה בין אפשרויות."},{"id":"article-paragraph-d268a260bb51","heading":"תקשורת לא חייבת להיות מילולית","text":"למשל, ילד שמושיט יד לכיוון המברשת יכול לבטא רצון להמשיך לסרק את הכלב. ילד שמתרחק יכול לסמן שהפעילות לא נעימה לו או שהוא זקוק להפסקה."},{"id":"article-paragraph-1ce808ddce94","heading":"תקשורת לא חייבת להיות מילולית","text":"גם היכולת לסרב היא תקשורת חשובה."},{"id":"article-paragraph-7851c42eefca","heading":"תקשורת לא חייבת להיות מילולית","text":"בטיפול, אני לא רוצה רק שהילד יבצע את מה שאני מבקש ממנו. אני רוצה שתהיה לו אפשרות להשפיע על המפגש: לבחור פעילות, לבקש עוד, להפסיק משהו שלא נעים לו ולהביע העדפה."},{"id":"article-paragraph-80ea5907afee","heading":"תקשורת לא חייבת להיות מילולית","text":"לצד התקשורת הטבעית של הילד, אפשר לשלב גם אמצעי תקשורת תומכת וחלופית (תת\"ח), כמו כרטיסי תמונות, לוחות בחירה או מכשירי תקשורת, בהתאם למערכת שהילד משתמש בה ולהמלצות אנשי המקצוע שמלווים אותו."},{"id":"article-paragraph-0bc09d7da880","heading":"תקשורת לא חייבת להיות מילולית","text":"הכלב יכול להפוך את התקשורת הזאת למשהו מוחשי ומשמעותי עבור הילד."},{"id":"article-paragraph-ba4915d5ce72","heading":"תקשורת לא חייבת להיות מילולית","text":"במקום לבקש ממנו להצביע על תמונה רק לצורך תרגול, אנחנו יכולים להציג לו שתי אפשרויות: להבריש את הכלב או לתת לו חטיף. הבחירה שלו משפיעה מיד על מה שקורה במפגש."},{"id":"article-paragraph-d610d4d4df9a","heading":"תקשורת לא חייבת להיות מילולית","text":"וכשהבחירה משנה משהו אמיתי, יש לה משמעות."},{"id":"article-heading-650cb52ee7ae","heading":"מה הקשר בין אוטיזם לוויסות חושי?","text":"מה הקשר בין אוטיזם לוויסות חושי?"},{"id":"article-paragraph-f8ff52587b72","heading":"מה הקשר בין אוטיזם לוויסות חושי?","text":"אצל ילדים אוטיסטים רבים קיימים הבדלים בעיבוד החושי."},{"id":"article-paragraph-4bb516aa4d5e","heading":"מה הקשר בין אוטיזם לוויסות חושי?","text":"הכוונה היא לאופן שבו המוח קולט ומעבד מידע שמגיע מהחושים: מגע, שמיעה, ראייה, ריח, תנועה, שיווי משקל ותחושת הגוף."},{"id":"article-paragraph-706cc18982bf","heading":"מה הקשר בין אוטיזם לוויסות חושי?","text":"יש ילדים שרגישים מאוד לגירויים מסוימים. למשל, רעש חזק, מגע בלתי צפוי או ריח מסוים יכולים להיות מציפים או לא נעימים עבורם."},{"id":"article-paragraph-ed6bcfa12ddd","heading":"מה הקשר בין אוטיזם לוויסות חושי?","text":"מנגד, יש ילדים שמחפשים גירויים חושיים. הם עשויים ליהנות מתנועה, ממגע במרקמים מסוימים או מפעילויות שמספקות להם תחושה גופנית ברורה."},{"id":"article-paragraph-77a673d3bbbb","heading":"מה הקשר בין אוטיזם לוויסות חושי?","text":"אותו ילד יכול להיות רגיש מאוד לרעש, ובמקביל ליהנות ממגע מסוים. גם התגובה שלו לגירוי יכולה להשתנות מיום ליום."},{"id":"article-paragraph-94d0b8b47b7f","heading":"מה הקשר בין אוטיזם לוויסות חושי?","text":"חשוב לי להדגיש שלא כל ילד אוטיסט חווה את אותם קשיים חושיים, וגם לא כל ילד שאינו מדבר בהכרח מתמודד עם קושי בוויסות חושי."},{"id":"article-paragraph-7cce163c99e7","heading":"מה הקשר בין אוטיזם לוויסות חושי?","text":"בטיפול, אנחנו צריכים להבין מה נעים לילד, מה מציף אותו, מאילו גירויים הוא נמנע ואילו חוויות הוא מחפש."},{"id":"article-heading-17269f784185","heading":"איך כלבים יכולים להשתלב בעבודה על ויסות חושי?","text":"איך כלבים יכולים להשתלב בעבודה על ויסות חושי?"},{"id":"article-paragraph-e087692e5876","heading":"איך כלבים יכולים להשתלב בעבודה על ויסות חושי?","text":"אחד היתרונות של עבודה עם כלבים הוא מגוון ההתנסויות החושיות שהם מאפשרים."},{"id":"article-paragraph-a198805dbd88","heading":"איך כלבים יכולים להשתלב בעבודה על ויסות חושי?","text":"אפשר להרגיש את הפרווה, להתבונן בתנועות של הכלב, לשמוע את הצעדים שלו, להבריש אותו, להכין לו אוכל או להשתתף במשחקי הרחה וחיפוש."},{"id":"article-paragraph-52f0cab906a5","heading":"איך כלבים יכולים להשתלב בעבודה על ויסות חושי?","text":"לכל אחת מהפעילויות האלה יש מאפיינים חושיים שונים."},{"id":"article-paragraph-ab2a7c290428","heading":"איך כלבים יכולים להשתלב בעבודה על ויסות חושי?","text":"בגנים שבהם עבדתי בעדי נגב השתמשתי לא מעט בפעילויות כמו הברשה, האכלה וטיפול בכלב. אלו פעילויות שלא דורשות שיחה ארוכה, אבל מאפשרות לילד להיות פעיל, לבחור, להתנסות וליצור קשר."},{"id":"article-heading-8b759fa5b4be","heading":"הברשה ומגע בפרווה","text":"הברשה ומגע בפרווה"},{"id":"article-paragraph-24354a614d54","heading":"איך כלבים יכולים להשתלב בעבודה על ויסות חושי?","text":"אחת הפעילויות הפשוטות היא הברשת הכלב."},{"id":"article-paragraph-53bda918cc45","heading":"איך כלבים יכולים להשתלב בעבודה על ויסות חושי?","text":"הילד יכול לבחור מברשת, להתבונן בי מדגים, ולאחר מכן לנסות בעצמו."},{"id":"article-paragraph-44478e28166c","heading":"איך כלבים יכולים להשתלב בעבודה על ויסות חושי?","text":"בפעילות הזאת אפשר לעבוד על היכרות עם מרקמים, תיאום תנועות, תכנון פעולה, קשב והשתתפות משותפת."},{"id":"article-paragraph-7190693c651d","heading":"איך כלבים יכולים להשתלב בעבודה על ויסות חושי?","text":"אפשר גם להשתמש במברשות שונות, כך שהילד יוכל להרגיש את ההבדל ביניהן ולבחור במה נעים לו להשתמש."},{"id":"article-paragraph-3cbe64c4afbe","heading":"איך כלבים יכולים להשתלב בעבודה על ויסות חושי?","text":"כמובן, יש ילדים שלא ירצו לגעת בפרווה או במברשת, וזה בסדר גמור. אפשר להשתתף גם דרך התבוננות, בחירת המברשת או הגשת הציוד."},{"id":"article-paragraph-f54131fab6c2","heading":"איך כלבים יכולים להשתלב בעבודה על ויסות חושי?","text":"המטרה אינה לחייב ילד להיחשף למגע שלא נעים לו, אלא לאפשר לו לחקור ולהתנסות בקצב שמתאים לו."},{"id":"article-heading-eff254704f0f","heading":"האכלה ופעילות מובנית","text":"האכלה ופעילות מובנית"},{"id":"article-paragraph-83bf7bf2af8f","heading":"איך כלבים יכולים להשתלב בעבודה על ויסות חושי?","text":"פעילות נוספת שהשתמשתי בה הרבה היא האכלת הכלבים."},{"id":"article-paragraph-57a8bd8c5fd1","heading":"איך כלבים יכולים להשתלב בעבודה על ויסות חושי?","text":"אפשר להכין מראש מספר חטיפים, לבקש מהילד לבחור אחד ולהגיש אותו לכלב בצורה בטוחה."},{"id":"article-paragraph-3c07663fbe05","heading":"איך כלבים יכולים להשתלב בעבודה על ויסות חושי?","text":"זאת יכולה להיות פעילות קצרה, ברורה וחזרתית מאוד."},{"id":"article-paragraph-6cad68a8d2b8","heading":"איך כלבים יכולים להשתלב בעבודה על ויסות חושי?","text":"הילד בוחר חטיף, נותן אותו לכלב ורואה תגובה מיידית."},{"id":"article-paragraph-0c16220d690c","heading":"איך כלבים יכולים להשתלב בעבודה על ויסות חושי?","text":"דרך הפעילות הזאת אפשר לתרגל בחירה, יוזמה, רצף פעולות, המתנה ותקשורת."},{"id":"article-paragraph-e9cff7ebc6a1","heading":"איך כלבים יכולים להשתלב בעבודה על ויסות חושי?","text":"עבור חלק מהילדים, החזרתיות הזאת חשובה במיוחד. כשהם יודעים מה עומד לקרות, הפעילות נעשית צפויה יותר, והם יכולים להרגיש בטוחים ולהשתתף בה."},{"id":"article-heading-ff1dd5d210af","heading":"פקודות פשוטות וחזרתיות - כשיש משמעות ברורה לכל פעולה","text":"פקודות פשוטות וחזרתיות - כשיש משמעות ברורה לכל פעולה"},{"id":"article-paragraph-851708eb35a0","heading":"פקודות פשוטות וחזרתיות - כשיש משמעות ברורה לכל פעולה","text":"אחת הדרכים המרכזיות שבהן עבדתי עם הילדים הייתה באמצעות פקודות פשוטות ומוכרות לכלבים."},{"id":"article-paragraph-d483061b4038","heading":"פקודות פשוטות וחזרתיות - כשיש משמעות ברורה לכל פעולה","text":"למשל, \"שב\", \"ארצה\", \"אליי\" ו\"תן יד\"."},{"id":"article-paragraph-b6338e4be0e8","heading":"פקודות פשוטות וחזרתיות - כשיש משמעות ברורה לכל פעולה","text":"היתרון בפעילויות האלה הוא שיש להן מבנה ברור: הילד מסמן או מבקש משהו מהכלב, הכלב מבצע פעולה, והילד יכול לראות מה קרה."},{"id":"article-paragraph-4a265bc0a08c","heading":"פקודות פשוטות וחזרתיות - כשיש משמעות ברורה לכל פעולה","text":"לא חייבים לומר את הפקודה בקול. אפשר להשתמש במחווה, בסימן מוסכם או בכרטיס חזותי, בהתאם ליכולת ולדרך התקשורת של הילד."},{"id":"article-paragraph-2ce63a40f9d8","heading":"פקודות פשוטות וחזרתיות - כשיש משמעות ברורה לכל פעולה","text":"לפעמים ביצענו את אותה הפעילות שוב ושוב."},{"id":"article-paragraph-d37746413217","heading":"פקודות פשוטות וחזרתיות - כשיש משמעות ברורה לכל פעולה","text":"מבחוץ זה אולי נראה כמו חזרה על אותו תרגיל, אבל מבחינה טיפולית אפשר לעבוד כך על הרבה דברים: יוזמה, קשב משותף, תכנון פעולה, המתנה, תחושת מסוגלות ויצירת קשר."},{"id":"article-paragraph-a44371551f73","heading":"פקודות פשוטות וחזרתיות - כשיש משמעות ברורה לכל פעולה","text":"אחד היתרונות של החזרתיות הוא שהילד יכול ללמוד מה צפוי לקרות. וכשהפעילות כבר מוכרת לו, לפעמים קל יותר להכניס שינוי קטן או לאפשר לו לקחת יותר יוזמה."},{"id":"article-heading-886e0df44cf0","heading":"התאמת משחקים לילדים שאינם משתמשים בדיבור","text":"התאמת משחקים לילדים שאינם משתמשים בדיבור"},{"id":"article-paragraph-10f835a299b0","heading":"התאמת משחקים לילדים שאינם משתמשים בדיבור","text":"העבודה עם הילדים בעדי נגב גרמה לי גם להתאים משחקים שאני משתמש בהם בדרך כלל בטיפול."},{"id":"article-paragraph-05b6dc8c8e2b","heading":"התאמת משחקים לילדים שאינם משתמשים בדיבור","text":"במקום להסתמך על הסברים ארוכים או על שיח מילולי, ניסיתי להפוך את המשחקים לחזותיים, פשוטים ומוחשיים יותר."},{"id":"article-heading-61830262f159","heading":"משחק דאבל עם קלפים גדולים","text":"משחק דאבל עם קלפים גדולים"},{"id":"article-paragraph-74c176e84039","heading":"התאמת משחקים לילדים שאינם משתמשים בדיבור","text":"אחד המשחקים שהשתמשתי בהם הוא משחק הדאבל הכלבי שלי, שאותו הדפסתי במיוחד בקלפים גדולים."},{"id":"article-paragraph-23cd3db80410","heading":"התאמת משחקים לילדים שאינם משתמשים בדיבור","text":"הגודל אפשר להציג לילדים את התמונות בצורה ברורה יותר ולעבוד איתם על זיהוי והתאמה בין סמלים."},{"id":"article-paragraph-ec0ddd6fe1e4","heading":"התאמת משחקים לילדים שאינם משתמשים בדיבור","text":"במקום לשחק לפי כל הכללים של משחק הדאבל הרגיל, אפשר לפשט את הפעילות."},{"id":"article-paragraph-ad3cd8fde3a1","heading":"התאמת משחקים לילדים שאינם משתמשים בדיבור","text":"למשל, להציג שני קלפים ולבקש מהילד למצוא את התמונה המשותפת."},{"id":"article-paragraph-33a9e44eccbf","heading":"התאמת משחקים לילדים שאינם משתמשים בדיבור","text":"אפשר להצביע על התמונה, לגעת בה או להשתמש באמצעי תקשורת אחר."},{"id":"article-paragraph-1e60830ee9f0","heading":"התאמת משחקים לילדים שאינם משתמשים בדיבור","text":"המשחק מאפשר לעבוד על קשב חזותי, הבחנה בין פרטים, בחירה והשתתפות משותפת, בלי צורך להשתמש בדיבור."},{"id":"article-heading-cef88a1247af","heading":"משחק \"לכל בעיה - פתרון\"","text":"משחק \"לכל בעיה - פתרון\""},{"id":"article-paragraph-6e59176f8b54","heading":"התאמת משחקים לילדים שאינם משתמשים בדיבור","text":"משחק נוסף שהתאמתי הוא \"לכל בעיה - פתרון\"."},{"id":"article-paragraph-714ea43aeff4","heading":"התאמת משחקים לילדים שאינם משתמשים בדיבור","text":"במשחק הזה אפשר להציג לילד בעיה ולצידה שלושה פתרונות אפשריים."},{"id":"article-paragraph-86ef9d473e9b","heading":"התאמת משחקים לילדים שאינם משתמשים בדיבור","text":"במקום לבקש ממנו להסביר במילים איך היה פותר את הבעיה, אפשר לבקש ממנו לבחור את הפתרון שמתאים בעיניו."},{"id":"article-paragraph-088a07caaae8","heading":"התאמת משחקים לילדים שאינם משתמשים בדיבור","text":"כך אפשר לעבוד על הבנת מצבים, בחירה, קשר בין בעיה לפתרון וחשיבה על אפשרויות שונות."},{"id":"article-paragraph-91051ae483b6","heading":"התאמת משחקים לילדים שאינם משתמשים בדיבור","text":"חשוב כמובן לבחור בעיות שהילד יכול להבין ולהציג אותן בצורה חזותית וברורה. לפעמים גם שתי אפשרויות יספיקו."},{"id":"article-paragraph-57b7379fb709","heading":"התאמת משחקים לילדים שאינם משתמשים בדיבור","text":"המטרה היא לא רק למצוא את התשובה שהמטפל חושב שהיא נכונה, אלא לאפשר לילד להשתתף, לבחור ולהראות כיצד הוא מבין את הסיטואציה."},{"id":"article-heading-6c82780f9ddb","heading":"קלפי רגשות ושפת גוף – להבין ולהביע רגשות בלי מילים","text":"קלפי רגשות ושפת גוף – להבין ולהביע רגשות בלי מילים"},{"id":"article-paragraph-2108295e0b41","heading":"התאמת משחקים לילדים שאינם משתמשים בדיבור","text":"פעילות נוספת שהשתמשתי בה הייתה עם קלפים שמציגים רגשות דרך שפת הגוף של כלבים."},{"id":"article-paragraph-6db6e502a3cb","heading":"התאמת משחקים לילדים שאינם משתמשים בדיבור","text":"בכל קלף מופיע כלב שמציג סימנים שיכולים להעיד על רגש או מצב מסוים, כמו פחד, כעס, שמחה או עצב."},{"id":"article-paragraph-726f7684c36c","heading":"התאמת משחקים לילדים שאינם משתמשים בדיבור","text":"בהתחלה התבוננו יחד בקלף וניסינו לזהות מה הכלב אולי מרגיש לפי שפת הגוף שלו."},{"id":"article-paragraph-c48da5c9fef6","heading":"התאמת משחקים לילדים שאינם משתמשים בדיבור","text":"אחר כך ביקשתי מהילדים להראות איך הם עצמם נראים כשהם מרגישים את אותו הרגש."},{"id":"article-paragraph-72afaa92e5e7","heading":"התאמת משחקים לילדים שאינם משתמשים בדיבור","text":"למשל, כשהצגתי רגש של עצב, כולנו עשינו את עצמנו בוכים. כשהצגתי כעס, כולנו עשינו פרצופים כועסים."},{"id":"article-paragraph-c27cfdcb2325","heading":"התאמת משחקים לילדים שאינם משתמשים בדיבור","text":"אחת החוויות הזכורות לי מהפעילות הזאת היא כמה הילדים צחקו ונהנו ממנה. דווקא החיקוי המשותף של בכי או כעס הפך למשחק מצחיק שכולם יכלו להשתתף בו, גם בלי לדבר."},{"id":"article-paragraph-65106d211f68","heading":"התאמת משחקים לילדים שאינם משתמשים בדיבור","text":"דרך הפעילות אפשר לעבוד על זיהוי רגשות, הבעות פנים, שפת גוף, חיקוי והשתתפות חברתית."},{"id":"article-paragraph-dc1d13139b41","heading":"התאמת משחקים לילדים שאינם משתמשים בדיבור","text":"אבל מבחינתי היה כאן עוד משהו חשוב: נוצרה חוויה משותפת של משחק והנאה. לא היינו צריכים לנהל שיחה על רגשות כדי לעסוק בהם. יכולנו להתבונן, לחקות, לצחוק ולהשתתף יחד."},{"id":"article-paragraph-b1b84a7c73c7","heading":"התאמת משחקים לילדים שאינם משתמשים בדיבור","text":"וכמובן, לא כל ילד מביע רגשות באותה הדרך, ולא תמיד אפשר לדעת מה כלב מרגיש רק מתמונה אחת. הפעילות משמשת הזדמנות להתבונן בהבעות ובשפת גוף, ולא מבחן שבו חייבים לזהות רגש בצורה מסוימת."},{"id":"article-heading-2c3528a22ece","heading":"עבודה עם החושים דרך פעילויות עם הכלב","text":"עבודה עם החושים דרך פעילויות עם הכלב"},{"id":"article-paragraph-ee5d9ee7209c","heading":"עבודה עם החושים דרך פעילויות עם הכלב","text":"בנוסף למשחקים ולפקודות, שילבתי פעילויות שהתמקדו בחושים שונים."},{"id":"article-heading-eb171b4d7b62","heading":"חוש הריח - משחקי חיפוש","text":"חוש הריח - משחקי חיפוש"},{"id":"article-paragraph-5c038e96a70d","heading":"עבודה עם החושים דרך פעילויות עם הכלב","text":"אפשר להחביא חטיפים או חפצים שהכלב מכיר, ולאפשר לו לחפש אותם באמצעות חוש הריח."},{"id":"article-paragraph-7a09eb0f9d70","heading":"עבודה עם החושים דרך פעילויות עם הכלב","text":"הילד יכול להשתתף בהחבאה, לבחור את המקום או לעזור להכין את הפעילות."},{"id":"article-paragraph-453f725ce66d","heading":"עבודה עם החושים דרך פעילויות עם הכלב","text":"כך נוצרת פעילות משותפת עם התחלה, אמצע וסוף."},{"id":"article-paragraph-900358b3e4e1","heading":"עבודה עם החושים דרך פעילויות עם הכלב","text":"אפשר גם לעבוד על המתנה, התבוננות, ציפייה, בחירה והנאה מההצלחה של הכלב."},{"id":"article-heading-7b2746b5fdd6","heading":"חוש המישוש - מגע, מים ומרקמים","text":"חוש המישוש - מגע, מים ומרקמים"},{"id":"article-paragraph-b5ae38d3a27b","heading":"עבודה עם החושים דרך פעילויות עם הכלב","text":"אפשר לשלב פעילויות כמו הברשה, משחק עם אביזרים שונים או רחצה של הכלב כשהתנאים מתאימים לכך."},{"id":"article-paragraph-1318c452152d","heading":"עבודה עם החושים דרך פעילויות עם הכלב","text":"למשל, פעילות של אמבטיה לכלב מאפשרת לילד לפגוש מים, ספוג, מגבת ומרקמים שונים."},{"id":"article-paragraph-e48f14537e9e","heading":"עבודה עם החושים דרך פעילויות עם הכלב","text":"אפשר לחלק את הפעילות לשלבים ברורים: להרטיב בעדינות, לנקות, לשטוף ולנגב."},{"id":"article-paragraph-ca0a6138e420","heading":"עבודה עם החושים דרך פעילויות עם הכלב","text":"גם כאן, לא כל ילד חייב להשתתף בכל שלב. ילד אחד אולי ירצה לגעת במים, ואחר יעדיף להחזיק את המגבת או רק להתבונן."},{"id":"article-paragraph-8e6b7f62fcaa","heading":"עבודה עם החושים דרך פעילויות עם הכלב","text":"צריך כמובן להקפיד שגם הכלב מכיר את הפעילות, מרגיש איתה בנוח ואינו נחשף לרחצה מיותרת או למגע שמכביד עליו."},{"id":"article-heading-a64ed8c49063","heading":"חוש הראייה - זיהוי, התאמה ומעקב","text":"חוש הראייה - זיהוי, התאמה ומעקב"},{"id":"article-paragraph-c041a0f44b7f","heading":"עבודה עם החושים דרך פעילויות עם הכלב","text":"אפשר להשתמש בתמונות של הכלבים, בכרטיסים, בצבעים ובחפצים שונים."},{"id":"article-paragraph-fc9e394aa6b5","heading":"עבודה עם החושים דרך פעילויות עם הכלב","text":"למשל, לבקש מהילד לבחור בין שתי תמונות של פעילויות, להתאים בין תמונה לחפץ אמיתי או לזהות את האביזר שבו נשתמש עכשיו."},{"id":"article-paragraph-ff0ac4ee5e06","heading":"עבודה עם החושים דרך פעילויות עם הכלב","text":"הפעילויות האלה מאפשרות לעבוד על הבנה, בחירה, תשומת לב לפרטים והשתתפות."},{"id":"article-heading-917bfae68762","heading":"משחקי זריקה והחזרה - תנועה, תקשורת והנאה משותפת","text":"משחקי זריקה והחזרה - תנועה, תקשורת והנאה משותפת"},{"id":"article-paragraph-e3a4058259a5","heading":"עבודה עם החושים דרך פעילויות עם הכלב","text":"פעילות נוספת שהילדים מאוד נהנו ממנה הייתה משחקי זריקה והחזרה עם הכלבים."},{"id":"article-paragraph-337058ab72f3","heading":"עבודה עם החושים דרך פעילויות עם הכלב","text":"הילד זורק לכלב כדור או צעצוע מתאים, הכלב רץ להביא אותו וחוזר איתו, ואז אפשר להתחיל שוב."},{"id":"article-paragraph-50a967cd9d38","heading":"עבודה עם החושים דרך פעילויות עם הכלב","text":"זאת פעילות פשוטה יחסית, אבל יש בה הרבה מאוד אפשרויות לעבודה."},{"id":"article-paragraph-856c99230a74","heading":"עבודה עם החושים דרך פעילויות עם הכלב","text":"הילד יוזם פעולה, רואה את התגובה של הכלב ומקבל הזדמנות לחזור עליה שוב ושוב. אפשר לתרגל המתנה עד שהכלב חוזר, תיאום תנועה, קשב, מעקב חזותי ותקשורת."},{"id":"article-paragraph-daabed91be94","heading":"עבודה עם החושים דרך פעילויות עם הכלב","text":"אפשר גם לעצור לרגע ולתת לילד הזדמנות לבקש שהמשחק יימשך. הוא יכול לעשות זאת באמצעות מחווה, הצבעה, כרטיס תקשורת או כל דרך אחרת שמתאימה לו."},{"id":"article-paragraph-2e232ed06e31","heading":"עבודה עם החושים דרך פעילויות עם הכלב","text":"בפעילות הזאת בלטה במיוחד ההנאה של הילדים. הם אהבו לזרוק לכלבים, לראות אותם רצים ומחזירים את הצעצוע, ולחזור על הפעולה שוב ושוב."},{"id":"article-paragraph-722cc5b1c283","heading":"עבודה עם החושים דרך פעילויות עם הכלב","text":"לפעמים דווקא הפעילויות הפשוטות והחזרתיות ביותר הן אלו שמצליחות לעורר הכי הרבה עניין, יוזמה והשתתפות."},{"id":"article-heading-a430fbbdb1e1","heading":"לא רק קשר עם הכלב - גם תקשורת ושיתוף פעולה בין הילדים","text":"לא רק קשר עם הכלב - גם תקשורת ושיתוף פעולה בין הילדים"},{"id":"article-paragraph-64fd0cef69b6","heading":"לא רק קשר עם הכלב - גם תקשורת ושיתוף פעולה בין הילדים","text":"אחת המטרות שהיו לי לאורך המפגשים הייתה לעודד תקשורת בין הילדים עצמם."},{"id":"article-paragraph-cda7ee4d4cae","heading":"לא רק קשר עם הכלב - גם תקשורת ושיתוף פעולה בין הילדים","text":"כשעובדים עם קבוצת ילדים שאינם משתמשים בדיבור, לפעמים קל להתרכז בקשר שבין המטפל לכל ילד, או בקשר שבין הילד לכלב. אבל רציתי שהמפגשים יאפשרו גם לילדים לפנות זה לזה, לשתף פעולה ולחוות משהו יחד."},{"id":"article-paragraph-34d149fe68d5","heading":"לא רק קשר עם הכלב - גם תקשורת ושיתוף פעולה בין הילדים","text":"לכן ניסיתי לשלב את התקשורת ביניהם גם בפעילויות הפשוטות ביותר."},{"id":"article-paragraph-34cbbf279c00","heading":"לא רק קשר עם הכלב - גם תקשורת ושיתוף פעולה בין הילדים","text":"למשל, כשילד סיים את התור שלו במשחק, במקום לבקש ממנו להחזיר אליי את הקלפים או את האביזר, ביקשתי ממנו להעביר אותם לילד הבא."},{"id":"article-paragraph-75f4724b1d1a","heading":"לא רק קשר עם הכלב - גם תקשורת ושיתוף פעולה בין הילדים","text":"זאת פעולה קטנה מאוד, אבל יש בה הזדמנות לאינטראקציה חברתית."},{"id":"article-paragraph-ce7a047c7d5d","heading":"לא רק קשר עם הכלב - גם תקשורת ושיתוף פעולה בין הילדים","text":"הילד צריך לשים לב למישהו אחר, לפנות אליו ולהעביר לו חפץ. הילד השני מקבל אותו, וכך נוצרת ביניהם אינטראקציה שלא חייבת לכלול אפילו מילה אחת."},{"id":"article-paragraph-6a5968ebe558","heading":"לא רק קשר עם הכלב - גם תקשורת ושיתוף פעולה בין הילדים","text":"אפשר לעשות את זה באמצעות הושטת יד, מבט, מחווה או כל דרך תקשורת אחרת שמתאימה לילדים."},{"id":"article-heading-938d2a6013a3","heading":"משימות שאפשר להצליח בהן רק ביחד","text":"משימות שאפשר להצליח בהן רק ביחד"},{"id":"article-paragraph-90ac5ef8b779","heading":"לא רק קשר עם הכלב - גם תקשורת ושיתוף פעולה בין הילדים","text":"בפעילויות אחרות ניסיתי ליצור מצבים שבהם הילדים צריכים לשתף פעולה כדי להשיג מטרה משותפת."},{"id":"article-paragraph-746cf768666c","heading":"לא רק קשר עם הכלב - גם תקשורת ושיתוף פעולה בין הילדים","text":"למשל, שני ילדים מחזיקים חישוק, וילד שלישי צריך להוביל את הכלב כך שיעבור דרכו."},{"id":"article-paragraph-4cfcb8e5ee85","heading":"לא רק קשר עם הכלב - גם תקשורת ושיתוף פעולה בין הילדים","text":"כדי שהפעילות תצליח, הילדים צריכים לפעול יחד. שניים מחזיקים את החישוק במקום, והשלישי מסמן לכלב לעבור."},{"id":"article-paragraph-81ba43227357","heading":"לא רק קשר עם הכלב - גם תקשורת ושיתוף פעולה בין הילדים","text":"אפשר גם להחליף ביניהם תפקידים, כך שכל ילד מקבל הזדמנות להשתתף בדרך אחרת."},{"id":"article-paragraph-08e32ceb10f7","heading":"לא רק קשר עם הכלב - גם תקשורת ושיתוף פעולה בין הילדים","text":"בפעילות נוספת הילדים יכולים להחזיק יחד מקל או אביזר אחר שמשמש כחלק ממשימה עם הכלב."},{"id":"article-paragraph-ce960b0732ac","heading":"לא רק קשר עם הכלב - גם תקשורת ושיתוף פעולה בין הילדים","text":"אלו פעילויות שמאפשרות לעבוד על תיאום, תשומת לב לאחר, המתנה, חלוקת תפקידים ושיתוף פעולה."},{"id":"article-paragraph-fe9feae5eeb2","heading":"לא רק קשר עם הכלב - גם תקשורת ושיתוף פעולה בין הילדים","text":"הילדים לא חייבים לשוחח ביניהם כדי להצליח במשימה. הם יכולים להתבונן זה בזה, להתאים את הפעולות שלהם ולגלות שיש משהו שהם מצליחים לעשות ביחד."},{"id":"article-heading-5bdcb72c4e6d","heading":"מה הופך את הפעילות הזאת למשמעותית?","text":"מה הופך את הפעילות הזאת למשמעותית?"},{"id":"article-paragraph-509f042579de","heading":"לא רק קשר עם הכלב - גם תקשורת ושיתוף פעולה בין הילדים","text":"מבחינתי, אחד היתרונות של השימוש בכלבים הוא שהם מאפשרים ליצור מטרה משותפת שהילדים רוצים להשתתף בה."},{"id":"article-paragraph-0c9781b4f070","heading":"לא רק קשר עם הכלב - גם תקשורת ושיתוף פעולה בין הילדים","text":"הם לא מתבקשים ליצור קשר רק כי המבוגר ביקש מהם לתקשר. יש פעילות מעניינת שהם רוצים לבצע, וכדי שהיא תצליח יש מקום גם לשיתוף פעולה עם ילד אחר."},{"id":"article-paragraph-7357dbac81fb","heading":"לא רק קשר עם הכלב - גם תקשורת ושיתוף פעולה בין הילדים","text":"וזה הבדל משמעותי בעיניי."},{"id":"article-paragraph-09fb1d13cda2","heading":"לא רק קשר עם הכלב - גם תקשורת ושיתוף פעולה בין הילדים","text":"התקשורת אינה רק המטרה של הפעילות, אלא גם הדרך שבה מצליחים לבצע אותה."},{"id":"article-paragraph-ea0a5241e13f","heading":"לא רק קשר עם הכלב - גם תקשורת ושיתוף פעולה בין הילדים","text":"כשילד מעביר חפץ לחבר, כשהם מחזיקים יחד חישוק או כשהם משתפים פעולה כדי שהכלב יבצע משימה, נוצרות הזדמנויות לקשר חברתי בתוך התנסות אמיתית."},{"id":"article-paragraph-b2ebd94f25a0","heading":"לא רק קשר עם הכלב - גם תקשורת ושיתוף פעולה בין הילדים","text":"גם כאן חשוב להתאים את הדרישה לילדים ולאפשר השתתפות בדרכים שונות. יש ילדים שירצו להשתתף ישירות, ואחרים יעדיפו בהתחלה להתבונן או לבצע רק חלק מהמשימה."},{"id":"article-paragraph-a13dbfae86a9","heading":"לא רק קשר עם הכלב - גם תקשורת ושיתוף פעולה בין הילדים","text":"המטרה אינה לכפות אינטראקציה, אלא ליצור הזדמנויות שבהן קשר ושיתוף פעולה יכולים להתפתח בצורה טבעית ונעימה."},{"id":"article-heading-3d81080f5147","heading":"למה הכלב יכול להיות משמעותי דווקא לילדים שאינם מדברים?","text":"למה הכלב יכול להיות משמעותי דווקא לילדים שאינם מדברים?"},{"id":"article-paragraph-61ea11f24be1","heading":"למה הכלב יכול להיות משמעותי דווקא לילדים שאינם מדברים?","text":"אחד הדברים המיוחדים בכלבים הוא שהתקשורת איתם אינה מתבססת רק על מילים."},{"id":"article-paragraph-81a06a38fc70","heading":"למה הכלב יכול להיות משמעותי דווקא לילדים שאינם מדברים?","text":"כלבים מגיבים גם למחוות, לתנועות גוף, למיקום במרחב ולסימנים שנלמדו."},{"id":"article-paragraph-2bab5f092c7a","heading":"למה הכלב יכול להיות משמעותי דווקא לילדים שאינם מדברים?","text":"במובן הזה, אפשר ליצור איתם אינטראקציה משמעותית גם בלי לנהל שיחה."},{"id":"article-paragraph-d89ea2fd56d2","heading":"למה הכלב יכול להיות משמעותי דווקא לילדים שאינם מדברים?","text":"הכלב יכול לתת לילד סיבה להשתתף, לפעול ולהביע רצון."},{"id":"article-paragraph-40e97e99d4f5","heading":"למה הכלב יכול להיות משמעותי דווקא לילדים שאינם מדברים?","text":"למשל, אם הילד רוצה שהכלב יתקרב אליו, אפשר לעזור לו למצוא דרך לסמן זאת. אם הוא רוצה להמשיך להבריש, הוא יכול לבקש \"עוד\". ואם הוא רוצה להפסיק, אנחנו צריכים לאפשר לו להביע גם את זה."},{"id":"article-paragraph-891a8265112a","heading":"למה הכלב יכול להיות משמעותי דווקא לילדים שאינם מדברים?","text":"בנוסף, כפי שתיארתי, הכלב יכול לשמש גם מוקד לפעילות משותפת בין הילדים, ולעודד אינטראקציות חברתיות שלא דורשות בהכרח שיחה מילולית."},{"id":"article-paragraph-e2a8b24a2f15","heading":"למה הכלב יכול להיות משמעותי דווקא לילדים שאינם מדברים?","text":"אנחנו לא עובדים רק על ביצוע משימות, אלא על האפשרות של הילד להיות שותף פעיל במפגש."},{"id":"article-heading-b938afa9f2a0","heading":"מה אומרים המחקרים על טיפול בעזרת כלבים בילדים אוטיסטים?","text":"מה אומרים המחקרים על טיפול בעזרת כלבים בילדים אוטיסטים?"},{"id":"article-paragraph-56609b4e8046","heading":"מה אומרים המחקרים על טיפול בעזרת כלבים בילדים אוטיסטים?","text":"בשנים האחרונות נערכו מחקרים שבחנו את ההשפעה של התערבויות בעזרת כלבים בקרב ילדים על הרצף האוטיסטי."},{"id":"article-paragraph-22b110a492c8","heading":"מה אומרים המחקרים על טיפול בעזרת כלבים בילדים אוטיסטים?","text":"סקירה שיטתית שפורסמה בשנת 2024 וכללה 19 מאמרים מצאה שבמרבית המחקרים דווח על השפעה חיובית בתחום התקשורת והאינטראקציה החברתית."},{"id":"article-paragraph-abf7d6edc69d","heading":"מה אומרים המחקרים על טיפול בעזרת כלבים בילדים אוטיסטים?","text":"החוקרים תיארו את הכלב כגורם שיכול לעודד מעורבות וליצור הזדמנויות לתקשורת משותפת."},{"id":"article-paragraph-90f458ab9c0d","heading":"מה אומרים המחקרים על טיפול בעזרת כלבים בילדים אוטיסטים?","text":"מחקר ישראלי נוסף שפורסם בשנת 2024 בחן 37 ילדים אוטיסטים בגיל הגן שהשתתפו בהתערבות מובנית של עבודה עם כלבים."},{"id":"article-paragraph-18462a8236c0","heading":"מה אומרים המחקרים על טיפול בעזרת כלבים בילדים אוטיסטים?","text":"לאורך ההתערבות נמצאו שינויים חיוביים בהתנהגויות תקשורתיות, ובהן יוזמות לא־מילוליות, מחוות וקשב משותף."},{"id":"article-paragraph-872558db2bea","heading":"מה אומרים המחקרים על טיפול בעזרת כלבים בילדים אוטיסטים?","text":"מחקר נוסף, שהתבסס על סקירה ומטא-אנליזה של 45 מחקרים שכללו 1,212 משתתפים, מצא שיפורים במדדים מסוימים של תקשורת חברתית והתנהגות בעקבות התערבויות בעזרת בעלי חיים."},{"id":"article-paragraph-c595284199a4","heading":"מה אומרים המחקרים על טיפול בעזרת כלבים בילדים אוטיסטים?","text":"הממצאים האלה מתחברים לאפשרות להשתמש בכלב כדי ליצור הזדמנויות לתקשורת ולפעילות משותפת."},{"id":"article-paragraph-d7d0a5d87b27","heading":"מה אומרים המחקרים על טיפול בעזרת כלבים בילדים אוטיסטים?","text":"עם זאת, המחקרים עוסקים בקבוצות מגוונות של ילדים אוטיסטים ובסוגים שונים של התערבויות. לכן לא נכון להניח שכל תוצאה שנמצאה מתייחסת דווקא לילדים שאינם מדברים, או שכל פעילות חושית עם כלב מביאה בהכרח לשיפור בוויסות החושי."},{"id":"article-heading-a63e4f90495f","heading":"גם בלי הרבה מילים, הקשר הוא חלק מרכזי בטיפול","text":"גם בלי הרבה מילים, הקשר הוא חלק מרכזי בטיפול"},{"id":"article-paragraph-1002a42e2bc0","heading":"גם בלי הרבה מילים, הקשר הוא חלק מרכזי בטיפול","text":"אחד הדברים שחשוב לי להדגיש הוא שגם בעבודה עם ילדים שאינם מדברים, הקשר הטיפולי נשאר מרכזי."},{"id":"article-paragraph-bf1ce548e827","heading":"גם בלי הרבה מילים, הקשר הוא חלק מרכזי בטיפול","text":"לפעמים קל להתמקד רק בשאלה האם הילד הצליח לבצע את המשימה: האם הוא נתן פקודה לכלב, האם הוא זיהה את התמונה, האם הוא האכיל או הבריש."},{"id":"article-paragraph-552d6683d1b1","heading":"גם בלי הרבה מילים, הקשר הוא חלק מרכזי בטיפול","text":"אבל מבחינתי, חשוב לא פחות לראות איך הילד חווה את המפגש."},{"id":"article-paragraph-c4c71f7cdd4e","heading":"גם בלי הרבה מילים, הקשר הוא חלק מרכזי בטיפול","text":"האם הוא מרגיש בנוח? האם הוא מראה עניין? האם הוא יוזם? האם הוא מצליח לבחור? האם הוא מביע כשמשהו לא מתאים לו?"},{"id":"article-paragraph-40182b450f54","heading":"גם בלי הרבה מילים, הקשר הוא חלק מרכזי בטיפול","text":"הקשר נבנה גם דרך חזרתיות, צפיות וביטחון."},{"id":"article-paragraph-7eba1b7c074b","heading":"גם בלי הרבה מילים, הקשר הוא חלק מרכזי בטיפול","text":"כשהילד מכיר אותי, מכיר את הכלב ואת הפעילויות, הוא יכול לדעת טוב יותר למה לצפות ולהרגיש שיש לו מקום בתוך המפגש."},{"id":"article-paragraph-e33f32889cab","heading":"גם בלי הרבה מילים, הקשר הוא חלק מרכזי בטיפול","text":"ולפעמים, דווקא כשאנחנו מפחיתים את הדרישה לדבר או להגיב בדרך מסוימת, מתאפשרת יותר השתתפות."},{"id":"article-paragraph-90d534b56053","heading":"גם בלי הרבה מילים, הקשר הוא חלק מרכזי בטיפול","text":"אחד הדברים שהיו משמעותיים עבורי בעבודה בגנים היה גם המשוב שקיבלתי מהצוותים החינוכיים והטיפוליים שליוו את הילדים."},{"id":"article-paragraph-f47409ece755","heading":"גם בלי הרבה מילים, הקשר הוא חלק מרכזי בטיפול","text":"לאורך המפגשים, נשות הצוות שיתפו אותי לא פעם בכך שהן רואות אצל הילדים דברים שלא תמיד באים לידי ביטוי בפעילויות אחרות. לפעמים הן הופתעו מרמת שיתוף הפעולה, מהיוזמה של הילדים או מהיכולת שלהם לבצע משימות שבדרך כלל היו מתקשים להשתתף בהן."},{"id":"article-paragraph-cef0f0b21f38","heading":"גם בלי הרבה מילים, הקשר הוא חלק מרכזי בטיפול","text":"עבורי, התגובות האלה המחישו עד כמה חשוב למצוא את הדרך שמתאימה לכל ילד. לפעמים ילד שלא מרבה להשתתף בפעילות מסוימת יכול לגלות עניין, ליזום ולשתף פעולה כשהפעילות נעשית בדרך אחרת, עם מוטיבציה שמתאימה לו."},{"id":"article-paragraph-4f0a9db30912","heading":"גם בלי הרבה מילים, הקשר הוא חלק מרכזי בטיפול","text":"אני חושב שזה אחד היתרונות המשמעותיים של העבודה עם כלבים. הם יכולים ליצור עניין ורצון להשתתף, ובאמצעותם אפשר לפעמים לפגוש יכולות של הילד שלא תמיד באות לידי ביטוי בסיטואציות אחרות."},{"id":"article-heading-dbcdb7a51d37","heading":"חשוב להתאים את המפגש גם לילד וגם לכלב","text":"חשוב להתאים את המפגש גם לילד וגם לכלב"},{"id":"article-paragraph-db29f2899bcf","heading":"חשוב להתאים את המפגש גם לילד וגם לכלב","text":"לא כל פעילות מתאימה לכל ילד, ולא כל פעילות מתאימה לכל כלב."},{"id":"article-paragraph-2899b4477d2d","heading":"חשוב להתאים את המפגש גם לילד וגם לכלב","text":"ילד שרגיש למגע אולי יעדיף שלא ללטף את הכלב. ילד שרגיש לרעש יכול להיבהל מנביחה, וילד שמתקשה להתמודד עם חוסר ודאות עשוי להזדקק להכנה לפני שהכלב מתקרב."},{"id":"article-paragraph-ae82589e6d9d","heading":"חשוב להתאים את המפגש גם לילד וגם לכלב","text":"חשוב גם להתייחס לרווחת הכלב."},{"id":"article-paragraph-d090b87ce19f","heading":"חשוב להתאים את המפגש גם לילד וגם לכלב","text":"גם כלב שמורגל בעבודה טיפולית זקוק לאפשרות להתרחק, לנוח ולהפסיק פעילות שלא נעימה לו."},{"id":"article-paragraph-814264f67b37","heading":"חשוב להתאים את המפגש גם לילד וגם לכלב","text":"לכן, לפני הפעילות ובמהלכה חשוב לשים לב לשני הצדדים, להתאים את הסביבה, לאפשר בחירה ולהימנע מהצפה חושית."},{"id":"article-paragraph-10bd9d24ecae","heading":"חשוב להתאים את המפגש גם לילד וגם לכלב","text":"המטרה היא ליצור מפגש שיש בו אפשרות לחוויה חיובית ומשמעותית, ולא להעמיס על הילד או על הכלב גירויים רק לשם התנסות."},{"id":"article-heading-7c13ae2e2530","heading":"לסיכום - טיפול לא חייב להתחיל במילים","text":"לסיכום - טיפול לא חייב להתחיל במילים"},{"id":"article-paragraph-2c5fe067e8e0","heading":"לסיכום - טיפול לא חייב להתחיל במילים","text":"העבודה שלי עם ילדים על הרצף האוטיסטי שאינם משתמשים בדיבור חידדה עבורי משהו חשוב: טיפול רגשי לא חייב להתבסס על שיחה."},{"id":"article-paragraph-6d6e44103ce9","heading":"לסיכום - טיפול לא חייב להתחיל במילים","text":"אפשר לעבוד על תקשורת, קשר, בחירה, יוזמה, ויסות והתמודדות דרך חוויות משותפות ופעילויות מוחשיות."},{"id":"article-paragraph-1cf6f29917b3","heading":"לסיכום - טיפול לא חייב להתחיל במילים","text":"הכלבים מאפשרים מגוון גדול של התנסויות כאלה: האכלה, הברשה, פקודות פשוטות, משחקי חיפוש, פעילויות חושיות, משחקים מותאמים ומשימות משותפות שדורשות שיתוף פעולה בין הילדים."},{"id":"article-paragraph-13a30a800e16","heading":"לסיכום - טיפול לא חייב להתחיל במילים","text":"אבל המטרה היא לא רק שהילד יבצע פעילות עם הכלב."},{"id":"article-paragraph-7cc3a0c9412a","heading":"לסיכום - טיפול לא חייב להתחיל במילים","text":"המטרה היא ליצור עבורו הזדמנות להשתתף, להבין, לבחור, להביע את עצמו, לתקשר עם ילדים אחרים ולחוות קשר בדרך שמתאימה לו."},{"id":"article-paragraph-121f344fd9f9","heading":"לסיכום - טיפול לא חייב להתחיל במילים","text":"גם כשאין מילים, יש תקשורת. וגם כשאין שיחה, יכול להתרחש תהליך טיפולי משמעותי."},{"id":"article-reference-1ce7c3847343","heading":"מקורות","text":"Galvany-López et al. (2024) – The Impact of Dog-Assisted Therapy Among Children and Adolescents with Autism Spectrum Disorder סקירה שיטתית של 19 מאמרים על התערבויות בעזרת כלבים בקרב ילדים ובני נוער אוטיסטים, שהתמקדה בין היתר בתקשורת ובאינטראקציה חברתית."},{"id":"article-reference-d1e243b62ce3","heading":"מקורות","text":"Polak-Passy, Ben-Itzchak & Zachor (2024) – Enhancing Social Communication Behaviors in Children with Autism מחקר ישראלי בהשתתפות 37 ילדים אוטיסטים בגיל הגן, שבחן שינוי בהתנהגויות תקשורתיות במהלך התערבות מובנית של עבודה עם כלבים."},{"id":"article-reference-135e5cfdc0b6","heading":"מקורות","text":"Xiao et al. (2024) – Effectiveness of Animal-Assisted Activities and Therapies for Autism Spectrum Disorder סקירה שיטתית ומטא־אנליזה של 45 מחקרים, שבחנה התערבויות בעזרת בעלי חיים והשפעתן על מדדים שונים בקרב אנשים אוטיסטים."},{"id":"article-reference-e11125abd6fc","heading":"מקורות","text":"American Speech-Language-Hearing Association (ASHA) – Augmentative and Alternative Communication מקור מקצועי בנושא תקשורת תומכת וחלופית, כולל שימוש בסמלים, מחוות, תמונות ומכשירי תקשורת."},{"id":"article-reference-91186f6f535c","heading":"מקורות","text":"National Autistic Society – Autism and Sensory Processing מידע מקצועי על הבדלים בעיבוד חושי אצל אנשים אוטיסטים, כולל רגישות יתר, תת־רגישות וחיפוש אחר גירויים חושיים."}]},{"title":"טיפול בעזרת כלבים במחלקות סיעודיות - תנועה, קשר ומשמעות בגיל השלישי","url":"https://derech-hakelev.com/pages/articles/dog-therapy-nursing-wards/","entries":[{"id":"article-title-1ea16f03f4f2","heading":"תחילת המאמר","text":"טיפול בעזרת כלבים במחלקות סיעודיות - תנועה, קשר ומשמעות בגיל השלישי"},{"id":"article-paragraph-6f4e2b0b8fec","heading":"פתיחת המאמר","text":"במשך כשנתיים עבדתי עם כלבים במחלקות סיעודיות בדיור מוגן. זאת הייתה אחת העבודות המשמעותיות שעשיתי, אבל גם אחת המורכבות שבהן."},{"id":"article-paragraph-70d5c1164214","heading":"פתיחת המאמר","text":"מצד אחד, היו שם הרבה רגעים של שמחה, צחוק, קשר וחוויות שלא תמיד אפשר להסביר במילים. מצד שני, נחשפתי גם לבדידות, לכאב, לירידה בתפקוד, לאובדן ולמצבים שלא תמיד פשוט להתמודד איתם."},{"id":"article-paragraph-eb397e2cd610","heading":"פתיחת המאמר","text":"העבודה הזאת לימדה אותי הרבה על כלבנות טיפולית, אבל אולי יותר מהכול, היא חידדה עבורי את החשיבות של התאמת הטיפול לאדם שנמצא מולנו."},{"id":"article-paragraph-49268f9e0808","heading":"פתיחת המאמר","text":"כשאנחנו מגיעים עם כלב לקבוצה, קל לחשוב קודם על הפעילויות שאנחנו יכולים להעביר. אילו משחקים נביא? מה נלמד על הכלבים? איך נחדש הפעם?"},{"id":"article-paragraph-b3cb03f2fc14","heading":"פתיחת המאמר","text":"אבל השאלה הראשונה צריכה להיות אחרת: מה אנחנו רוצים להשיג עבור האנשים שנמצאים מולנו?"},{"id":"article-paragraph-f10326b5a097","heading":"פתיחת המאמר","text":"במחלקות הסיעודיות שבהן עבדתי, המטרות המרכזיות שלי היו עידוד תנועה, תקשורת, קשר חברתי, השתתפות ויצירת חוויות חיוביות."},{"id":"article-paragraph-81b8a87d96df","heading":"פתיחת המאמר","text":"ומתוך המטרות האלה בניתי את הפעילויות."},{"id":"article-heading-809150ff4f75","heading":"מה מאפיין את העבודה עם דיירים במחלקות סיעודיות?","text":"מה מאפיין את העבודה עם דיירים במחלקות סיעודיות?"},{"id":"article-paragraph-dfeebfcd366e","heading":"מה מאפיין את העבודה עם דיירים במחלקות סיעודיות?","text":"אוכלוסיית הגיל השלישי מגוונת מאוד. יש אנשים שממשיכים לתפקד באופן עצמאי גם בגיל מבוגר, ויש אנשים שמתמודדים עם מגבלות גופניות וקוגניטיביות משמעותיות."},{"id":"article-paragraph-283fa21dea83","heading":"מה מאפיין את העבודה עם דיירים במחלקות סיעודיות?","text":"במחלקות סיעודיות אנחנו פוגשים בדרך כלל אנשים שזקוקים לעזרה בחלק גדול מפעולות היום-יום, ולעיתים גם מתמודדים עם מחלות כרוניות, ירידה בניידות, קשיי זיכרון, פגיעה בחושים ושינויים במצב הרגשי."},{"id":"article-paragraph-394c9fb4ecde","heading":"מה מאפיין את העבודה עם דיירים במחלקות סיעודיות?","text":"חלק מהדיירים מתמודדים עם דמנציה, ואחרים עם מגבלות גופניות משמעותיות ללא פגיעה קוגניטיבית דומה."},{"id":"article-paragraph-1c9d48dc80e4","heading":"מה מאפיין את העבודה עם דיירים במחלקות סיעודיות?","text":"גם בתוך אותה מחלקה יכולים להיות הבדלים גדולים מאוד בין הדיירים."},{"id":"article-paragraph-b4d6338ba190","heading":"מה מאפיין את העבודה עם דיירים במחלקות סיעודיות?","text":"אדם אחד מסוגל להרים את שתי הידיים ולזרוק כדור, ואחר יצליח לבצע רק תנועה קטנה עם יד אחת. אדם אחד ינהל איתנו שיחה שלמה, ואחר יתקשה למצוא מילים או לזכור את מה שאמרנו לפני כמה דקות."},{"id":"article-paragraph-7f8bc53b9113","heading":"מה מאפיין את העבודה עם דיירים במחלקות סיעודיות?","text":"לכן, בעבודה הזאת אי אפשר לצפות שכולם ישתתפו באותו האופן."},{"id":"article-heading-d02b4c4d3df0","heading":"קודם כול - מה המטרות שלנו?","text":"קודם כול - מה המטרות שלנו?"},{"id":"article-paragraph-e063c82a57e1","heading":"קודם כול - מה המטרות שלנו?","text":"אחד הדברים שאני משתדל לעשות בכל מסגרת טיפולית הוא להגדיר קודם כול את המטרות."},{"id":"article-paragraph-1e6bf146ea9e","heading":"קודם כול - מה המטרות שלנו?","text":"זה אולי נשמע מובן מאליו, אבל אנחנו כל כך רגילים לפעילויות מסוימות, עד שאנחנו עלולים לנסות להתאים אותן לכל אוכלוסייה."},{"id":"article-paragraph-7312c9016bcb","heading":"קודם כול - מה המטרות שלנו?","text":"בעבודה עם ילדים, למשל, אני משלב לא מעט משחקים, שיחות על רגשות, לימוד על שפת הגוף של הכלבים ופעילויות שמשמשות בסיס לשיח ולהשלכה על החיים שלהם."},{"id":"article-paragraph-33dce3357647","heading":"קודם כול - מה המטרות שלנו?","text":"אבל במחלקות הסיעודיות הרגשתי שחלק גדול מהתכנים האלה פשוט פחות רלוונטי למטרות שהצבתי."},{"id":"article-paragraph-093b969c8d8f","heading":"קודם כול - מה המטרות שלנו?","text":"לא היה לי צורך ללמד את הדיירים בכל מפגש נושא חדש מעולם הכלבים, או לנסות לייצר שיח עיוני מורכב."},{"id":"article-paragraph-7e7389ac74ff","heading":"קודם כול - מה המטרות שלנו?","text":"רציתי לעודד אותם לנוע, לדבר, לצחוק, ליצור קשר עם אנשים אחרים ולהשתתף בפעילות שיש בה עניין והנאה."},{"id":"article-paragraph-8e51bd8eceb5","heading":"קודם כול - מה המטרות שלנו?","text":"לכן, גם הפעילויות שבחרתי היו בדרך כלל פשוטות יחסית."},{"id":"article-paragraph-5742f16d81bf","heading":"קודם כול - מה המטרות שלנו?","text":"אבל הפשטות שלהן לא הופכת אותן לפחות משמעותיות."},{"id":"article-heading-0907b0dfaaed","heading":"עידוד תנועה באמצעות פעילות עם כלבים","text":"עידוד תנועה באמצעות פעילות עם כלבים"},{"id":"article-paragraph-c868b12c0d51","heading":"עידוד תנועה באמצעות פעילות עם כלבים","text":"אחת המטרות המרכזיות שלי הייתה לעודד תנועה."},{"id":"article-paragraph-4ac82bab41a7","heading":"עידוד תנועה באמצעות פעילות עם כלבים","text":"במחלקות הסיעודיות שבהן עבדתי, רבים מהדיירים ישבו בכיסאות גלגלים והתמודדו עם מגבלות בטווחי התנועה וביכולת להפעיל את הגוף."},{"id":"article-paragraph-820d1a020f88","heading":"עידוד תנועה באמצעות פעילות עם כלבים","text":"הכלבים אפשרו לי להכניס תנועה לתוך פעילות שהייתה מעניינת ומהנה עבורם."},{"id":"article-paragraph-db96c4dafa0c","heading":"עידוד תנועה באמצעות פעילות עם כלבים","text":"למשל, הייתי מבקש מדייר לזרוק כדור או משחק לכלב. בפעילות הזאת הוא נדרש להרים את היד, לכוון ולבצע תנועת זריקה."},{"id":"article-paragraph-b4463bed0ea0","heading":"עידוד תנועה באמצעות פעילות עם כלבים","text":"כדי שהכלב יסתובב, הייתי מבקש מהדייר להוביל אותו באמצעות תנועה מעגלית עם היד."},{"id":"article-paragraph-ec0ff2c9a786","heading":"עידוד תנועה באמצעות פעילות עם כלבים","text":"לעיתים ביקשתי לבצע את התנועה עם יד ימין, ולעיתים עם יד שמאל."},{"id":"article-paragraph-e4198cd5a42e","heading":"עידוד תנועה באמצעות פעילות עם כלבים","text":"אפשר היה לשלב גם הברשה, הגשת חטיף, החזקת צעצוע או שימוש באביזרים אחרים."},{"id":"article-paragraph-495a3c9a3612","heading":"עידוד תנועה באמצעות פעילות עם כלבים","text":"כמובן, לא כל דייר היה מסוגל לבצע את אותה התנועה. במקרים מסוימים היה צורך לצמצם את טווח התנועה, להיעזר באביזר מותאם או להסתפק בפעולה קטנה מאוד."},{"id":"article-paragraph-4ca2c2f1a956","heading":"עידוד תנועה באמצעות פעילות עם כלבים","text":"המטרה לא הייתה שכולם יצליחו לבצע משימה מסוימת, אלא שכל אחד יוכל להשתתף בהתאם ליכולות שלו."},{"id":"article-paragraph-387b96891753","heading":"עידוד תנועה באמצעות פעילות עם כלבים","text":"חשוב לי גם להבחין בין עידוד תנועה לבין שיקום גופני מקצועי. הפעילויות שלי נועדו לעודד השתתפות והפעלה מותאמת של הגוף, ולא להחליף פיזיותרפיה או טיפול רפואי."},{"id":"article-heading-7d96236ecfb1","heading":"דוגמאות לפעילויות עם כלבים במחלקות סיעודיות","text":"דוגמאות לפעילויות עם כלבים במחלקות סיעודיות"},{"id":"article-paragraph-f256039ed2bc","heading":"דוגמאות לפעילויות עם כלבים במחלקות סיעודיות","text":"במהלך העבודה השתמשתי במגוון פעילויות ופקודות מוכרות מעולם הכלבנות, אבל התאמתי אותן למטרות וליכולות של הדיירים."},{"id":"article-paragraph-9ed4836f2364","heading":"דוגמאות לפעילויות עם כלבים במחלקות סיעודיות","text":"היתרון של הפקודות האלה הוא שהן פשוטות יחסית, מוכרות לכלבים ואפשר לחזור עליהן פעמים רבות. את אותה הפעילות אפשר גם להתאים כך שתדרוש יותר או פחות תנועה, או שתעודד דווקא תקשורת ושיתוף פעולה."},{"id":"article-heading-c38ae8fe16ab","heading":"האכלה","text":"האכלה"},{"id":"article-paragraph-024fa43bcfb6","heading":"דוגמאות לפעילויות עם כלבים במחלקות סיעודיות","text":"אחת הפעילויות הבסיסיות היא לתת לכלב חטיף."},{"id":"article-paragraph-305312982dd2","heading":"דוגמאות לפעילויות עם כלבים במחלקות סיעודיות","text":"הדייר יכול להחזיק את החטיף, להושיט את היד ולתת אותו לכלב, בהתאם ליכולתו וללא סיכון לנשיכה."},{"id":"article-paragraph-6c767f75e7a8","heading":"דוגמאות לפעילויות עם כלבים במחלקות סיעודיות","text":"גם פעולה פשוטה כזאת מאפשרת לעבוד על הושטת יד, אחיזה, בחירה ויצירת קשר."},{"id":"article-paragraph-7d571dee119c","heading":"דוגמאות לפעילויות עם כלבים במחלקות סיעודיות","text":"אצל דיירים שהתקשו להחזיק חטיף קטן, היה אפשר להיעזר בדרך הגשה אחרת, למשל להניח אותו בכלי מתאים."},{"id":"article-heading-f564c69ef922","heading":"סירוק והברשה","text":"סירוק והברשה"},{"id":"article-paragraph-3fff9c85e7b0","heading":"דוגמאות לפעילויות עם כלבים במחלקות סיעודיות","text":"פעילות נוספת היא הברשת הכלב."},{"id":"article-paragraph-372fd2c034a1","heading":"דוגמאות לפעילויות עם כלבים במחלקות סיעודיות","text":"אפשר להניח מברשת בידו של הדייר ולעזור לו לבצע תנועות הברשה עדינות, אם הוא מעוניין בכך."},{"id":"article-paragraph-c150e0430dbd","heading":"דוגמאות לפעילויות עם כלבים במחלקות סיעודיות","text":"הפעילות יכולה לעודד הפעלה של היד, אחיזה ותנועות חוזרות, לצד מגע עם הכלב."},{"id":"article-paragraph-0cb0c56390c4","heading":"דוגמאות לפעילויות עם כלבים במחלקות סיעודיות","text":"כמובן, חשוב להתאים את המברשת ואת אופן הפעילות גם לכלב, ולוודא שהמגע נעים לו."},{"id":"article-heading-2538e18a7637","heading":"\"יד\"","text":"\"יד\""},{"id":"article-paragraph-d0c8595b87f8","heading":"דוגמאות לפעילויות עם כלבים במחלקות סיעודיות","text":"בפקודה הזאת הדייר מבקש מהכלב לתת לו יד."},{"id":"article-paragraph-83e2fae2d77d","heading":"דוגמאות לפעילויות עם כלבים במחלקות סיעודיות","text":"אפשר להחזיק את היד פתוחה, להושיט אותה לכיוון הכלב ולחכות שהוא יניח עליה את כפו."},{"id":"article-paragraph-613676aad33a","heading":"דוגמאות לפעילויות עם כלבים במחלקות סיעודיות","text":"זאת הזדמנות לעבודה על הושטת יד, קשר עין, תזמון ותקשורת."},{"id":"article-paragraph-da8bfba3ac4d","heading":"דוגמאות לפעילויות עם כלבים במחלקות סיעודיות","text":"יש דיירים שמסוגלים לתת את הפקודה בקול, ואחרים יכולים להשתמש במחווה או לקבל סיוע בהפעלת הכלב."},{"id":"article-heading-f7ac36eb79b1","heading":"\"תביא\" - זריקה והחזרה של משחק","text":"\"תביא\" - זריקה והחזרה של משחק"},{"id":"article-paragraph-9bff6cf28860","heading":"דוגמאות לפעילויות עם כלבים במחלקות סיעודיות","text":"אחת הפעילויות שבהן השתמשתי הרבה הייתה זריקת משחק לכלב."},{"id":"article-paragraph-2835f827cd8c","heading":"דוגמאות לפעילויות עם כלבים במחלקות סיעודיות","text":"הדייר זורק כדור או צעצוע מתאים, והכלב רץ להביא אותו ומחזיר אותו."},{"id":"article-paragraph-5195cb22344f","heading":"דוגמאות לפעילויות עם כלבים במחלקות סיעודיות","text":"אפשר לבקש מהדייר להרים את היד, לכוון למקום מסוים או לנסות לזרוק מעט רחוק יותר, אם הדבר מתאים ליכולותיו."},{"id":"article-paragraph-76f5fc5a2909","heading":"דוגמאות לפעילויות עם כלבים במחלקות סיעודיות","text":"הפעילות מאפשרת תנועה של הכתף, המרפק וכף היד, וגם מעודדת מעקב אחר הכלב והשתתפות פעילה."},{"id":"article-paragraph-550830259ac8","heading":"דוגמאות לפעילויות עם כלבים במחלקות סיעודיות","text":"בפעילות הזאת השתמשתי גם בהיכרות האישית עם הדיירים. למשל, הדייר שהיה בעבר אלוף הארץ בג'ודו היה מתאמץ במיוחד כשהייתי מזכיר לו את הישגיו."},{"id":"article-heading-5ff11ecb94d0","heading":"\"לא לגעת\" - המתנה ושליטה בדחף","text":"\"לא לגעת\" - המתנה ושליטה בדחף"},{"id":"article-paragraph-2a3f638492c6","heading":"דוגמאות לפעילויות עם כלבים במחלקות סיעודיות","text":"בתרגיל הזה הדייר מציג לכלב חטיף, והכלב צריך להמתין ולא לקחת אותו עד שהוא מקבל אישור."},{"id":"article-paragraph-82911cd06aab","heading":"דוגמאות לפעילויות עם כלבים במחלקות סיעודיות","text":"הדייר יכול להחזיק את החטיף במקום מתאים, לסמן לכלב להמתין ואז לאפשר לו לקבל אותו."},{"id":"article-paragraph-cb08c98f3c03","heading":"דוגמאות לפעילויות עם כלבים במחלקות סיעודיות","text":"מעבר לתקשורת עם הכלב, יש כאן הזדמנות לעבודה על רצף פעולות, קשב והבנת הקשר בין הוראה לתגובה."},{"id":"article-paragraph-60652b85ebea","heading":"דוגמאות לפעילויות עם כלבים במחלקות סיעודיות","text":"חשוב שהכלב יהיה מאומן בתרגיל ושהחטיף יוצג בצורה בטוחה, בלי ליצור מצב שבו הכלב מנסה לחטוף אותו מידו של הדייר."},{"id":"article-heading-87355bcd37b0","heading":"חישוק - \"כנס\"","text":"חישוק - \"כנס\""},{"id":"article-paragraph-a1b5cba8cddd","heading":"דוגמאות לפעילויות עם כלבים במחלקות סיעודיות","text":"בפעילות הזאת הדיירים מחזיקים חישוק והכלב עובר דרכו."},{"id":"article-paragraph-f166b4625344","heading":"דוגמאות לפעילויות עם כלבים במחלקות סיעודיות","text":"אפשר לעבוד מול דייר אחד, או לבקש משני דיירים להחזיק יחד את החישוק בזמן שאדם נוסף מסמן לכלב לעבור."},{"id":"article-paragraph-5b21e6356995","heading":"דוגמאות לפעילויות עם כלבים במחלקות סיעודיות","text":"כך אפשר לשלב עבודה על אחיזה, הפעלת הידיים, תיאום ושיתוף פעולה בין הדיירים."},{"id":"article-paragraph-8da918856129","heading":"דוגמאות לפעילויות עם כלבים במחלקות סיעודיות","text":"את גובה החישוק והמרחק מתאימים ליכולות של הדיירים ושל הכלב. אין צורך שהכלב יקפוץ: מעבר דרך חישוק שמונח בגובה נמוך יכול לשרת את אותה מטרה."},{"id":"article-heading-f454bfa28175","heading":"\"אליי\" - לקרוא לכלב ולהאכיל אותו","text":"\"אליי\" - לקרוא לכלב ולהאכיל אותו"},{"id":"article-paragraph-d772d8a8a5bc","heading":"דוגמאות לפעילויות עם כלבים במחלקות סיעודיות","text":"זאת הייתה אחת הפעילויות שאהבתי לשלב."},{"id":"article-paragraph-b64ed1c56c2d","heading":"דוגמאות לפעילויות עם כלבים במחלקות סיעודיות","text":"הייתי נותן לדייר חטיף ומתרחק ממנו יחד עם הכלב."},{"id":"article-paragraph-18576f7e348f","heading":"דוגמאות לפעילויות עם כלבים במחלקות סיעודיות","text":"לאחר מכן הדייר היה צריך לקרוא לכלב או לסמן לו להגיע אליו."},{"id":"article-paragraph-c08c82064e57","heading":"דוגמאות לפעילויות עם כלבים במחלקות סיעודיות","text":"כשהכלב היה מגיע, הדייר היה נותן לו את החטיף."},{"id":"article-paragraph-275b9cbc5ad2","heading":"דוגמאות לפעילויות עם כלבים במחלקות סיעודיות","text":"התרגיל משלב כמה דברים: יוזמה, תקשורת, קריאה או שימוש במחווה, קשר עם הכלב והושטת יד לצורך האכלה."},{"id":"article-paragraph-8443676c120f","heading":"דוגמאות לפעילויות עם כלבים במחלקות סיעודיות","text":"אפשר להתאים את המרחק ואת אופן הקריאה ליכולות הדייר, כך שגם מי שמתקשה לדבר יוכל להשתתף באמצעות סימן מוסכם."},{"id":"article-heading-c535cd658692","heading":"\"שב\" ו\"ארצה\"","text":"\"שב\" ו\"ארצה\""},{"id":"article-paragraph-adecd8fcd990","heading":"דוגמאות לפעילויות עם כלבים במחלקות סיעודיות","text":"אלו שתי פקודות פשוטות שאפשר לשלב כמעט בכל מפגש."},{"id":"article-paragraph-d3f62bcdf20f","heading":"דוגמאות לפעילויות עם כלבים במחלקות סיעודיות","text":"הדייר מבקש מהכלב לשבת או לשכב, באמצעות פקודה קולית או מחווה."},{"id":"article-paragraph-b66c37a2d0cb","heading":"דוגמאות לפעילויות עם כלבים במחלקות סיעודיות","text":"היתרון הוא שהתגובה של הכלב ברורה ומיידית. הדייר מבצע פעולה ורואה את התוצאה שלה."},{"id":"article-paragraph-e6603fdd4d6f","heading":"דוגמאות לפעילויות עם כלבים במחלקות סיעודיות","text":"הפקודות האלה מתאימות גם לפעילויות קצרות וחזרתיות, ואפשר לשלב אותן עם האכלה וחיזוק של הכלב."},{"id":"article-heading-cc41f66a85a4","heading":"\"סיבוב\"","text":"\"סיבוב\""},{"id":"article-paragraph-5a6a01147e87","heading":"דוגמאות לפעילויות עם כלבים במחלקות סיעודיות","text":"בפעילות הזאת הדייר מסמן לכלב להסתובב באמצעות תנועה מעגלית של היד."},{"id":"article-paragraph-419836d1a5d7","heading":"דוגמאות לפעילויות עם כלבים במחלקות סיעודיות","text":"אפשר לבקש ממנו לבצע סיבוב בכיוון אחד, ולאחר מכן בכיוון השני."},{"id":"article-paragraph-260d9421d444","heading":"דוגמאות לפעילויות עם כלבים במחלקות סיעודיות","text":"אצל דיירים שמסוגלים לכך, אפשר לתרגל את הפעולה עם כל אחת מהידיים."},{"id":"article-paragraph-3a11d6d1d71c","heading":"דוגמאות לפעילויות עם כלבים במחלקות סיעודיות","text":"זאת דוגמה טובה לכך שפקודה פשוטה יכולה להפוך להזדמנות לעידוד תנועה ולתיאום בין הפעולה של הדייר לבין התגובה של הכלב."},{"id":"article-heading-ab0f55339c24","heading":"\"קפוץ\" ומעבר מעל או מתחת לרגליים","text":"\"קפוץ\" ומעבר מעל או מתחת לרגליים"},{"id":"article-paragraph-c4bce4444311","heading":"דוגמאות לפעילויות עם כלבים במחלקות סיעודיות","text":"אצל חלק מהדיירים הייתה אפשרות לשלב גם עבודה עם הרגליים."},{"id":"article-paragraph-aad6d0ba32eb","heading":"דוגמאות לפעילויות עם כלבים במחלקות סיעודיות","text":"למשל, דייר שמסוגל להרים מעט את רגליו יכול ליצור מרווח, והכלב יכול לעבור מתחתיהן, אם הדבר בטוח ונוח לשניהם."},{"id":"article-paragraph-83e5b2288001","heading":"דוגמאות לפעילויות עם כלבים במחלקות סיעודיות","text":"במקרים אחרים אפשר היה ליצור מכשול נמוך שהכלב עובר מעליו."},{"id":"article-paragraph-1aa63d795fdf","heading":"דוגמאות לפעילויות עם כלבים במחלקות סיעודיות","text":"גם כאן, המטרה היא לא שהכלב יבצע קפיצה מרשימה, אלא ליצור הזדמנות להפעלה מותאמת של הגוף."},{"id":"article-paragraph-4765998132f3","heading":"דוגמאות לפעילויות עם כלבים במחלקות סיעודיות","text":"חשוב במיוחד לוודא שאין עומס על הרגליים, שאין סיכון לאובדן שיווי משקל או לפגיעה בדייר, ושהפעילות מתאימה גם ליכולותיו הגופניות של הכלב."},{"id":"article-heading-a76dcfa5c9d0","heading":"איך בוחרים פעילות מתאימה?","text":"איך בוחרים פעילות מתאימה?"},{"id":"article-paragraph-7d8bda801ccb","heading":"דוגמאות לפעילויות עם כלבים במחלקות סיעודיות","text":"הרשימה הזאת יכולה לתת רעיונות לכלבנים טיפוליים שעובדים עם דיירים סיעודיים, אבל אין צורך לבצע את כל הפעילויות בכל מפגש."},{"id":"article-paragraph-aa7e2250f950","heading":"דוגמאות לפעילויות עם כלבים במחלקות סיעודיות","text":"הבחירה צריכה להתחיל במטרה שאנחנו רוצים להשיג."},{"id":"article-paragraph-b3a33d8e7477","heading":"דוגמאות לפעילויות עם כלבים במחלקות סיעודיות","text":"אם המטרה היא לעודד תנועה של היד, אפשר לבחור בזריקה, בסיבוב או בהברשה. אם אנחנו רוצים לעודד תקשורת, אפשר להשתמש ב\"אליי\", ב\"יד\" או בפקודות פשוטות אחרות."},{"id":"article-paragraph-fd5d0dfb7814","heading":"דוגמאות לפעילויות עם כלבים במחלקות סיעודיות","text":"וכשאנחנו רוצים לעודד שיתוף פעולה בין הדיירים, אפשר לבחור בפעילות עם חישוק או בהעברת אביזרים ביניהם."},{"id":"article-paragraph-81702b4710f3","heading":"דוגמאות לפעילויות עם כלבים במחלקות סיעודיות","text":"אותה פקודה יכולה לשרת מטרות שונות, בהתאם לאופן שבו אנחנו משתמשים בה ולצרכים של האדם שמולנו."},{"id":"article-heading-eede2b0da572","heading":"הפעילות הקבוצתית היא במידה רבה עבודה פרטנית","text":"הפעילות הקבוצתית היא במידה רבה עבודה פרטנית"},{"id":"article-paragraph-12d6bb9b36d8","heading":"הפעילות הקבוצתית היא במידה רבה עבודה פרטנית","text":"חלק מהקבוצות שהעברתי היו גדולות יחסית."},{"id":"article-paragraph-3fb47b4ec49e","heading":"הפעילות הקבוצתית היא במידה רבה עבודה פרטנית","text":"לכאורה מדובר בפעילות קבוצתית, אבל בפועל, חלק גדול מהעבודה נעשה מול כל דייר בנפרד."},{"id":"article-paragraph-b54b806119a4","heading":"הפעילות הקבוצתית היא במידה רבה עבודה פרטנית","text":"הייתי עובר בין המשתתפים עם הכלבים, מתאים לכל אחד פעילות לפי יכולותיו ומנסה למצוא דרך שבה יוכל לקחת חלק."},{"id":"article-paragraph-4f84dd9e9945","heading":"הפעילות הקבוצתית היא במידה רבה עבודה פרטנית","text":"אצל דייר אחד אפשר היה לעבוד על זריקה, ואצל אחר על הושטת יד או על תנועה קטנה של האצבעות."},{"id":"article-paragraph-6560e8f06506","heading":"הפעילות הקבוצתית היא במידה רבה עבודה פרטנית","text":"גם המרחב הפיזי יצר אתגרים."},{"id":"article-paragraph-bf83db99796f","heading":"הפעילות הקבוצתית היא במידה רבה עבודה פרטנית","text":"הכלב לא תמיד הצליח להגיע לדייר בגלל גובה כיסא הגלגלים או המיקום שלו. במקרים אחרים היה צורך לשנות את גובה האביזר, את המרחק או את אופן ביצוע המשימה."},{"id":"article-paragraph-517fb2fd0d09","heading":"הפעילות הקבוצתית היא במידה רבה עבודה פרטנית","text":"היו גם דיירים שלא השתתפו באופן פעיל בכל התרגילים, אבל כן רצו ללטף את הכלב, להתבונן במתרחש או להשתתף בשיחה."},{"id":"article-paragraph-85a5383e42e4","heading":"הפעילות הקבוצתית היא במידה רבה עבודה פרטנית","text":"כל אלה היו דרכים לגיטימיות להשתתף."},{"id":"article-paragraph-9b9888cb8122","heading":"הפעילות הקבוצתית היא במידה רבה עבודה פרטנית","text":"הקבוצה אפשרה מפגש חברתי, אבל ההתייחסות לכל אדם הייתה צריכה להישאר אישית."},{"id":"article-heading-270b170c16e7","heading":"תקשורת וקשר חברתי - לא פחות חשובים מהתנועה","text":"תקשורת וקשר חברתי - לא פחות חשובים מהתנועה"},{"id":"article-paragraph-3cd2c7f83909","heading":"תקשורת וקשר חברתי - לא פחות חשובים מהתנועה","text":"מעבר לתנועה, אחת המטרות החשובות שלי הייתה לעודד תקשורת."},{"id":"article-paragraph-ad2b3b5274fc","heading":"תקשורת וקשר חברתי - לא פחות חשובים מהתנועה","text":"זה התחיל בשיחות האישיות עם הדיירים, אבל לא הסתיים שם."},{"id":"article-paragraph-7a26274fc530","heading":"תקשורת וקשר חברתי - לא פחות חשובים מהתנועה","text":"במהלך הפעילות הייתי שואל אותם על המשפחות שלהם, על הילדים, על העבר שלהם ועל דברים שעניינו אותם. היינו צוחקים, מספרים סיפורים ומשתמשים לא מעט בהומור."},{"id":"article-paragraph-6dfe1aa8ab6d","heading":"תקשורת וקשר חברתי - לא פחות חשובים מהתנועה","text":"ניסיתי גם לעודד תקשורת בין הדיירים עצמם."},{"id":"article-paragraph-6a41c4dac306","heading":"תקשורת וקשר חברתי - לא פחות חשובים מהתנועה","text":"למשל, כשדייר סיים לשחק עם אביזר מסוים, במקום להחזיר אותו אליי, ביקשתי ממנו להעביר אותו לדייר אחר."},{"id":"article-paragraph-41e74955e06f","heading":"תקשורת וקשר חברתי - לא פחות חשובים מהתנועה","text":"זאת פעולה קטנה, אבל היא יוצרת הזדמנות לפנות לאדם נוסף, ליצור קשר ולהשתתף בפעילות משותפת."},{"id":"article-paragraph-3e3591b8b12e","heading":"תקשורת וקשר חברתי - לא פחות חשובים מהתנועה","text":"היו גם משימות שדרשו שיתוף פעולה."},{"id":"article-paragraph-eca304af9bf6","heading":"תקשורת וקשר חברתי - לא פחות חשובים מהתנועה","text":"למשל, שני דיירים יכלו להחזיק יחד חישוק, בזמן שדייר אחר מסמן לכלב לעבור דרכו."},{"id":"article-paragraph-1247fab2b50b","heading":"תקשורת וקשר חברתי - לא פחות חשובים מהתנועה","text":"גם כאן היה צורך להתאים את הפעילות ליכולות שלהם. בחלק מהמקרים היה צורך להחזיק את החישוק נמוך יותר, או לסייע לאחד המשתתפים."},{"id":"article-paragraph-850af0969ca9","heading":"תקשורת וקשר חברתי - לא פחות חשובים מהתנועה","text":"המטרה לא הייתה רק שהכלב יעבור בחישוק, אלא שהדיירים יהיו חלק ממשהו שהם עושים יחד."},{"id":"article-heading-909c3a07453b","heading":"חשוב לזכור - הדיירים הם אנשים בעלי רצונות ודעות משלהם","text":"חשוב לזכור - הדיירים הם אנשים בעלי רצונות ודעות משלהם"},{"id":"article-paragraph-d093680d131c","heading":"חשוב לזכור - הדיירים הם אנשים בעלי רצונות ודעות משלהם","text":"אחד הדברים שהיה חשוב לי לשמור עליהם לאורך העבודה הוא הזכות של כל דייר לבחור אם להשתתף בפעילות."},{"id":"article-paragraph-b2439c0ddd6f","heading":"חשוב לזכור - הדיירים הם אנשים בעלי רצונות ודעות משלהם","text":"במחלקות סיעודיות יש אנשים שזקוקים לעזרה רבה בפעולות היום-יום. אבל העובדה שאדם תלוי באחרים מבחינה גופנית או סיעודית לא אומרת שהוא איבד את הזכות להחליט מה מתאים לו ומה הוא רוצה."},{"id":"article-paragraph-e8216fdbde1b","heading":"חשוב לזכור - הדיירים הם אנשים בעלי רצונות ודעות משלהם","text":"יצא לי לראות מצבים שבהם אנשי צוות הביאו דיירים לפעילות גם כשהם הביעו התנגדות או אמרו שהם לא מעוניינים להשתתף."},{"id":"article-paragraph-892d1a3d5e2e","heading":"חשוב לזכור - הדיירים הם אנשים בעלי רצונות ודעות משלהם","text":"במקרים כאלה הייתי מבקש לא להביא את מי שלא רוצה להגיע, ולהחזיר למחלקה דייר שביקש לצאת מהפעילות."},{"id":"article-paragraph-08ee7575b50b","heading":"חשוב לזכור - הדיירים הם אנשים בעלי רצונות ודעות משלהם","text":"גם אם אני מאמין שהמפגש עם הכלבים יכול להיות משמעותי עבורו, זאת לא סיבה לכפות עליו להשתתף."},{"id":"article-paragraph-94067cd17a18","heading":"חשוב לזכור - הדיירים הם אנשים בעלי רצונות ודעות משלהם","text":"אדם יכול לא לרצות להשתתף מסיבות רבות. אולי הוא עייף, אולי כואב לו משהו, אולי הוא לא אוהב כלבים, ואולי פשוט לא מתחשק לו."},{"id":"article-paragraph-fc5ff77fc0b8","heading":"חשוב לזכור - הדיירים הם אנשים בעלי רצונות ודעות משלהם","text":"גם אדם עם דמנציה יכול להביע רצון, התנגדות והעדפות, וחשוב להתייחס אליהן ברצינות."},{"id":"article-paragraph-5f9290799c5e","heading":"חשוב לזכור - הדיירים הם אנשים בעלי רצונות ודעות משלהם","text":"אפשר להזמין, להציע, להסביר ולהתאים את הפעילות, אבל צריך גם לדעת לקבל תשובה שלילית."},{"id":"article-paragraph-c5bfd4f13d86","heading":"חשוב לזכור - הדיירים הם אנשים בעלי רצונות ודעות משלהם","text":"המטרה היא לא לגרום לכמה שיותר דיירים להשתתף, אלא לאפשר למי שמעוניין בכך להשתתף בדרך שמתאימה לו."},{"id":"article-heading-1619cc040082","heading":"חזרתיות היא לא בהכרח חיסרון - היא יכולה להיות בדיוק מה שצריך","text":"חזרתיות היא לא בהכרח חיסרון - היא יכולה להיות בדיוק מה שצריך"},{"id":"article-paragraph-b1fa04e38bd5","heading":"חזרתיות היא לא בהכרח חיסרון - היא יכולה להיות בדיוק מה שצריך","text":"אחד הדברים שיכולים להיות מאתגרים עבור המטפל בעבודה עם האוכלוסייה הזאת הוא החזרתיות."},{"id":"article-paragraph-33f9ceb1b313","heading":"חזרתיות היא לא בהכרח חיסרון - היא יכולה להיות בדיוק מה שצריך","text":"אנחנו רגילים לחשוב שבכל מפגש צריך להביא פעילות חדשה, לחדש, לגוון וליצור עניין."},{"id":"article-paragraph-26de004b024d","heading":"חזרתיות היא לא בהכרח חיסרון - היא יכולה להיות בדיוק מה שצריך","text":"אבל במחלקות סיעודיות, ובמיוחד בעבודה עם אנשים שמתמודדים עם דמנציה וקשיי זיכרון, גיליתי שדווקא החזרה על אותן פעילויות יכולה להיות משמעותית מאוד."},{"id":"article-paragraph-9746ce5f405e","heading":"חזרתיות היא לא בהכרח חיסרון - היא יכולה להיות בדיוק מה שצריך","text":"כשאנחנו חוזרים על אותה משימה, חלק מהדיירים מתחילים לזהות אותה, להכיר את רצף הפעולות ולדעת מה מצופה מהם."},{"id":"article-paragraph-32d1266fb556","heading":"חזרתיות היא לא בהכרח חיסרון - היא יכולה להיות בדיוק מה שצריך","text":"בהדרגה הם עשויים לדעת מה לעשות כשהכלב מגיע, איך להחזיק את האביזר או איזו תנועה לבצע."},{"id":"article-paragraph-06d03eed0b82","heading":"חזרתיות היא לא בהכרח חיסרון - היא יכולה להיות בדיוק מה שצריך","text":"זה יכול לתת להם תחושה של היכרות, ביטחון ושליטה."},{"id":"article-paragraph-a4e7cc8e739c","heading":"חזרתיות היא לא בהכרח חיסרון - היא יכולה להיות בדיוק מה שצריך","text":"חשוב להבחין בין סוגי הזיכרון השונים. גם כשיש פגיעה משמעותית ביכולת לזכור מידע חדש או אירועים שהתרחשו לאחרונה, לעיתים נותרת יכולת מסוימת ללמוד דרך חזרתיות ולהיעזר בזיכרון של הרגלים ופעולות מוכרות."},{"id":"article-paragraph-3b865e5c3ce4","heading":"חזרתיות היא לא בהכרח חיסרון - היא יכולה להיות בדיוק מה שצריך","text":"לכן החזרתיות לא הייתה רק משהו שצריך לקבל או להשלים איתו."},{"id":"article-paragraph-a47d7b42ed11","heading":"חזרתיות היא לא בהכרח חיסרון - היא יכולה להיות בדיוק מה שצריך","text":"היא הייתה חלק מהדרך שבה התאמתי את הפעילות לקשיים הקוגניטיביים של הדיירים."},{"id":"article-paragraph-12544a28087d","heading":"חזרתיות היא לא בהכרח חיסרון - היא יכולה להיות בדיוק מה שצריך","text":"מה שעבורי יכול היה להרגיש כמו עוד פעם של אותה פעילות, עבור הדייר היה הזדמנות נוספת להרגיש שהוא מכיר, יודע ומצליח."},{"id":"article-heading-8b9fc136bedc","heading":"מה חשוב לדעת על דמנציה?","text":"מה חשוב לדעת על דמנציה?"},{"id":"article-paragraph-66ed4c639336","heading":"מה חשוב לדעת על דמנציה?","text":"דמנציה היא תסמונת שמתבטאת בירידה בתפקודים קוגניטיביים, כמו זיכרון, שפה, התמצאות, קשב ושיפוט, עד כדי פגיעה בתפקוד היום-יומי."},{"id":"article-paragraph-2fcb27cc8740","heading":"מה חשוב לדעת על דמנציה?","text":"מחלת אלצהיימר היא אחד הגורמים השכיחים לדמנציה, אבל קיימים גם סוגים נוספים."},{"id":"article-paragraph-360a5dcec39e","heading":"מה חשוב לדעת על דמנציה?","text":"חשוב להבין שדמנציה אינה חלק בלתי נמנע מההזדקנות. לא כל אדם מבוגר מתמודד עם דמנציה, ולא כל אדם שמתמודד איתה יחווה את אותם התסמינים."},{"id":"article-paragraph-17d16f42e218","heading":"מה חשוב לדעת על דמנציה?","text":"אצל אנשים רבים עם דמנציה נפגעת במיוחד היכולת לזכור אירועים שהתרחשו לאחרונה."},{"id":"article-paragraph-e7fea00d4d16","heading":"מה חשוב לדעת על דמנציה?","text":"לכן אדם יכול לזכור סיפורים מלפני עשרות שנים, ובו בזמן לא לזכור מי האדם שהציג את עצמו בפניו לפני כמה דקות."},{"id":"article-paragraph-b635ba833238","heading":"מה חשוב לדעת על דמנציה?","text":"וזה מחייב אותנו להתאים גם את הדרך שבה אנחנו מתקשרים איתו."},{"id":"article-heading-1f11fb65fb00","heading":"לא לשאול \"אתה זוכר אותי?\"","text":"לא לשאול \"אתה זוכר אותי?\""},{"id":"article-paragraph-0843282fcaf8","heading":"מה חשוב לדעת על דמנציה?","text":"אחת ההמלצות המקצועיות בעבודה עם אנשים עם דמנציה היא להימנע ממבחני זיכרון לא נחוצים."},{"id":"article-paragraph-daf1312196a6","heading":"מה חשוב לדעת על דמנציה?","text":"מתוך כוונה טובה אנחנו עלולים לשאול אדם: \"אתה זוכר איך קוראים לי?\", \"אתה זוכר איך קוראים לכלב?\" או \"אתה זוכר מה עשינו במפגש הקודם?\"."},{"id":"article-paragraph-8b01d2ec457a","heading":"מה חשוב לדעת על דמנציה?","text":"אבל עבור אדם שמתקשה לזכור, השאלות האלה עלולות לעורר מבוכה, תסכול או תחושת כישלון."},{"id":"article-paragraph-6b47a8e11c98","heading":"מה חשוב לדעת על דמנציה?","text":"לכן הייתי מקפיד להציג את עצמי ואת הכלבים מחדש, גם אם נפגשנו פעמים רבות."},{"id":"article-paragraph-77772c2a486f","heading":"מה חשוב לדעת על דמנציה?","text":"\"שלום, אני יוני. היום הגעתי עם ליאו ולוגאן, ובאנו לעשות קצת פעילות ביחד.\""},{"id":"article-paragraph-59e7b05c805f","heading":"מה חשוב לדעת על דמנציה?","text":"הייתי חוזר על ההיכרות גם במהלך המפגש, כשזיהיתי שמישהו אינו זוכר מי אני או מה אנחנו עושים."},{"id":"article-paragraph-9f367753c342","heading":"מה חשוב לדעת על דמנציה?","text":"לא הייתה סיבה לצפות מהדיירים לזכור אותי רק מפני שכבר נפגשנו."},{"id":"article-heading-c85386da1c2f","heading":"לזכור את האדם גם כשהוא לא זוכר אותך","text":"לזכור את האדם גם כשהוא לא זוכר אותך"},{"id":"article-paragraph-07178858c75c","heading":"לזכור את האדם גם כשהוא לא זוכר אותך","text":"אחד הדברים שגיליתי שהם משמעותיים מאוד בעבודה הזאת היה דווקא ההיכרות האישית שלי עם הדיירים."},{"id":"article-paragraph-0b290e65ba17","heading":"לזכור את האדם גם כשהוא לא זוכר אותך","text":"הייתי משתדל לזכור את השמות שלהם, את המשפחות שלהם, את הילדים, את הדברים שסיפרו לי ואת האירועים המשמעותיים בחייהם."},{"id":"article-paragraph-502fbdeb287a","heading":"לזכור את האדם גם כשהוא לא זוכר אותך","text":"הייתי פונה לדייר בשמו והוא היה מסתכל עליי בהפתעה ושואל: \"איך אתה יודע איך קוראים לי?\""},{"id":"article-paragraph-dc97e7a6a793","heading":"לזכור את האדם גם כשהוא לא זוכר אותך","text":"גם כשאותו אדם לא זכר אותי מהמפגש הקודם, העובדה שאני זכרתי אותו הייתה משמעותית."},{"id":"article-paragraph-951722bc0ddf","heading":"לזכור את האדם גם כשהוא לא זוכר אותך","text":"זה היה חלק מרכזי מהקשר."},{"id":"article-paragraph-9ee4cc3c1303","heading":"לזכור את האדם גם כשהוא לא זוכר אותך","text":"לא רציתי להתייחס לאנשים רק לפי מצבם הסיעודי, היכולת הקוגניטיבית או המגבלות הגופניות שלהם."},{"id":"article-paragraph-3c818e1295cb","heading":"לזכור את האדם גם כשהוא לא זוכר אותך","text":"רציתי להכיר את האדם שמאחורי כל אלה."},{"id":"article-heading-7d6440141f14","heading":"אלוף הארץ בג'ודו","text":"אלוף הארץ בג'ודו"},{"id":"article-paragraph-a6b8ae353716","heading":"לזכור את האדם גם כשהוא לא זוכר אותך","text":"היה לי דייר שבעברו היה אלוף הארץ בג'ודו."},{"id":"article-paragraph-0c7e731d0b95","heading":"לזכור את האדם גם כשהוא לא זוכר אותך","text":"במהלך הפעילויות שבהן ביקשתי ממנו לזרוק משחק לכלב, הייתי מזכיר לו את זה."},{"id":"article-paragraph-9e4f91d9fe24","heading":"לזכור את האדם גם כשהוא לא זוכר אותך","text":"הייתי אומר לו משהו בסגנון: \"בוא נראה זריקה של אלוף הארץ בג'ודו\"."},{"id":"article-paragraph-637bdd4a4399","heading":"לזכור את האדם גם כשהוא לא זוכר אותך","text":"ובכל פעם כזאת הוא היה מתאמץ הרבה יותר."},{"id":"article-paragraph-4d63c696b5b0","heading":"לזכור את האדם גם כשהוא לא זוכר אותך","text":"הוא היה זורק מכל הלב, משקיע ומנסה להצליח."},{"id":"article-paragraph-4cd5fe05caa4","heading":"לזכור את האדם גם כשהוא לא זוכר אותך","text":"הדוגמה הזאת ממחישה עד כמה חשוב להכיר את האדם שמולנו."},{"id":"article-paragraph-726d209c4b6e","heading":"לזכור את האדם גם כשהוא לא זוכר אותך","text":"הדרך לעודד תנועה לא תמיד עוברת דרך בקשה נוספת להרים את היד או להתאמץ, אלא דרך חיבור למשהו שיש לו משמעות עבורו."},{"id":"article-paragraph-555d031a4abe","heading":"לזכור את האדם גם כשהוא לא זוכר אותך","text":"הוא לא היה רק אדם מבוגר בכיסא גלגלים."},{"id":"article-paragraph-8197174cf92b","heading":"לזכור את האדם גם כשהוא לא זוכר אותך","text":"הוא היה גם אדם עם עבר, עם הישגים, עם גאווה ועם סיפור חיים."},{"id":"article-heading-b99b5862343d","heading":"לשמוע את אותו הסיפור חמש פעמים במפגש","text":"לשמוע את אותו הסיפור חמש פעמים במפגש"},{"id":"article-paragraph-80711253a821","heading":"לשמוע את אותו הסיפור חמש פעמים במפגש","text":"אחד הדברים שפגשתי הרבה בעבודה במחלקות הסיעודיות היה החזרתיות בשיחות."},{"id":"article-paragraph-cebdb2c0a5e7","heading":"לשמוע את אותו הסיפור חמש פעמים במפגש","text":"הייתי עובר בין הדיירים, ובכל פעם שהייתי חוזר לאותו אדם, הוא היה שואל שוב את אותה השאלה או מספר מחדש את אותו הסיפור."},{"id":"article-paragraph-b6120ada82d5","heading":"לשמוע את אותו הסיפור חמש פעמים במפגש","text":"הייתה למשל דיירת מתוקה שכמעט בכל סבב הייתה שואלת אותי אם אני נשוי ואם יש לי ילדים."},{"id":"article-paragraph-05f1a91c5336","heading":"לשמוע את אותו הסיפור חמש פעמים במפגש","text":"בכל פעם הייתי עונה מחדש."},{"id":"article-paragraph-8899f40a00ef","heading":"לשמוע את אותו הסיפור חמש פעמים במפגש","text":"הייתי מספר לה שאני נשוי ויש לי שני ילדים, ואז שואל גם אותה על המשפחה שלה."},{"id":"article-paragraph-8e12fcfe4860","heading":"לשמוע את אותו הסיפור חמש פעמים במפגש","text":"היא הייתה מספרת לי על הילדים שלה ועל הבן שלה שיש לו כלבים."},{"id":"article-paragraph-1717811c9adf","heading":"לשמוע את אותו הסיפור חמש פעמים במפגש","text":"היו מפגשים שבהם שמעתי את אותו הסיפור ארבע או חמש פעמים."},{"id":"article-paragraph-0344b1bf802d","heading":"לשמוע את אותו הסיפור חמש פעמים במפגש","text":"בכל פעם מחדש הייתי מקשיב, מתעניין ומגיב לסיפור שלה באותה ההתלהבות."},{"id":"article-paragraph-8793ca580f1c","heading":"לשמוע את אותו הסיפור חמש פעמים במפגש","text":"זאת אולי הייתה הפעם החמישית ששמעתי את הסיפור, אבל עבורה זאת יכולה הייתה להיות הפעם הראשונה שהיא מספרת לי אותו."},{"id":"article-paragraph-26564ee2f21e","heading":"לשמוע את אותו הסיפור חמש פעמים במפגש","text":"העובדה שאני כבר מכיר את הסיפור לא הופכת את השיחה לפחות משמעותית עבורה."},{"id":"article-heading-84dc40490227","heading":"איך נכון לתקשר עם אנשים עם דמנציה?","text":"איך נכון לתקשר עם אנשים עם דמנציה?"},{"id":"article-paragraph-40603a75730e","heading":"איך נכון לתקשר עם אנשים עם דמנציה?","text":"יש כמה עקרונות מקצועיים שחשוב להכיר בעבודה עם אנשים עם דמנציה."},{"id":"article-paragraph-bbcd2618e5e0","heading":"איך נכון לתקשר עם אנשים עם דמנציה?","text":"ראשית, חשוב לפנות לאדם בגובה העיניים ובצורה מכבדת. לדבר אליו ישירות, לקרוא לו בשמו ולא להתייחס אליו כאילו הוא ילד רק מפני שהוא זקוק לעזרה."},{"id":"article-paragraph-cbc5fb6a1d32","heading":"איך נכון לתקשר עם אנשים עם דמנציה?","text":"כדאי להשתמש במשפטים קצרים וברורים, לתת הוראה אחת בכל פעם ולהדגים פעולות כשהדבר יכול לעזור."},{"id":"article-paragraph-1924dcb54897","heading":"איך נכון לתקשר עם אנשים עם דמנציה?","text":"חשוב גם לתת זמן לתגובה. לאדם יכול לקחת יותר זמן להבין שאלה, למצוא מילה או להחליט מה הוא רוצה לעשות."},{"id":"article-paragraph-9e9a15381605","heading":"איך נכון לתקשר עם אנשים עם דמנציה?","text":"במקום לשאול שאלות רחבות מדי, אפשר להציע אפשרויות פשוטות. למשל, \"את רוצה ללטף את הכלב או לזרוק לו כדור?\""},{"id":"article-paragraph-b7adf6b5f565","heading":"איך נכון לתקשר עם אנשים עם דמנציה?","text":"כפי שתיארתי קודם, כדאי להימנע משאלות שבודקות זיכרון ללא צורך."},{"id":"article-paragraph-e39b160c466f","heading":"איך נכון לתקשר עם אנשים עם דמנציה?","text":"גם כאשר אדם חוזר על אותו סיפור או אומר משהו שאינו תואם את המציאות, לא תמיד צריך למהר לתקן אותו."},{"id":"article-paragraph-353a65d9eb6e","heading":"איך נכון לתקשר עם אנשים עם דמנציה?","text":"חשוב יותר לנסות להבין את מה שהוא מבקש להביע ולשמור על הקשר."},{"id":"article-paragraph-186d28fa1d69","heading":"איך נכון לתקשר עם אנשים עם דמנציה?","text":"אם אדם מספר על אירוע מהעבר, אפשר להתעניין ולשאול עליו, בלי להפוך את השיחה לבחינה של דיוק העובדות."},{"id":"article-paragraph-4fdcbf67e7cb","heading":"איך נכון לתקשר עם אנשים עם דמנציה?","text":"וכשיש חוסר שקט או שאלה שחוזרת על עצמה, כדאי לחשוב גם על הצורך שעומד מאחוריה. החזרה עשויה לנבוע משכחה, אבל גם מחיפוש אחר ביטחון, קשר או הרגעה."},{"id":"article-paragraph-93df5387ab67","heading":"איך נכון לתקשר עם אנשים עם דמנציה?","text":"המטרה היא לא להתעלם מהקשיים הקוגניטיביים, אלא להתאים את התקשורת כך שלא נהפוך אותם למקור נוסף של תסכול."},{"id":"article-heading-994b5add2709","heading":"ההומור והצחוק הם חלק מהעבודה","text":"ההומור והצחוק הם חלק מהעבודה"},{"id":"article-paragraph-33385eeda9de","heading":"ההומור והצחוק הם חלק מהעבודה","text":"אחד הדברים שאני הכי זוכר מהעבודה הזאת הוא הצחוק."},{"id":"article-paragraph-d3a5cf732a24","heading":"ההומור והצחוק הם חלק מהעבודה","text":"היו הרבה רגעים שבהם היינו צוחקים יחד, מספרים בדיחות או מתבדחים תוך כדי הפעילות עם הכלבים."},{"id":"article-paragraph-1dde951817ea","heading":"ההומור והצחוק הם חלק מהעבודה","text":"הבדיחה הייתה יכולה להיות קשורה לכלב, למשהו שהדייר אמר או לסיפור אישי שכבר הכרתי."},{"id":"article-paragraph-8c197c7181ea","heading":"ההומור והצחוק הם חלק מהעבודה","text":"ההומור לא היה רק משהו שמוסיף אווירה טובה למפגש."},{"id":"article-paragraph-dd645b694bef","heading":"ההומור והצחוק הם חלק מהעבודה","text":"הוא היה חלק מהקשר."},{"id":"article-paragraph-cee9c06c4ca9","heading":"ההומור והצחוק הם חלק מהעבודה","text":"הוא אפשר ליצור חוויה נעימה, להקל על המתח ולהרגיש שיש במפגש משהו שהוא הרבה מעבר לתרגול של תנועה או הפעלה."},{"id":"article-heading-04b5158beb0a","heading":"הכלבים יכולים לפתוח גם שיחות על הזדקנות","text":"הכלבים יכולים לפתוח גם שיחות על הזדקנות"},{"id":"article-paragraph-237b7624ec71","heading":"הכלבים יכולים לפתוח גם שיחות על הזדקנות","text":"גם השינויים בגיל וביכולת של הכלבים עצמם אפשרו שיחות מעניינות."},{"id":"article-paragraph-3a7765f6e7b8","heading":"הכלבים יכולים לפתוח גם שיחות על הזדקנות","text":"הייתי מגיע עם כלב מבוגר וכלב צעיר, ובפעילויות מסוימות הייתי מסביר לדיירים שאנחנו צריכים להתאים את המשימה לכלב המבוגר."},{"id":"article-paragraph-eb5e1a421ba0","heading":"הכלבים יכולים לפתוח גם שיחות על הזדקנות","text":"למשל, כשעבדנו עם חישוק, הייתי מסביר שלא נבקש מהכלב המבוגר לקפוץ לגובה, אלא נוריד את החישוק כדי שיוכל לעבור דרכו בנוחות."},{"id":"article-paragraph-eee0bbbf7ca6","heading":"הכלבים יכולים לפתוח גם שיחות על הזדקנות","text":"משם הייתה יכולה להתפתח שיחה על הגיל ועל השינויים ביכולות שלנו."},{"id":"article-paragraph-e7ba617b6e4b","heading":"הכלבים יכולים לפתוח גם שיחות על הזדקנות","text":"זה היה קורה בצורה טבעית, מתוך הפעילות עצמה."},{"id":"article-paragraph-1e52ecf149c5","heading":"הכלבים יכולים לפתוח גם שיחות על הזדקנות","text":"לא הייתי צריך להכין שיעור על הזדקנות או לנסות להוביל את הדיירים לשיחה רגשית מורכבת."},{"id":"article-paragraph-da84005d1042","heading":"הכלבים יכולים לפתוח גם שיחות על הזדקנות","text":"הסיטואציה אפשרה לנו לדבר על משהו שהם מכירים מחייהם."},{"id":"article-heading-02ae35f524c9","heading":"לא כולם אוהבים כלבים - וחשוב לכבד גם את זה","text":"לא כולם אוהבים כלבים - וחשוב לכבד גם את זה"},{"id":"article-paragraph-2b1c822fbdfd","heading":"לא כולם אוהבים כלבים - וחשוב לכבד גם את זה","text":"לצד הרגעים החיוביים, היו גם התנגדויות לא פשוטות."},{"id":"article-paragraph-9e207de2261c","heading":"לא כולם אוהבים כלבים - וחשוב לכבד גם את זה","text":"אחד הדברים שצריך לזכור כשמגיעים עם כלבים למחלקה סיעודית הוא שלא כל אדם אוהב כלבים, ולא לכל אדם יש חוויות חיוביות שקשורות אליהם."},{"id":"article-paragraph-4823086db0f7","heading":"לא כולם אוהבים כלבים - וחשוב לכבד גם את זה","text":"במיוחד בעבודה עם אנשים מבוגרים בישראל, אנחנו עשויים לפגוש גם אנשים שחוו טראומות קשות במהלך חייהם."},{"id":"article-paragraph-5c5eec0f1aaf","heading":"לא כולם אוהבים כלבים - וחשוב לכבד גם את זה","text":"היו מקרים שבהם דיירים הגיבו לנוכחות הכלבים מתוך זיכרונות טראומטיים מתקופת השואה."},{"id":"article-paragraph-01162feccb76","heading":"לא כולם אוהבים כלבים - וחשוב לכבד גם את זה","text":"אדם יכול היה לצעוק לעברי שהנאצים השתמשו בכלבים, לספר שכלבים רדפו אחריו בעבר, ואפילו לכנות אותי נאצי."},{"id":"article-paragraph-1230ef2db7f7","heading":"לא כולם אוהבים כלבים - וחשוב לכבד גם את זה","text":"היו גם דיירים שהתנגדו לנוכחות הכלבים מסיבות דתיות או אישיות."},{"id":"article-paragraph-4ee169a8d9b6","heading":"לא כולם אוהבים כלבים - וחשוב לכבד גם את זה","text":"למשל, מישהו שאמר שאסור להכניס כלבים למקום שבו הוא גר, או שאל אותי איך אני, כאדם דתי, מגיע עם כלבים."},{"id":"article-paragraph-540a2fd70250","heading":"לא כולם אוהבים כלבים - וחשוב לכבד גם את זה","text":"אלה לא תמיד תגובות שקל לשמוע."},{"id":"article-paragraph-8d42b24a0a50","heading":"לא כולם אוהבים כלבים - וחשוב לכבד גם את זה","text":"אבל חשוב להבין שהכלב לא בהכרח מעורר אצל כולם תחושות חיוביות. עבור אדם מסוים הוא יכול להיות מקור לשמחה, ועבור אחר דווקא מקור לפחד, לזיכרון קשה או לתחושת חדירה למרחב הפרטי."},{"id":"article-paragraph-fbdd15d0aa3b","heading":"לא כולם אוהבים כלבים - וחשוב לכבד גם את זה","text":"בעבודה הזאת חשוב מאוד לכבד את רצון הדיירים ולאפשר להם לבחור אם להשתתף."},{"id":"article-paragraph-41d16a35e541","heading":"לא כולם אוהבים כלבים - וחשוב לכבד גם את זה","text":"במיוחד כשמדובר בטראומה, אין מקום לכפות מפגש עם כלב או להפוך את הפעילות לחשיפה שאינה מתוכננת ומותאמת."},{"id":"article-heading-e8d8d86d3edb","heading":"אתגר נוסף - אוכל בסביבת המחלקה","text":"אתגר נוסף - אוכל בסביבת המחלקה"},{"id":"article-paragraph-5fe606514331","heading":"אתגר נוסף - אוכל בסביבת המחלקה","text":"אחד הקשיים המעשיים בעבודה במחלקות סיעודיות קשור דווקא לאוכל."},{"id":"article-paragraph-dc35c748ae36","heading":"אתגר נוסף - אוכל בסביבת המחלקה","text":"במחלקות כאלה יש לא מעט מצבים שבהם נשאר אוכל על הרצפה, על כיסאות הגלגלים או על הבגדים והידיים של הדיירים."},{"id":"article-paragraph-d12d65b83a78","heading":"אתגר נוסף - אוכל בסביבת המחלקה","text":"כשמגיעים עם כלבים שאוהבים מאוד אוכל, כמו הכלבים שלי, צריך להיות ערניים במיוחד."},{"id":"article-paragraph-f92626fe8bdc","heading":"אתגר נוסף - אוכל בסביבת המחלקה","text":"כלב שמריח אוכל יכול לנסות להתקרב אליו, לאסוף שאריות מהרצפה או לחפש מזון ליד הדיירים."},{"id":"article-paragraph-0fd557e350b8","heading":"אתגר נוסף - אוכל בסביבת המחלקה","text":"הדבר עלול להסיח את דעתו מהפעילות, ליצור אי־נוחות אצל הדיירים ואף לסכן אותם ואת הכלב."},{"id":"article-paragraph-042210a8273a","heading":"אתגר נוסף - אוכל בסביבת המחלקה","text":"צריך לזכור שלא כל מזון של בני אדם מתאים לכלבים, וחלק מהמזונות עלולים להיות מסוכנים עבורם."},{"id":"article-paragraph-62c3ac86c7ea","heading":"אתגר נוסף - אוכל בסביבת המחלקה","text":"לכן, לפני שמתחילים את הפעילות חשוב לבדוק את הסביבה, לוודא שאין מזון נגיש שעלול למשוך את הכלב ולתכנן היטב את הפעילויות שכוללות חטיפים."},{"id":"article-paragraph-6d657d01a052","heading":"אתגר נוסף - אוכל בסביבת המחלקה","text":"צריך גם להקפיד שהכלב לא ינסה לקחת אוכל מהידיים, מהבגדים או מסביבת כיסא הגלגלים של הדייר."},{"id":"article-paragraph-67584ffe3416","heading":"אתגר נוסף - אוכל בסביבת המחלקה","text":"ככל האפשר, כדאי לתאם מראש עם הצוות שהפעילות תתקיים בסביבה מסודרת ונקייה משאריות מזון, ולוודא שהכלבים יודעים להתעלם מאוכל שלא מיועד להם."},{"id":"article-paragraph-372ad7936d90","heading":"אתגר נוסף - אוכל בסביבת המחלקה","text":"הכלב צריך להיות קשוב למטפל ולפעילות, ולא עסוק בחיפוש אחר אוכל במחלקה."},{"id":"article-paragraph-0274113e2329","heading":"אתגר נוסף - אוכל בסביבת המחלקה","text":"זה אולי נשמע כמו פרט טכני קטן, אבל בשטח הוא יכול להשפיע מאוד על הבטיחות ועל אופן ההתנהלות של המפגש."},{"id":"article-heading-13d8993ee09d","heading":"המפגש עם בדידות, כאב ותחושת חוסר משמעות","text":"המפגש עם בדידות, כאב ותחושת חוסר משמעות"},{"id":"article-paragraph-a69ab52cc07d","heading":"המפגש עם בדידות, כאב ותחושת חוסר משמעות","text":"העבודה במחלקות סיעודיות חושפת אותנו גם למצבים רגשיים לא פשוטים."},{"id":"article-paragraph-fd23d27ef568","heading":"המפגש עם בדידות, כאב ותחושת חוסר משמעות","text":"פגשתי אנשים שהתמודדו עם בדידות, עצב ותחושה שהם כבר לא משמעותיים כפי שהיו בעבר."},{"id":"article-paragraph-269fa8b5d8e4","heading":"המפגש עם בדידות, כאב ותחושת חוסר משמעות","text":"שמעתי גם אמירות כמו \"אין לי בשביל מה לחיות\" או \"אני רוצה למות\"."},{"id":"article-paragraph-081773856a17","heading":"המפגש עם בדידות, כאב ותחושת חוסר משמעות","text":"אלה אמירות שלא קל לשמוע."},{"id":"article-paragraph-5761f2e490f8","heading":"המפגש עם בדידות, כאב ותחושת חוסר משמעות","text":"בעבודה כזאת חשוב להיות מסוגלים להקשיב לכאב בלי למהר לבטל אותו או לנסות לשכנע את האדם שהוא צריך להרגיש אחרת."},{"id":"article-paragraph-59a72c1d698f","heading":"המפגש עם בדידות, כאב ותחושת חוסר משמעות","text":"אבל חשוב גם לקחת אמירות כאלה ברצינות. רצון למות יכול לבטא מצוקה קיומית, כאב או ייאוש, ולעיתים גם סיכון אובדני שמצריך בירור מקצועי."},{"id":"article-paragraph-924e9e3107cf","heading":"המפגש עם בדידות, כאב ותחושת חוסר משמעות","text":"לכן לא נכון להסתפק בניסיון לעודד את הדייר באמצעות הכלב או להסיח את דעתו."},{"id":"article-paragraph-6be182b181d6","heading":"המפגש עם בדידות, כאב ותחושת חוסר משמעות","text":"כשעולות אמירות כאלה, חשוב לפנות לצוות המקצועי ולפעול בהתאם לנהלים ולהערכת הסיכון."},{"id":"article-paragraph-b67c7795bdfe","heading":"המפגש עם בדידות, כאב ותחושת חוסר משמעות","text":"הכלבנות הטיפולית יכולה להציע רגעים של קשר, עניין והנאה, אבל היא אינה מחליפה מענה מקצועי למצוקה נפשית משמעותית."},{"id":"article-heading-4b6551ddd27f","heading":"לראות אנשים הולכים ומידרדרים","text":"לראות אנשים הולכים ומידרדרים"},{"id":"article-paragraph-f77cd6bd296f","heading":"לראות אנשים הולכים ומידרדרים","text":"אחד הקשיים בעבודה ממושכת במחלקות סיעודיות הוא לראות את השינויים שחלים באנשים לאורך הזמן."},{"id":"article-paragraph-5eccf5186fa5","heading":"לראות אנשים הולכים ומידרדרים","text":"אתה מכיר אדם כשהוא עדיין פעיל יחסית, מדבר, צוחק ומשתתף."},{"id":"article-paragraph-ce22e548fdb2","heading":"לראות אנשים הולכים ומידרדרים","text":"ואז, לאורך שבועות או חודשים, אתה מתחיל לראות ירידה ביכולות שלו."},{"id":"article-paragraph-49914a6e3a6e","heading":"לראות אנשים הולכים ומידרדרים","text":"הוא מתקשה יותר לנוע, פחות משתתף בשיחות, מתעייף מהר יותר או כבר לא מצליח לבצע דברים שקודם היו פשוטים עבורו."},{"id":"article-paragraph-99ca0e12775c","heading":"לראות אנשים הולכים ומידרדרים","text":"יש משהו לא פשוט במפגש המתמשך עם התהליכים האלה."},{"id":"article-paragraph-72d243c97ce3","heading":"לראות אנשים הולכים ומידרדרים","text":"בעבודה טיפולית אנחנו רגילים לחשוב על התקדמות, על רכישת מיומנויות ועל שיפור בתפקוד."},{"id":"article-paragraph-ed60497489ba","heading":"לראות אנשים הולכים ומידרדרים","text":"אבל בעבודה עם אנשים מבוגרים וסיעודיים, לא תמיד זאת המציאות."},{"id":"article-paragraph-b919a76f39d4","heading":"לראות אנשים הולכים ומידרדרים","text":"לעיתים ההצלחה היא לא לשפר יכולת, אלא לשמר אותה ככל האפשר."},{"id":"article-paragraph-d193d7680800","heading":"לראות אנשים הולכים ומידרדרים","text":"ובמקרים אחרים המטרה היא פשוט לאפשר לאדם להשתתף, ליהנות ולחוות קשר גם כשהיכולות שלו הולכות ופוחתות."},{"id":"article-heading-d960b2ab81f4","heading":"הקושי הגדול ביותר - להיפרד מאנשים שנקשרת אליהם","text":"הקושי הגדול ביותר - להיפרד מאנשים שנקשרת אליהם"},{"id":"article-paragraph-087e8a0ecaee","heading":"הקושי הגדול ביותר - להיפרד מאנשים שנקשרת אליהם","text":"מכל הקשיים שפגשתי בעבודה הזאת, אחד המשמעותיים ביותר עבורי היה האובדן."},{"id":"article-paragraph-1cfd6f572d94","heading":"הקושי הגדול ביותר - להיפרד מאנשים שנקשרת אליהם","text":"כשעובדים עם אותם אנשים לאורך זמן, נוצרים קשרים אישיים."},{"id":"article-paragraph-6b653a45486b","heading":"הקושי הגדול ביותר - להיפרד מאנשים שנקשרת אליהם","text":"אתה מכיר אותם, מחכה לפגוש אותם, זוכר את הסיפורים שלהם, צוחק איתם ודואג להם."},{"id":"article-paragraph-b5029fccd389","heading":"הקושי הגדול ביותר - להיפרד מאנשים שנקשרת אליהם","text":"והמשמעות היא שגם כשמישהו מהם נפטר, זה יכול להיות אובדן כואב מאוד."},{"id":"article-paragraph-8e36969e2e4b","heading":"הקושי הגדול ביותר - להיפרד מאנשים שנקשרת אליהם","text":"היה דייר שהייתי קשור אליו במיוחד."},{"id":"article-paragraph-57b53b2cd722","heading":"הקושי הגדול ביותר - להיפרד מאנשים שנקשרת אליהם","text":"הוא היה אחד האנשים הפעילים ביותר בקבוצה. הוא היה מצחיק את כולם, יוזם שיחות, מכיר את שאר הדיירים ודואג להם."},{"id":"article-paragraph-9c467405eea4","heading":"הקושי הגדול ביותר - להיפרד מאנשים שנקשרת אליהם","text":"גם מבחינה גופנית וקוגניטיבית הוא היה בין הדיירים שתפקדו טוב יותר."},{"id":"article-paragraph-d44e75205500","heading":"הקושי הגדול ביותר - להיפרד מאנשים שנקשרת אליהם","text":"יום אחד הגעתי למחלקה ושאלתי את אחת העובדות איפה הוא, וביקשתי שיביאו אותו לפעילות."},{"id":"article-paragraph-04a772c379fa","heading":"הקושי הגדול ביותר - להיפרד מאנשים שנקשרת אליהם","text":"בדרך כלל היו מעדכנים אותנו מראש כשדייר נפטר, אבל במקרה הזה לא קיבלתי עדכון."},{"id":"article-paragraph-b0a903b5d2f8","heading":"הקושי הגדול ביותר - להיפרד מאנשים שנקשרת אליהם","text":"העובדת הסתכלה עליי ואמרה לי שהוא נפטר."},{"id":"article-paragraph-d4c783db07a1","heading":"הקושי הגדול ביותר - להיפרד מאנשים שנקשרת אליהם","text":"הייתי בהלם מוחלט."},{"id":"article-paragraph-0cb95d3c861d","heading":"הקושי הגדול ביותר - להיפרד מאנשים שנקשרת אליהם","text":"לא ציפיתי לזה, ובאותו רגע פשוט התחלתי לבכות."},{"id":"article-paragraph-e0f816b4e86e","heading":"הקושי הגדול ביותר - להיפרד מאנשים שנקשרת אליהם","text":"הייתי צריך להמשיך ולהעביר את הפעילות כשאני עדיין עם דמעות בעיניים."},{"id":"article-paragraph-0a426359b746","heading":"הקושי הגדול ביותר - להיפרד מאנשים שנקשרת אליהם","text":"אני חושב שזה אחד הדברים שהכי קשה להסביר למי שלא עבד לאורך זמן עם האוכלוסייה הזאת."},{"id":"article-paragraph-6e1125a1a919","heading":"הקושי הגדול ביותר - להיפרד מאנשים שנקשרת אליהם","text":"אנחנו מגיעים כדי לתת משהו לאנשים, אבל תוך כדי העבודה נוצרים גם קשרים משמעותיים עבורנו."},{"id":"article-paragraph-fff6fb6fe446","heading":"הקושי הגדול ביותר - להיפרד מאנשים שנקשרת אליהם","text":"וכשאדם שנקשרנו אליו נפטר, זה כואב."},{"id":"article-paragraph-3bfcc49ba7eb","heading":"הקושי הגדול ביותר - להיפרד מאנשים שנקשרת אליהם","text":"היכולת להתמודד עם האובדן היא חלק מהעבודה, אבל זה לא אומר שאנחנו צריכים להיות אדישים אליו."},{"id":"article-heading-93e71f0b80ee","heading":"למה העבודה הזאת יכולה להיות קשה גם למטפל?","text":"למה העבודה הזאת יכולה להיות קשה גם למטפל?"},{"id":"article-paragraph-370841bd75d1","heading":"למה העבודה הזאת יכולה להיות קשה גם למטפל?","text":"מעבר למצבים הרגשיים, יש בעבודה הזאת גם קושי שנובע מהאופי החזרתי שלה."},{"id":"article-paragraph-8eac55b47833","heading":"למה העבודה הזאת יכולה להיות קשה גם למטפל?","text":"אנחנו רגילים לבנות מפגשים חדשים, לנסות משחקים אחרים ולהרגיש שאנחנו כל הזמן מתקדמים למשהו נוסף."},{"id":"article-paragraph-0f0078dbdcee","heading":"למה העבודה הזאת יכולה להיות קשה גם למטפל?","text":"אבל כאן, הדבר הנכון יכול להיות לעשות כמעט את אותו הדבר בכל מפגש."},{"id":"article-paragraph-a28bbb71a5e8","heading":"למה העבודה הזאת יכולה להיות קשה גם למטפל?","text":"זה יכול להיות מאתגר עבור המטפל, במיוחד אם הוא רגיל לעבודה מגוונת מאוד."},{"id":"article-paragraph-3b00d680427d","heading":"למה העבודה הזאת יכולה להיות קשה גם למטפל?","text":"כשהשגרה חוזרת על עצמה, כשאנחנו נתקלים שוב ושוב באותם קשיים, וכשנוסף לכל אלה גם המפגש עם הידרדרות ואובדן, נדרשת יכולת רגשית לא פשוטה כדי להמשיך בעבודה הזאת לאורך זמן."},{"id":"article-paragraph-27e91afe751a","heading":"למה העבודה הזאת יכולה להיות קשה גם למטפל?","text":"יצא לי לראות אנשים שהגיעו לעבוד במסגרת הזאת ולא הצליחו להמשיך מעבר למפגש אחד או שניים."},{"id":"article-paragraph-a7fa54133e38","heading":"למה העבודה הזאת יכולה להיות קשה גם למטפל?","text":"אני יכול להבין את זה."},{"id":"article-paragraph-295108c496d6","heading":"למה העבודה הזאת יכולה להיות קשה גם למטפל?","text":"לא כל אחד מרגיש בנוח עם המראות, עם הכאב ועם המורכבות של העבודה הזאת."},{"id":"article-paragraph-45ae4ebac6f9","heading":"למה העבודה הזאת יכולה להיות קשה גם למטפל?","text":"אבל חשוב לי לחזור לנקודה שהתחלתי איתה: הפעילות לא אמורה לשרת את הצורך שלנו לחדש או להרגיש שאנחנו עושים משהו מיוחד."},{"id":"article-paragraph-c8a2dbde97f5","heading":"למה העבודה הזאת יכולה להיות קשה גם למטפל?","text":"היא אמורה לשרת את האנשים שעבורם אנחנו מגיעים."},{"id":"article-paragraph-24f8ee81d7f1","heading":"למה העבודה הזאת יכולה להיות קשה גם למטפל?","text":"אם החזרה על אותה פעילות מאפשרת לדייר להרגיש בטוח יותר, להשתתף ולחוות הצלחה, אז יש לה ערך, גם אם עבורנו היא כבר מוכרת מאוד."},{"id":"article-heading-c923a8087fdc","heading":"מה אומרים המחקרים על טיפול בעזרת בעלי חיים בגיל השלישי?","text":"מה אומרים המחקרים על טיפול בעזרת בעלי חיים בגיל השלישי?"},{"id":"article-paragraph-06479064299c","heading":"מה אומרים המחקרים על טיפול בעזרת בעלי חיים בגיל השלישי?","text":"בשנים האחרונות נערכו מחקרים רבים שבחנו התערבויות בעזרת בעלי חיים בקרב אנשים מבוגרים, ובפרט אנשים שמתמודדים עם דמנציה."},{"id":"article-paragraph-2fd9f8b9954c","heading":"מה אומרים המחקרים על טיפול בעזרת בעלי חיים בגיל השלישי?","text":"סקירה שיטתית ומטא-אנליזה שפורסמה בשנת 2026 בחנה 59 מחקרים על התערבויות בעזרת בעלי חיים באנשים עם דמנציה, מתוכם 24 מחקרים מבוקרים שכללו 1,881 משתתפים."},{"id":"article-paragraph-4831364d2b0a","heading":"מה אומרים המחקרים על טיפול בעזרת בעלי חיים בגיל השלישי?","text":"בניתוח הכמותי נמצאו שיפורים בתסמיני דיכאון ובמדדים מסוימים של תפקוד קוגניטיבי בקרב משתתפים בהתערבויות בעזרת בעלי חיים."},{"id":"article-paragraph-f63e589ce9d7","heading":"מה אומרים המחקרים על טיפול בעזרת בעלי חיים בגיל השלישי?","text":"סקירת-על נוספת שפורסמה בשנת 2026 בחנה 16 סקירות שיטתיות ומצאה תמיכה בהפחתת תסמיני דיכאון אצל אנשים עם דמנציה שהשתתפו בהתערבויות כאלה."},{"id":"article-paragraph-4610af9cefec","heading":"מה אומרים המחקרים על טיפול בעזרת בעלי חיים בגיל השלישי?","text":"הממצאים האלה מעניינים משום שהם מצביעים על האפשרות של בעלי חיים לתרום לרווחה הרגשית של אנשים עם דמנציה."},{"id":"article-paragraph-ee351dab39ca","heading":"מה אומרים המחקרים על טיפול בעזרת בעלי חיים בגיל השלישי?","text":"לצד המחקרים, חשוב להבין גם מה מתרחש בתוך המפגש עצמו."},{"id":"article-paragraph-f3f41e663016","heading":"מה אומרים המחקרים על טיפול בעזרת בעלי חיים בגיל השלישי?","text":"כשדייר מרים את היד כדי לזרוק כדור, כשהוא צוחק מבדיחה, כשהוא מספר על המשפחה שלו או כשהוא משתתף בפעילות משותפת עם דייר אחר - אלה רגעים שאפשר לזהות בהם השתתפות, קשר ועניין."},{"id":"article-paragraph-455b502434e9","heading":"מה אומרים המחקרים על טיפול בעזרת בעלי חיים בגיל השלישי?","text":"לא תמיד הם מעידים על שינוי קבוע בתפקוד, אבל הם יכולים להיות בעלי משמעות רבה עבור האדם באותו רגע."},{"id":"article-heading-6f233bbf6601","heading":"לא כל פעילות חייבת להיות מורכבת כדי להיות משמעותית","text":"לא כל פעילות חייבת להיות מורכבת כדי להיות משמעותית"},{"id":"article-paragraph-75e8b814a011","heading":"לא כל פעילות חייבת להיות מורכבת כדי להיות משמעותית","text":"אחד הדברים המרכזיים שלמדתי מהעבודה במחלקות הסיעודיות הוא שפעילות משמעותית לא חייבת להיות מורכבת."},{"id":"article-paragraph-2e8c086661c7","heading":"לא כל פעילות חייבת להיות מורכבת כדי להיות משמעותית","text":"היא יכולה להיות זריקת כדור פשוטה, סיבוב של היד, הברשה של כלב או שיחה ששמענו כבר עשרות פעמים."},{"id":"article-paragraph-f3d4138c166f","heading":"לא כל פעילות חייבת להיות מורכבת כדי להיות משמעותית","text":"השאלה היא לא כמה הפעילות מתוחכמת, אלא מה היא מאפשרת לאדם."},{"id":"article-paragraph-d34afb63c00f","heading":"לא כל פעילות חייבת להיות מורכבת כדי להיות משמעותית","text":"האם היא מעודדת אותו לנוע? האם היא יוצרת הזדמנות לדבר עם מישהו? האם היא מאפשרת לו להרגיש שהוא מסוגל לעשות משהו? האם היא מחברת אותו לזיכרון משמעותי מהחיים שלו? האם היא פשוט מאפשרת לו ליהנות ולצחוק?"},{"id":"article-paragraph-dd48fe1be37f","heading":"לא כל פעילות חייבת להיות מורכבת כדי להיות משמעותית","text":"אלה השאלות שהנחו אותי לאורך העבודה."},{"id":"article-heading-8a0b566aba17","heading":"לסיכום - לראות את האדם, לא רק את המגבלות שלו","text":"לסיכום - לראות את האדם, לא רק את המגבלות שלו"},{"id":"article-paragraph-d117cd4c7123","heading":"לסיכום - לראות את האדם, לא רק את המגבלות שלו","text":"העבודה עם כלבים במחלקות סיעודיות הייתה עבורי חוויה מקצועית ואישית משמעותית מאוד."},{"id":"article-paragraph-0b5ac34ddb31","heading":"לסיכום - לראות את האדם, לא רק את המגבלות שלו","text":"היא דרשה ממני ללמוד להתאים את הפעילויות למגבלות גופניות וקוגניטיביות, להיות סבלני לחזרתיות, להכיר את האנשים שמולי ולפעמים גם להתמודד עם מצבים רגשיים לא פשוטים."},{"id":"article-paragraph-d1741474bcb9","heading":"לסיכום - לראות את האדם, לא רק את המגבלות שלו","text":"אבל היא גם אפשרה לי לפגוש אנשים עם סיפורי חיים, עם הומור, עם רצונות, עם יכולות ועם צורך עמוק בקשר."},{"id":"article-paragraph-0f95e67b6c22","heading":"לסיכום - לראות את האדם, לא רק את המגבלות שלו","text":"אדם יכול לשכוח את השם שלי, ועדיין להתרגש מכך שאני זוכר את השם שלו."},{"id":"article-paragraph-8fcc25e20bd4","heading":"לסיכום - לראות את האדם, לא רק את המגבלות שלו","text":"הוא יכול להתקשות להרים את היד, אבל להתאמץ הרבה יותר כשאני מזכיר לו שפעם היה אלוף הארץ בג'ודו."},{"id":"article-paragraph-e50877199cfc","heading":"לסיכום - לראות את האדם, לא רק את המגבלות שלו","text":"והוא יכול לספר לי את אותו הסיפור חמש פעמים במפגש, ועדיין ליהנות מהשיחה בכל פעם מחדש."},{"id":"article-paragraph-0f8a4c16b6d8","heading":"לסיכום - לראות את האדם, לא רק את המגבלות שלו","text":"לצד כל אלה, חשוב גם לזכור שאותו אדם יכול לבחור שלא להשתתף בפעילות, ושגם הבחירה הזאת ראויה לכבוד."},{"id":"article-paragraph-31d529010e53","heading":"לסיכום - לראות את האדם, לא רק את המגבלות שלו","text":"המטרה היא לא רק להפעיל אנשים מבוגרים באמצעות כלבים, אלא להכיר אותם, לכבד את רצונותיהם, להתאים את הפעילות לצרכים שלהם ולאפשר להם להרגיש שרואים אותם, גם כשהיכולות שלהם משתנות."},{"id":"article-reference-520db70386af","heading":"מקורות","text":"Amanat et al. (2026) - Animal-Assisted Therapy in Dementia: A Systematic Review and Meta-Analysis of Cognitive, Affective, and Behavioral Outcomes סקירה שיטתית ומטא-אנליזה שבחנה את ההשפעה של התערבויות בעזרת בעלי חיים על תסמינים רגשיים, קוגניטיביים והתנהגותיים אצל אנשים עם דמנציה."},{"id":"article-reference-44e39248f406","heading":"מקורות","text":"Zhou et al. (2026) - The Effectiveness of Animal-Assisted Interventions for People Living With Dementia: An Overview of Systematic Reviews and Meta-Analysis סקירת-על של 16 סקירות שיטתיות, שמצאה תמיכה בהפחתת תסמיני דיכאון בקרב אנשים עם דמנציה."},{"id":"article-reference-e3036856eeed","heading":"מקורות","text":"משרד הבריאות - תקשורת רגישה עם אנשים עם דמנציה הנחיות מעשיות לתקשורת מכבדת, הימנעות ממבחני זיכרון, התאמת שאלות ומתן זמן לתגובה."},{"id":"article-reference-05dcf4a3926c","heading":"מקורות","text":"Alzheimer's Association - Repetition הסברים לחזרתיות בשאלות ובהתנהגויות אצל אנשים עם דמנציה, והמלצות לתגובה מותאמת."},{"id":"article-reference-2a3f309ad036","heading":"מקורות","text":"משרד הבריאות - פעילות ותעסוקה לאנשים עם דמנציה מתקדמת המלצות לשמירה על כבוד האדם, יצירת פעילויות משמעותיות והתאמה לתפקוד ולתחומי העניין האישיים."},{"id":"article-reference-3acb3505c590","heading":"מקורות","text":"Alzheimer Society of Canada - Person-centred care of people with dementia living in care homes עקרונות לטיפול ממוקד-אדם, המכבד את הזהות, ההעדפות והקשרים האישיים של אנשים עם דמנציה."},{"id":"article-reference-910666f8b849","heading":"מקורות","text":"משרד הבריאות - סימני אזהרה לאובדנות הנחיות לזיהוי אמירות המעידות על מצוקה וסיכון ולפנייה לגורמי טיפול מתאימים."}]},{"title":"טיפול בעזרת כלבים בנוער בסיכון - אמון, קשר והזדמנות לראות את עצמך אחרת","url":"https://derech-hakelev.com/pages/articles/dog-therapy-at-risk-youth/","entries":[{"id":"article-title-c8c1532261e6","heading":"תחילת המאמר","text":"טיפול בעזרת כלבים בנוער בסיכון - אמון, קשר והזדמנות לראות את עצמך אחרת"},{"id":"article-paragraph-67fe74d786ff","heading":"פתיחת המאמר","text":"אחת התגובות שאני מקבל כשאנשים שומעים שאני עובד עם כלבים גם עם נוער בסיכון היא הפתעה."},{"id":"article-paragraph-ce8efa7d4b69","heading":"פתיחת המאמר","text":"\"מה, נערים בגיל הזה באמת משתפים פעולה עם כלבים?\", \"זה לא ילדותי בשבילם?\", \"ועוד נוער בסיכון? הם בטח ציניים לכל הדברים האלה\"."},{"id":"article-paragraph-d1fe5a7f2664","heading":"פתיחת המאמר","text":"אני יכול להבין מאיפה השאלות האלה מגיעות. כשחושבים על כלבנות טיפולית, הרבה אנשים מדמיינים ילדים קטנים שמלטפים כלבים, מלמדים אותם פקודות ומשחקים איתם."},{"id":"article-paragraph-308ddc4e0fe5","heading":"פתיחת המאמר","text":"אבל יצא לי לעבוד גם עם נערים וגם עם נערות בסיכון, והניסיון שלי היה שונה מאוד מהתמונה הזאת."},{"id":"article-paragraph-f3bbdae58747","heading":"פתיחת המאמר","text":"דווקא בגיל ההתבגרות, ובמיוחד בעבודה עם בני נוער שחוו לא מעט קשיים בחייהם, הכלבים יכולים ליצור הזדמנויות משמעותיות לקשר, לשיחה ולהתנסות."},{"id":"article-paragraph-47bcf9a2f8ef","heading":"פתיחת המאמר","text":"העניין הוא לא רק אילו פעילויות אנחנו מביאים, אלא בעיקר איך אנחנו מביאים אותן, איזה קשר אנחנו מצליחים ליצור עם בני הנוער ומה אנחנו מנסים להשיג באמצעותן."},{"id":"article-heading-08f1271eeed1","heading":"מה זה בכלל נוער בסיכון?","text":"מה זה בכלל נוער בסיכון?"},{"id":"article-paragraph-ae1491d6ec14","heading":"מה זה בכלל נוער בסיכון?","text":"המושג \"נוער בסיכון\" מתייחס לבני נוער שמתמודדים עם נסיבות אישיות, משפחתיות או חברתיות שעלולות לפגוע בהתפתחות שלהם, בביטחונם וברווחתם."},{"id":"article-paragraph-6449e7162551","heading":"מה זה בכלל נוער בסיכון?","text":"אלה יכולים להיות בני נוער שחוו הזנחה, אלימות, פגיעות שונות, קשיים משפחתיים, דחייה חברתית, נשירה ממסגרות חינוכיות או מצבי מצוקה אחרים."},{"id":"article-paragraph-5a4e6cd69840","heading":"מה זה בכלל נוער בסיכון?","text":"חלקם מתמודדים גם עם קשיים בוויסות רגשי, בהתנהגות, ביצירת קשרים ובמתן אמון באחרים."},{"id":"article-paragraph-df383e13ee87","heading":"מה זה בכלל נוער בסיכון?","text":"אבל חשוב לזכור שנוער בסיכון הוא לא אוכלוסייה אחידה."},{"id":"article-paragraph-40d3ccffb3a2","heading":"מה זה בכלל נוער בסיכון?","text":"יש הבדלים גדולים בין הנערים והנערות, בסיפורי החיים שלהם, בכוחות שלהם ובצרכים הטיפוליים שלהם."},{"id":"article-paragraph-2f15236fab71","heading":"מה זה בכלל נוער בסיכון?","text":"המושג \"נוער בסיכון\" מתאר נסיבות וגורמי סיכון, ולא את האישיות של הנער או הנערה."},{"id":"article-paragraph-ceb96ebbbc62","heading":"מה זה בכלל נוער בסיכון?","text":"נער שמתקשה לקבל סמכות, מתפרץ או מסרב להשתתף בפעילות לא בהכרח עושה זאת רק מתוך רצון להתנגד. ההתנהגות יכולה להיות קשורה לחוויות קודמות, לקושי לתת אמון, לצורך בשליטה או לניסיון להתמודד עם מצבים שמאיימים עליו."},{"id":"article-paragraph-953ee82e2bc8","heading":"מה זה בכלל נוער בסיכון?","text":"זה לא אומר שכל התנהגות צריכה להתקבל, אבל כן חשוב שננסה להבין מה עומד מאחוריה."},{"id":"article-heading-2e656fb8c9d9","heading":"העבודה במרכז עד\"י לנערות בסיכון","text":"העבודה במרכז עד\"י לנערות בסיכון"},{"id":"article-paragraph-c7d77ad8f808","heading":"העבודה במרכז עד\"י לנערות בסיכון","text":"אחת המסגרות שבהן עבדתי הייתה מרכז עד\"י, מסגרת המיועדת לנערות בגילאי 13-18 שאינן משולבות במסגרת בית ספרית."},{"id":"article-paragraph-690f623a304d","heading":"העבודה במרכז עד\"י לנערות בסיכון","text":"הנערות שהגיעו למרכז התמודדו עם מצבי חיים מורכבים. חלקן היו מעורבות גם בהליכים פליליים, לצד קשיים משפחתיים, חברתיים ואישיים."},{"id":"article-paragraph-7fa532fa15c1","heading":"העבודה במרכז עד\"י לנערות בסיכון","text":"כשעובדים עם אוכלוסייה כזאת, חשוב להבין שלא תמיד פשוט להכניס אדם חדש לחיים שלהן, ובוודאי שלא לצפות שכבר במפגש הראשון הן ירגישו בנוח להיפתח ולשתף."},{"id":"article-paragraph-9053019c6a83","heading":"העבודה במרכז עד\"י לנערות בסיכון","text":"אלא שדווקא העבודה עם הכלבים יצרה הזדמנות מעניינת."},{"id":"article-paragraph-557dba5417a9","heading":"העבודה במרכז עד\"י לנערות בסיכון","text":"הפעילויות אפשרו לנו להתחיל ממשהו קליל יותר, שלא דורש מהנערות לשבת ולדבר על הקשיים שלהן מהרגע הראשון."},{"id":"article-paragraph-6175b3487b89","heading":"העבודה במרכז עד\"י לנערות בסיכון","text":"היינו משחקים, עובדים עם הכלבים, צוחקים ומשתתפים במשימות שונות, ומתוך הדברים האלה היו נוצרות גם שיחות משמעותיות."},{"id":"article-heading-c00b4f7a1cc1","heading":"למה הקשר הטיפולי חשוב כל כך בעבודה עם נוער בסיכון?","text":"למה הקשר הטיפולי חשוב כל כך בעבודה עם נוער בסיכון?"},{"id":"article-paragraph-5d6d0d0bea39","heading":"למה הקשר הטיפולי חשוב כל כך בעבודה עם נוער בסיכון?","text":"אחד האתגרים בעבודה עם בני נוער בסיכון הוא יצירת קשר של אמון."},{"id":"article-paragraph-4e8b946a2804","heading":"למה הקשר הטיפולי חשוב כל כך בעבודה עם נוער בסיכון?","text":"כשנער או נערה חוו שוב ושוב אכזבות, פגיעות או מערכות יחסים לא יציבות, לא תמיד יהיה להם קל לתת אמון במבוגר חדש."},{"id":"article-paragraph-47dab83e7c83","heading":"למה הקשר הטיפולי חשוב כל כך בעבודה עם נוער בסיכון?","text":"גם עצם הכניסה למסגרת טיפולית יכולה לעורר התנגדות."},{"id":"article-paragraph-8235c222b26e","heading":"למה הקשר הטיפולי חשוב כל כך בעבודה עם נוער בסיכון?","text":"למה שאני אספר לך משהו? מי אתה בכלל? איך אני יודע שאפשר לסמוך עליך?"},{"id":"article-paragraph-da4deab80966","heading":"למה הקשר הטיפולי חשוב כל כך בעבודה עם נוער בסיכון?","text":"אלה שאלות שגם אם הן לא נאמרות במפורש, יכולות להיות נוכחות מאוד בקשר."},{"id":"article-paragraph-c8432d013d60","heading":"למה הקשר הטיפולי חשוב כל כך בעבודה עם נוער בסיכון?","text":"לכן, לפני שאנחנו מנסים להיכנס לנושאים רגשיים מורכבים, חשוב קודם ליצור היכרות ולבסס קשר."},{"id":"article-paragraph-53e6cb991047","heading":"למה הקשר הטיפולי חשוב כל כך בעבודה עם נוער בסיכון?","text":"כאן יש לכלבים יתרון מעניין."},{"id":"article-paragraph-f111390b6129","heading":"למה הקשר הטיפולי חשוב כל כך בעבודה עם נוער בסיכון?","text":"הנער לא בהכרח צריך לשבת מול מטפל ולדבר על עצמו. אפשר להתחיל מפעילות משותפת, ממשחק, מאילוף הכלב או אפילו מבדיחה."},{"id":"article-paragraph-663aa8cc82be","heading":"למה הקשר הטיפולי חשוב כל כך בעבודה עם נוער בסיכון?","text":"הכלב נותן לנו משהו לעשות יחד, ודרך העשייה הזאת יכולה להיווצר בהדרגה גם שיחה."},{"id":"article-heading-91f18fb76453","heading":"איך הכלבים עוזרים לעקוף את הציניות?","text":"איך הכלבים עוזרים לעקוף את הציניות?"},{"id":"article-paragraph-8a6e8887fa05","heading":"איך הכלבים עוזרים לעקוף את הציניות?","text":"אני חושב שאחד הדברים המעניינים בעבודה עם בני נוער, ובמיוחד עם נוער בסיכון, הוא המקום של הציניות."},{"id":"article-paragraph-a4a3ed326d3e","heading":"איך הכלבים עוזרים לעקוף את הציניות?","text":"בגיל ההתבגרות יש לא מעט מצבים שבהם בני נוער משתמשים בצחוק, בהערות עוקצניות או בזלזול כדי להתמודד עם סיטואציות שלא נוח להם בהן."},{"id":"article-paragraph-2eecb2285c63","heading":"איך הכלבים עוזרים לעקוף את הציניות?","text":"ציניות יכולה להיות דרך לשמור על עצמם מפני מבוכה, חשיפה או פגיעות."},{"id":"article-paragraph-056f07f4756f","heading":"איך הכלבים עוזרים לעקוף את הציניות?","text":"כשאנחנו מגיעים עם פעילות טיפולית שמרגישה רצינית מדי, או כשאנחנו מבקשים מהם לדבר ישירות על הרגשות שלהם, אנחנו עלולים לפגוש התנגדות."},{"id":"article-paragraph-503813262e79","heading":"איך הכלבים עוזרים לעקוף את הציניות?","text":"אבל כשמגיע מישהו עם כלבים, משהו באווירה משתנה."},{"id":"article-paragraph-f9f4e3a54637","heading":"איך הכלבים עוזרים לעקוף את הציניות?","text":"הפעילות מלכתחילה פחות רשמית. אפשר לצחוק על משהו שהכלב עשה, להתבדח עם החברים או פשוט להתעסק בכלב בלי להרגיש שצריך לחשוף משהו אישי."},{"id":"article-paragraph-c8c51346f292","heading":"איך הכלבים עוזרים לעקוף את הציניות?","text":"כך נוצרת אפשרות להניח לרגע את הציניות בצד."},{"id":"article-paragraph-bf37e834d2ad","heading":"איך הכלבים עוזרים לעקוף את הציניות?","text":"זה לא אומר שאנחנו מנסים לבטל אותה או לשכנע את בני הנוער להפסיק להיות ציניים. הציניות יכולה למלא עבורם תפקיד חשוב, וגם היא ראויה להבנה."},{"id":"article-paragraph-999ac189123a","heading":"איך הכלבים עוזרים לעקוף את הציניות?","text":"אבל כשהם מרגישים בנוח, כשהפעילות מהנה וכשיש קשר טוב עם המטפל, הם לא תמיד זקוקים לה באותה המידה."},{"id":"article-paragraph-f5b9595e83b6","heading":"איך הכלבים עוזרים לעקוף את הציניות?","text":"וזה אחד הדברים שבלטו לי בעבודה."},{"id":"article-paragraph-fa67c4a2fa67","heading":"איך הכלבים עוזרים לעקוף את הציניות?","text":"הנערות יכלו להיות ציניות מאוד בתחילת המפגש, אבל בהמשך לצחוק, לשחק, להשתתף ולדבר גם על נושאים אישיים ומשמעותיים."},{"id":"article-paragraph-408b75d2a441","heading":"איך הכלבים עוזרים לעקוף את הציניות?","text":"הכלבים אפשרו לנו לעבור משיחה קלילה וצחוק לשיחה רצינית, בלי שהמעבר ירגיש מאולץ."},{"id":"article-paragraph-df82d93e61b5","heading":"איך הכלבים עוזרים לעקוף את הציניות?","text":"את הדבר הזה ראיתי גם בעבודה עם נערים בסיכון. ברגע שהפעילות מותאמת לגיל שלהם, והקשר עם המטפל טבעי ולא מתנשא, גם נערים שנראים בהתחלה מרוחקים או ציניים יכולים להתחבר ולהשתתף."},{"id":"article-heading-644f24138276","heading":"\"יש בנות שזאת הפעילות היחידה שהן נכנסות אליה\"","text":"\"יש בנות שזאת הפעילות היחידה שהן נכנסות אליה\""},{"id":"article-paragraph-cfebc17e77f6","heading":"\"יש בנות שזאת הפעילות היחידה שהן נכנסות אליה\"","text":"באחת התקופות שבהן עבדתי במרכז עד\"י, קיבלתי משוב משמעותי מאוד ממנהלת המקום."},{"id":"article-paragraph-453cbd1b00cd","heading":"\"יש בנות שזאת הפעילות היחידה שהן נכנסות אליה\"","text":"היא סיפרה לי שיש נערות שהפעילות עם הכלבים היא הפעילות היחידה שהן בוחרות להיכנס אליה."},{"id":"article-paragraph-21fb8886cd1c","heading":"\"יש בנות שזאת הפעילות היחידה שהן נכנסות אליה\"","text":"כשהייתה אפשרות שהמפגשים יסתיימו, הנערות עצמן ביקשו שהם יימשכו ולא רצו שאני והכלבים נפסיק להגיע."},{"id":"article-paragraph-50f2085aed47","heading":"\"יש בנות שזאת הפעילות היחידה שהן נכנסות אליה\"","text":"המשוב הזה המחיש לי משהו חשוב."},{"id":"article-paragraph-6f1dba1aa028","heading":"\"יש בנות שזאת הפעילות היחידה שהן נכנסות אליה\"","text":"אנחנו יכולים לבנות פעילות טיפולית עם מטרות טובות מאוד, אבל אם בני הנוער לא רוצים להגיע אליה או לא מצליחים להתחבר אליה, יהיה קשה להשיג את אותן מטרות."},{"id":"article-paragraph-6610117f159b","heading":"\"יש בנות שזאת הפעילות היחידה שהן נכנסות אליה\"","text":"עצם הרצון להגיע, להשתתף ולהישאר בקשר הוא לא דבר מובן מאליו."},{"id":"article-paragraph-bc9ae93f2395","heading":"\"יש בנות שזאת הפעילות היחידה שהן נכנסות אליה\"","text":"העניין בכלבים, ההומור והחוויה המשותפת יכולים לעזור להפוך את המפגש למשהו שבני הנוער רוצים להיות חלק ממנו."},{"id":"article-paragraph-b8cb6fd1e52a","heading":"\"יש בנות שזאת הפעילות היחידה שהן נכנסות אליה\"","text":"ומשם אפשר להתחיל לעבוד."},{"id":"article-heading-d5a542adc81d","heading":"הצוות הוא חלק בלתי נפרד מהתהליך","text":"הצוות הוא חלק בלתי נפרד מהתהליך"},{"id":"article-paragraph-2e3bf74cbaa7","heading":"הצוות הוא חלק בלתי נפרד מהתהליך","text":"אחד הדברים שתרמו מאוד לעבודה שלי במרכז עד\"י היה הצוות של המקום."},{"id":"article-paragraph-8e8f8f7ae9a6","heading":"הצוות הוא חלק בלתי נפרד מהתהליך","text":"היו שם שינשיניות מקסימות שהיו שותפות לפעילויות, עזרו לי במפגשים והיו חלק משמעותי מהקשר עם הנערות. גם המנהלת ושאר הצוות היו מאוד רתומים לתהליך ונתנו לי תחושה שיש שיתוף פעולה אמיתי."},{"id":"article-paragraph-8b61fdd4be3e","heading":"הצוות הוא חלק בלתי נפרד מהתהליך","text":"אני זוכר גם את אם הבית המקסימה, שבכל פעם שהייתי מסיים את המפגש הייתה מזמינה אותי להישאר לארוחת צהריים. היא הייתה מכינה אוכל מדהים, והארוחות האלה היו עוד חלק מהאווירה החמה והמשפחתית שהייתה במקום."},{"id":"article-paragraph-cf6920bcc737","heading":"הצוות הוא חלק בלתי נפרד מהתהליך","text":"זה אולי נשמע כמו פרט קטן שלא קשור ישירות לכלבנות טיפולית, אבל הוא חלק מהסיפור."},{"id":"article-paragraph-813faa030e0d","heading":"הצוות הוא חלק בלתי נפרד מהתהליך","text":"כשאנחנו מגיעים לעבוד במסגרת, אנחנו לא עובדים רק עם המשתתפים בפעילות. אנחנו נכנסים למקום שיש בו צוות, מערכות יחסים, שגרה ותרבות משלו."},{"id":"article-paragraph-9c9830131a98","heading":"הצוות הוא חלק בלתי נפרד מהתהליך","text":"כשהצוות מכיר את המטרות, מאמין בפעילות ומשתף פעולה, הרבה יותר קל ליצור המשכיות, להתמודד עם קשיים שעולים בקבוצה ולהבין מה עובר על בני הנוער גם מחוץ למפגשים שלנו."},{"id":"article-paragraph-2d4e4a53d7f0","heading":"הצוות הוא חלק בלתי נפרד מהתהליך","text":"אחד הדברים שהמנהלת הייתה עושה הוא לשלוח לי לפני כל מפגש רשימה של הנערות שנמצאות במרכז באותו יום."},{"id":"article-paragraph-bfe60b4aae09","heading":"הצוות הוא חלק בלתי נפרד מהתהליך","text":"מעבר לכך שזה אפשר לי לדעת מראש מי צפויה להגיע ולהיערך בהתאם, היה לזה ערך נוסף מבחינתי: לזכור את השמות שלהן."},{"id":"article-heading-03e211cac1e2","heading":"לזכור שמות - דבר קטן שעושה הבדל גדול","text":"לזכור שמות - דבר קטן שעושה הבדל גדול"},{"id":"article-paragraph-97e1e161e1f9","heading":"לזכור שמות - דבר קטן שעושה הבדל גדול","text":"אחד הדברים שאני ממליץ עליהם כמעט בכל מסגרת שבה אני עובד הוא להתאמץ לזכור את השמות של המשתתפים."},{"id":"article-paragraph-4d07dcd60978","heading":"לזכור שמות - דבר קטן שעושה הבדל גדול","text":"אני אומר את זה דווקא בתור מישהו שהזיכרון שלו לא מדהים. זה לא תמיד בא לי בקלות, ואני צריך להשקיע בזה מאמץ."},{"id":"article-paragraph-2b89710aa1ad","heading":"לזכור שמות - דבר קטן שעושה הבדל גדול","text":"אבל זה משהו שמאוד חשוב לי."},{"id":"article-paragraph-542861302d7f","heading":"לזכור שמות - דבר קטן שעושה הבדל גדול","text":"במרכז עד\"י הייתי מגיע למפגש עם שבע או שמונה נערות, ולא תמיד היו אלה אותן נערות מהשבוע הקודם. הרשימה שהמנהלת הייתה שולחת לי אפשרה לי לעבור על השמות לפני המפגש ולנסות לזכור מי מגיעה."},{"id":"article-paragraph-ffdabdcf8357","heading":"לזכור שמות - דבר קטן שעושה הבדל גדול","text":"היו מצבים שבהם הנערות עצמן התקשו לזכור את השם שלי ממפגש למפגש, אבל אני זכרתי את השמות שלהן."},{"id":"article-paragraph-100239c40ea1","heading":"לזכור שמות - דבר קטן שעושה הבדל גדול","text":"לא פעם הן היו ממש מופתעות."},{"id":"article-paragraph-f1fba103ff97","heading":"לזכור שמות - דבר קטן שעושה הבדל גדול","text":"\"איך אתה זוכר את השם שלי?\""},{"id":"article-paragraph-172282142acb","heading":"לזכור שמות - דבר קטן שעושה הבדל גדול","text":"וזה בדיוק העניין."},{"id":"article-paragraph-2405e6c88388","heading":"לזכור שמות - דבר קטן שעושה הבדל גדול","text":"כשאנחנו פונים לאדם בשמו, במיוחד כשלא ראינו אותו במשך שבוע או כשפגשנו אותו רק פעמים בודדות, אנחנו מעבירים לו מסר פשוט: ראיתי אותך, אני זוכר אותך, אתה לא עוד מישהו שעבר פה."},{"id":"article-paragraph-1f3fdb4254b3","heading":"לזכור שמות - דבר קטן שעושה הבדל גדול","text":"אני לא חושב שצריך להפריז במשמעות של הדבר הזה, אבל ראיתי שוב ושוב עד כמה הוא יכול להיות משמעותי עבור מי שנמצא מולנו."},{"id":"article-paragraph-3b054ffd6d92","heading":"לזכור שמות - דבר קטן שעושה הבדל גדול","text":"וזה לא קשור רק לעבודה עם נוער בסיכון. גם בעבודה עם ילדים, עם מבוגרים ועם קבוצות אחרות, אני משתדל להקפיד על כך."},{"id":"article-paragraph-cad21eb24d75","heading":"לזכור שמות - דבר קטן שעושה הבדל גדול","text":"לפני שאנחנו מבקשים ממישהו לשתף אותנו במשהו אישי, כדאי שנדע לפחות איך קוראים לו."},{"id":"article-paragraph-ab37a5ea5088","heading":"לזכור שמות - דבר קטן שעושה הבדל גדול","text":"לכן, חלק חשוב מהעבודה הוא ליצור קשר טוב גם עם אנשי הצוות, לשתף אותם בתהליך ולהיעזר בהיכרות שלהם עם הנערים והנערות."},{"id":"article-paragraph-1f94ed4c2cf8","heading":"לזכור שמות - דבר קטן שעושה הבדל גדול","text":"העבודה עם בני הנוער לא מתקיימת בנפרד מהמסגרת שבה הם נמצאים. ככל שיש יותר שיתוף פעולה עם הצוות, כך אפשר ליצור תהליך משמעותי ומותאם יותר."},{"id":"article-heading-0008707efb72","heading":"הקשר לא תמיד מסתיים כשהפעילות נגמרת","text":"הקשר לא תמיד מסתיים כשהפעילות נגמרת"},{"id":"article-paragraph-448260cd8c02","heading":"הקשר לא תמיד מסתיים כשהפעילות נגמרת","text":"אחד הדברים המשמעותיים שחוויתי בעבודה במרכז היה שהקשר שנוצר במפגשים לא תמיד הסתיים כשהפעילות הרשמית נגמרה."},{"id":"article-paragraph-c0f96a36facf","heading":"הקשר לא תמיד מסתיים כשהפעילות נגמרת","text":"היו מקרים שבהם נשארתי במרכז גם אחרי המפגש, משום שהנערות רצו להמשיך לדבר, לשתף או פשוט להיות יחד."},{"id":"article-paragraph-51b0c423cbcd","heading":"הקשר לא תמיד מסתיים כשהפעילות נגמרת","text":"בין השיחות היו גם רגעים שבהם אחת הנערות הייתה נפתחת ומספרת דברים אישיים מאוד."},{"id":"article-paragraph-40cd264f9452","heading":"הקשר לא תמיד מסתיים כשהפעילות נגמרת","text":"לא תמיד זה קרה בזמן הפעילות הטיפולית שתכננתי. היו שיתופים שהגיעו דווקא אחרי שהמפגש הסתיים, כשהאווירה הייתה פחות רשמית והקשר כבר היה מבוסס."},{"id":"article-paragraph-1a500fdc519a","heading":"הקשר לא תמיד מסתיים כשהפעילות נגמרת","text":"אני חושב שיש בזה משהו חשוב להבנה של עבודה עם בני נוער."},{"id":"article-paragraph-0c27f74cf201","heading":"הקשר לא תמיד מסתיים כשהפעילות נגמרת","text":"לא כל שיחה משמעותית מתרחשת כשאנחנו מבקשים לשבת ולדבר על רגשות."},{"id":"article-paragraph-2fc168e7c011","heading":"הקשר לא תמיד מסתיים כשהפעילות נגמרת","text":"לפעמים דווקא השיחות שמתפתחות באופן טבעי, בלי שאלון או משימה מסוימת, הן אלו שמאפשרות לנער או לנערה לספר דברים שקשה להם להביא במקומות אחרים."},{"id":"article-paragraph-ec4b5d3267b5","heading":"הקשר לא תמיד מסתיים כשהפעילות נגמרת","text":"כמובן, גם במפגשים הלא פורמליים האלה צריך לשמור על הגבולות המקצועיים, על פרטיות, על כללי המסגרת ועל האחריות שלנו כמטפלים."},{"id":"article-paragraph-b06a0c4bce4c","heading":"הקשר לא תמיד מסתיים כשהפעילות נגמרת","text":"אבל לא צריך להפוך כל רגע בקשר לשיחה טיפולית מובנית."},{"id":"article-paragraph-a25f5bb53fd4","heading":"הקשר לא תמיד מסתיים כשהפעילות נגמרת","text":"לפעמים הדרך להגיע לשיחה עמוקה מתחילה דווקא ביכולת לשבת עם בני הנוער, להתעניין במה שמעניין אותם, לצחוק איתם ולא לנסות כל הזמן להוביל אותם לנושא מסוים."},{"id":"article-heading-0975b0f0dffd","heading":"עבודה על אמון - במי אני סומך ומי סומך עליי?","text":"עבודה על אמון - במי אני סומך ומי סומך עליי?"},{"id":"article-paragraph-204ce8b678c8","heading":"עבודה על אמון - במי אני סומך ומי סומך עליי?","text":"אחד הנושאים שעסקתי בהם במפגשים היה אמון."},{"id":"article-paragraph-5af36668dc00","heading":"עבודה על אמון - במי אני סומך ומי סומך עליי?","text":"אפשר לעבוד על אמון דרך פעילויות שונות עם הכלבים, למשל משימות שבהן צריך לסמוך על מי שמוביל, להיעזר באחרים או לפעול בשיתוף פעולה."},{"id":"article-paragraph-b626c8bade91","heading":"עבודה על אמון - במי אני סומך ומי סומך עליי?","text":"אבל הפעילות עצמה היא רק נקודת הפתיחה."},{"id":"article-paragraph-96aa47e486b3","heading":"עבודה על אמון - במי אני סומך ומי סומך עליי?","text":"אחריה אפשר לדבר על מה שקרה ולחבר את הדברים לחיים של בני הנוער."},{"id":"article-paragraph-8d134d3d1052","heading":"עבודה על אמון - במי אני סומך ומי סומך עליי?","text":"על מי אתם סומכים? מי סומך עליכם? מה גורם לכם לתת אמון במישהו? מה קורה כשמישהו מאכזב אתכם?"},{"id":"article-paragraph-6f71dfa7030b","heading":"עבודה על אמון - במי אני סומך ומי סומך עליי?","text":"אני זוכר שבאחת הקבוצות, כבר במפגש הראשון, במהלך פעילות שעסקה באמון וביצירת קשר, אחת הנערות אמרה שאין אף אדם בעולם שהיא סומכת עליו."},{"id":"article-paragraph-8a5b168d9d6f","heading":"עבודה על אמון - במי אני סומך ומי סומך עליי?","text":"זאת אמירה משמעותית מאוד, במיוחד במפגש ראשון."},{"id":"article-paragraph-177f612648eb","heading":"עבודה על אמון - במי אני סומך ומי סומך עליי?","text":"היא יכולה לפתוח פתח להבנה של האופן שבו אותה נערה חווה קשרים ואת המקום של אמון בחייה."},{"id":"article-paragraph-9f695bb2efcc","heading":"עבודה על אמון - במי אני סומך ומי סומך עליי?","text":"בקבוצה חשוב במיוחד לשמור על הבחירה של כל משתתפת כמה לחשוף, ולא להפוך שיתוף אישי לתנאי להשתתפות בפעילות."},{"id":"article-paragraph-5cef35e8976c","heading":"עבודה על אמון - במי אני סומך ומי סומך עליי?","text":"עצם האפשרות לומר משהו כזה ולקבל תגובה מכבדת יכולה להיות התחלה של חוויה אחרת בתוך קשר."},{"id":"article-heading-ecba08a449e6","heading":"כוחות וחסמים - לראות גם את מה שכן יש בי","text":"כוחות וחסמים - לראות גם את מה שכן יש בי"},{"id":"article-paragraph-a8da76af405e","heading":"כוחות וחסמים - לראות גם את מה שכן יש בי","text":"נושא נוסף שאני אוהב לעבוד עליו עם בני נוער הוא כוחות וחסמים."},{"id":"article-paragraph-219d30e94168","heading":"כוחות וחסמים - לראות גם את מה שכן יש בי","text":"הרבה נערים ונערות בסיכון מגיעים אחרי שנים שבהן שמעו בעיקר מה לא בסדר אצלם."},{"id":"article-paragraph-e5e9301de474","heading":"כוחות וחסמים - לראות גם את מה שכן יש בי","text":"שהם לא מקשיבים, לא משתפים פעולה, מתנהגים לא יפה, לא מצליחים בלימודים או עושים בעיות."},{"id":"article-paragraph-f40781313d93","heading":"כוחות וחסמים - לראות גם את מה שכן יש בי","text":"עם הזמן, האופן שבו הסביבה מתייחסת אלינו יכול להשפיע גם על הדרך שבה אנחנו תופסים את עצמנו."},{"id":"article-paragraph-43d67335c8cd","heading":"כוחות וחסמים - לראות גם את מה שכן יש בי","text":"לכן חשוב לי ליצור במפגשים הזדמנויות שבהן בני הנוער יכולים לזהות יכולות וכוחות שלהם."},{"id":"article-paragraph-3151bbdfdf0a","heading":"כוחות וחסמים - לראות גם את מה שכן יש בי","text":"אפשר לעשות זאת דרך משימות עם הכלבים שדורשות התמדה, סבלנות, תקשורת או פתרון בעיות."},{"id":"article-paragraph-edd7496befb0","heading":"כוחות וחסמים - לראות גם את מה שכן יש בי","text":"כשנערה מצליחה ללמד כלב לבצע פעולה, כשהיא מתמודדת עם אתגר או עוזרת למישהי אחרת להצליח, אפשר לעצור ולהתייחס למה שקרה."},{"id":"article-paragraph-2febb37a5495","heading":"כוחות וחסמים - לראות גם את מה שכן יש בי","text":"איזה כוח בא לידי ביטוי כאן? מה עזר לך להצליח? האם את מזהה את היכולת הזאת גם במקומות אחרים בחיים?"},{"id":"article-paragraph-edafdb283046","heading":"כוחות וחסמים - לראות גם את מה שכן יש בי","text":"המטרה היא לא רק לתת מחמאות, אלא לעזור לבני הנוער לזהות בעצמם יכולות שאולי לא תמיד מקבלות מקום."},{"id":"article-heading-4b80373dca01","heading":"עבודה על כוחות באמצעות המשחק DRIVE","text":"עבודה על כוחות באמצעות המשחק DRIVE"},{"id":"article-paragraph-48271aca68f6","heading":"עבודה על כוחות באמצעות המשחק DRIVE","text":"באחד המפגשים השתמשתי במשחק הקלפים DRIVE שעוסק ביצרים של כלבים (ואנשים)."},{"id":"article-paragraph-6a57f726c230","heading":"עבודה על כוחות באמצעות המשחק DRIVE","text":"התחלנו בהיכרות עם היצרים השונים ובשיחה על הדרך שבה הם באים לידי ביטוי בהתנהגות של כלבים. משם עברנו לדבר על בני אדם ועל המקומות שבהם אפשר לזהות דחפים, נטיות וכוחות דומים גם בחיים שלנו."},{"id":"article-paragraph-7c29d1310608","heading":"עבודה על כוחות באמצעות המשחק DRIVE","text":"בהמשך ביקשתי מכל נערה לבחור שני יצרים: אחד שהיא מרגישה שהוא חזק אצלה, ואחד שהיא הייתה רוצה לחזק בעצמה."},{"id":"article-paragraph-f8bd8fc6aa99","heading":"עבודה על כוחות באמצעות המשחק DRIVE","text":"היה מעניין מאוד לשמוע את הבחירות שלהן ואת ההסברים שנתנו."},{"id":"article-paragraph-195e41b6f4a2","heading":"עבודה על כוחות באמצעות המשחק DRIVE","text":"לא מעט נערות בחרו ביצר ההישרדות כיצר חזק אצלן. אחרות דיברו על יצר קרב או הגנה. היו גם נערות שהתייחסו ליצרים שהיו רוצות לפתח יותר."},{"id":"article-paragraph-cff4ccd8478f","heading":"עבודה על כוחות באמצעות המשחק DRIVE","text":"אחת הנערות, למשל, בחרה ביצר המנהיגות כמשהו שהייתה רוצה לחזק בעצמה."},{"id":"article-paragraph-619418228684","heading":"עבודה על כוחות באמצעות המשחק DRIVE","text":"נערה אחרת בחרה ביצר הלהקה. מתוך השיחה עלה הרצון שלה להרגיש שייכת, להיות חלק מקבוצת השווים שלה, ולא להרגיש את הזרות שהיא חוותה."},{"id":"article-paragraph-d91db9cc3d4d","heading":"עבודה על כוחות באמצעות המשחק DRIVE","text":"הפעילות הזאת אפשרה שיח מעניין מאוד על האופן שבו כל אחת מהן רואה את עצמה."},{"id":"article-paragraph-106819f7f125","heading":"עבודה על כוחות באמצעות המשחק DRIVE","text":"הבחירה ביצר ההישרדות או ביצר הקרב לא חייבת להעיד על קושי או על משהו שלילי. אלה יכולים להיות כוחות שעזרו לאדם להתמודד עם מצבים מורכבים בחייו. השאלה היא איך הכוחות האלה באים לידי ביטוי, מתי הם עוזרים לנו ומתי אנחנו מרגישים שהם מגבילים אותנו."},{"id":"article-paragraph-6205db7a37e2","heading":"עבודה על כוחות באמצעות המשחק DRIVE","text":"גם הבחירה ביצר שהיינו רוצים לחזק יכולה ללמד הרבה על הדברים שחסרים לנו או שאנחנו שואפים אליהם."},{"id":"article-paragraph-50c572e5255d","heading":"עבודה על כוחות באמצעות המשחק DRIVE","text":"דרך הקלפים הצלחנו לדבר על נושאים כמו הישרדות, התמודדות, מנהיגות ושייכות, בלי לפתוח את המפגש בשאלות ישירות על הקשיים האישיים של הנערות."},{"id":"article-paragraph-d595ee26d791","heading":"עבודה על כוחות באמצעות המשחק DRIVE","text":"היצרים של הכלבים שימשו לנו שפה משותפת לחשוב באמצעותה על הכוחות שלנו, על הדרך שבה אנחנו מתמודדים עם העולם ועל הדברים שהיינו רוצים לפתח בעצמנו."},{"id":"article-paragraph-88ca2fbb056e","heading":"עבודה על כוחות באמצעות המשחק DRIVE","text":"חשוב לזכור שזאת הייתה פעילות של התבוננות ושיח באמצעות מושגים מעולם הכלבים, ולא ניסיון לקבוע שלבני אדם יש בדיוק את אותם יצרים או להסיק מסקנות אבחוניות מתוך בחירת הקלפים."},{"id":"article-heading-3e18305b0aaa","heading":"סטיגמות - איך מתייחסים אליי ומה חושבים עליי?","text":"סטיגמות - איך מתייחסים אליי ומה חושבים עליי?"},{"id":"article-paragraph-7b34dd4f872f","heading":"סטיגמות - איך מתייחסים אליי ומה חושבים עליי?","text":"נושא נוסף שאפשר לעבוד עליו דרך הכלבים הוא סטיגמות."},{"id":"article-paragraph-5be0c0523314","heading":"סטיגמות - איך מתייחסים אליי ומה חושבים עליי?","text":"לכלבים שונים יש מראה, גודל, גזע והתנהגות שונים, והם יכולים לעורר אצל אנשים תגובות שונות עוד לפני שהכירו אותם."},{"id":"article-paragraph-739bf3cdaa13","heading":"סטיגמות - איך מתייחסים אליי ומה חושבים עליי?","text":"יש אנשים שיחששו מכלב מסוים בגלל המראה שלו, ואחרים יניחו שכלב שנראה חמוד הוא בהכרח ידידותי."},{"id":"article-paragraph-79005cfac45a","heading":"סטיגמות - איך מתייחסים אליי ומה חושבים עליי?","text":"מכאן אפשר לפתוח שיחה על הדרך שבה אנחנו שופטים אחרים ועל האופן שבו אנשים שופטים אותנו."},{"id":"article-paragraph-3749578c4963","heading":"סטיגמות - איך מתייחסים אליי ומה חושבים עליי?","text":"האם יצא לכם שאנשים חשבו עליכם משהו עוד לפני שהכירו אתכם? האם הרגשתם שמתייגים אתכם? האם גם אנחנו עושים את זה לאחרים?"},{"id":"article-paragraph-c5354d472368","heading":"סטיגמות - איך מתייחסים אליי ומה חושבים עליי?","text":"בעבודה עם בני נוער בסיכון, זה יכול להיות נושא משמעותי במיוחד."},{"id":"article-paragraph-23461aaeb3a7","heading":"סטיגמות - איך מתייחסים אליי ומה חושבים עליי?","text":"נער או נערה שמזוהים עם התנהגות מסוימת, עם מסגרת חינוכית מסוימת או עם תווית של \"נוער בסיכון\" עלולים להרגיש שאנשים כבר החליטו מי הם."},{"id":"article-paragraph-a72701c2d00a","heading":"סטיגמות - איך מתייחסים אליי ומה חושבים עליי?","text":"העבודה הטיפולית יכולה לאפשר להם לבחון את התוויות האלה, אבל גם את הדרך שבה הם עצמם מסתכלים על אחרים."},{"id":"article-heading-d3248d70ae8e","heading":"איך הסביבה משפיעה על ההתנהגות שלנו?","text":"איך הסביבה משפיעה על ההתנהגות שלנו?"},{"id":"article-paragraph-187dbecc987f","heading":"איך הסביבה משפיעה על ההתנהגות שלנו?","text":"אחת הפעילויות שהעברתי עם נערות בסיכון עסקה בהשפעת הסביבה."},{"id":"article-paragraph-0d5985965209","heading":"איך הסביבה משפיעה על ההתנהגות שלנו?","text":"במהלך הפעילות יצאנו עם הכלבים החוצה והתבוננו באופן שבו הם מתנהגים בסביבה אחרת."},{"id":"article-paragraph-1abd950f43a9","heading":"איך הסביבה משפיעה על ההתנהגות שלנו?","text":"כלב יכול להתנהג בצורה מסוימת במקום מוכר ושקט, ולהגיב אחרת לחלוטין כשהוא מגיע לסביבה עם אנשים, רעשים, ריחות וגירויים חדשים."},{"id":"article-paragraph-df671d152d67","heading":"איך הסביבה משפיעה על ההתנהגות שלנו?","text":"אפשר לראות שהוא נעשה יותר נרגש, פחות קשוב, יותר דרוך או דווקא יותר סקרן."},{"id":"article-paragraph-9636a7332612","heading":"איך הסביבה משפיעה על ההתנהגות שלנו?","text":"מכאן עברנו לדבר על בני האדם."},{"id":"article-paragraph-4a424ea67759","heading":"איך הסביבה משפיעה על ההתנהגות שלנו?","text":"האם אנחנו מתנהגים באותה הדרך בכל מקום?"},{"id":"article-paragraph-0fffaff386e6","heading":"איך הסביבה משפיעה על ההתנהגות שלנו?","text":"האם אני אותה נערה כשאני בבית, בבית הספר, עם חברות או ליד אנשים שאני לא מכירה?"},{"id":"article-paragraph-4e7bb61a2989","heading":"איך הסביבה משפיעה על ההתנהגות שלנו?","text":"איך הנוכחות של אנשים מסוימים משפיעה עליי? האם יש מקומות שבהם אני מרגישה בטוחה יותר? האם יש סביבות שבהן קשה לי יותר לשלוט בתגובות שלי?"},{"id":"article-paragraph-e9c5d096a9c1","heading":"איך הסביבה משפיעה על ההתנהגות שלנו?","text":"הפעילות הזאת מאפשרת לדבר על השפעת הסביבה בלי להתחיל משאלה ישירה כמו \"למה את מתנהגת ככה?\"."},{"id":"article-paragraph-76d6ae740096","heading":"איך הסביבה משפיעה על ההתנהגות שלנו?","text":"אנחנו מתחילים בהתבוננות על הכלב, ומשם אפשר לחשוב גם על עצמנו."},{"id":"article-paragraph-a70b38f42618","heading":"איך הסביבה משפיעה על ההתנהגות שלנו?","text":"וזה חשוב במיוחד משום שהתנהגות לא מתרחשת בחלל ריק. היא מושפעת גם מהסביבה, ממערכות היחסים ומהתחושה שלנו בתוך המצב."},{"id":"article-heading-40cf03dda5ac","heading":"שיתוף פעולה ותקשורת - כשצריך להצליח ביחד","text":"שיתוף פעולה ותקשורת - כשצריך להצליח ביחד"},{"id":"article-paragraph-63a4d0ce170f","heading":"שיתוף פעולה ותקשורת - כשצריך להצליח ביחד","text":"בחלק מהפעילויות רציתי ליצור מצבים שבהם הנערות צריכות לשתף פעולה כדי להצליח."},{"id":"article-paragraph-8e613eb31b14","heading":"שיתוף פעולה ותקשורת - כשצריך להצליח ביחד","text":"למשל, פעילות שבה קושרים את הרגליים של המשתתפות יחד, בצורה מותאמת ובטוחה, והן צריכות לתאם את התנועה שלהן כדי להתקדם ולבצע משימות."},{"id":"article-paragraph-5cf0720c3b7a","heading":"שיתוף פעולה ותקשורת - כשצריך להצליח ביחד","text":"אפשר לשלב גם משימות שבהן צריך להוביל כלב, לעבור במסלול או להצליח במשימה משותפת."},{"id":"article-paragraph-8e0aa856a8dc","heading":"שיתוף פעולה ותקשורת - כשצריך להצליח ביחד","text":"העניין הוא שלא מספיק שכל אחת תנסה להצליח לבד."},{"id":"article-paragraph-8b19c368e372","heading":"שיתוף פעולה ותקשורת - כשצריך להצליח ביחד","text":"כדי לבצע את המשימה צריך להתייחס למי שנמצאות לידך, להקשיב, לתאם, להתפשר ולמצוא דרך לפעול יחד."},{"id":"article-paragraph-35399c70d34e","heading":"שיתוף פעולה ותקשורת - כשצריך להצליח ביחד","text":"וכשלא מצליחים, יכולה להתעורר גם תחושת תסכול."},{"id":"article-paragraph-23158250d614","heading":"שיתוף פעולה ותקשורת - כשצריך להצליח ביחד","text":"מי מחליטה מה עושים? מה קורה כשלא מסכימים? האם אחת מנסה להשתלט על המשימה? האם מישהי מוותרת מיד?"},{"id":"article-paragraph-b5303bc44b88","heading":"שיתוף פעולה ותקשורת - כשצריך להצליח ביחד","text":"אלה בדיוק הרגעים שבהם אפשר לעבוד על תקשורת, על חלוקת תפקידים ועל הדרך שבה אנחנו מגיבים לאחרים."},{"id":"article-paragraph-d9990bf7dc5d","heading":"שיתוף פעולה ותקשורת - כשצריך להצליח ביחד","text":"כמובן, פעילות שכוללת קשירה או הגבלת תנועה דורשת הסכמה מלאה, בחירה חופשית והקפדה על בטיחות. לא חייבים להשתמש בקשירה עצמה כדי לתרגל את אותן מיומנויות; אפשר ליצור משימות משותפות גם באמצעות חישוק, אביזר שמחזיקים יחד או מסלול שדורש תיאום."},{"id":"article-heading-ffec45c271ca","heading":"שילוב של שיחה, הומור ופעילות עם הכלבים","text":"שילוב של שיחה, הומור ופעילות עם הכלבים"},{"id":"article-paragraph-63352931a65d","heading":"שילוב של שיחה, הומור ופעילות עם הכלבים","text":"אחד הדברים שעבדו טוב בקבוצות היה השילוב בין פעילויות עם הכלבים לבין שיחה ומשחק."},{"id":"article-paragraph-59d43b1ad8d0","heading":"שילוב של שיחה, הומור ופעילות עם הכלבים","text":"לא כל מפגש צריך להיות שיחה טיפולית כבדה, ולא כל פעילות צריכה להיות אתגר מורכב."},{"id":"article-paragraph-83b377c371d8","heading":"שילוב של שיחה, הומור ופעילות עם הכלבים","text":"היו גם משימות פשוטות כמו לספר סיפור מצחיק, לשתף משהו על עצמך או להגיד משהו טוב למישהי אחרת בקבוצה."},{"id":"article-paragraph-51f7ff981958","heading":"שילוב של שיחה, הומור ופעילות עם הכלבים","text":"אפשר לשלב משימות כאלה בתוך משחק, ובין שאלה לשאלה לבצע פעילות עם הכלב."},{"id":"article-paragraph-8e29dbdc9927","heading":"שילוב של שיחה, הומור ופעילות עם הכלבים","text":"השילוב הזה מאפשר לנוע בין שיחה לעשייה, בין רגעים רציניים לרגעים קלילים, ובין התבוננות פנימית לקשר עם שאר הקבוצה."},{"id":"article-paragraph-58da53503a5a","heading":"שילוב של שיחה, הומור ופעילות עם הכלבים","text":"ההומור היה חלק חשוב מאוד מהעבודה שלי עם בני הנוער."},{"id":"article-paragraph-2aa94518d547","heading":"שילוב של שיחה, הומור ופעילות עם הכלבים","text":"כשאני מצליח לדבר איתם בגובה העיניים, להבין את הראש שלהם, לצחוק איתם ולא להגיע בגישה מרוחקת או מתנשאת, נוצרות הזדמנויות אחרות לקשר."},{"id":"article-paragraph-2d13e04a2e4c","heading":"שילוב של שיחה, הומור ופעילות עם הכלבים","text":"וזה לא אומר לנסות להיות אחד מהחבר'ה או לוותר על הגבולות המקצועיים."},{"id":"article-paragraph-26f3f8a5e42e","heading":"שילוב של שיחה, הומור ופעילות עם הכלבים","text":"אפשר להיות מבוגר משמעותי, לשמור על מסגרת ועל גבולות, ובו בזמן להיות נגיש, טבעי ולדעת גם לצחוק."},{"id":"article-heading-915d6f08c369","heading":"אתגר נוסף - כשהרכב הקבוצה משתנה ממפגש למפגש","text":"אתגר נוסף - כשהרכב הקבוצה משתנה ממפגש למפגש"},{"id":"article-paragraph-b95af5ef49ff","heading":"אתגר נוסף - כשהרכב הקבוצה משתנה ממפגש למפגש","text":"אחד הקשיים המשמעותיים בעבודה במסגרות של נוער בסיכון הוא שלא תמיד אפשר לבנות על קבוצה קבועה."},{"id":"article-paragraph-111679647211","heading":"אתגר נוסף - כשהרכב הקבוצה משתנה ממפגש למפגש","text":"במסגרות כאלה יש תחלופה של משתתפים. נערים ונערות מסיימים את השהות במסגרת, אחרים מצטרפים, וגם מי שנמצאים בה לא בהכרח מגיעים לכל מפגש."},{"id":"article-paragraph-886d7180df75","heading":"אתגר נוסף - כשהרכב הקבוצה משתנה ממפגש למפגש","text":"כך יכול להיווצר מצב שבמפגש אחד אנחנו עובדים עם קבוצה מסוימת, ובשבוע שלאחר מכן פוגשים הרכב שונה לגמרי."},{"id":"article-paragraph-e87e2402d23f","heading":"אתגר נוסף - כשהרכב הקבוצה משתנה ממפגש למפגש","text":"מישהי שהשתתפה במפגש הקודם אולי לא תגיע הפעם, ולעומתה תצטרף נערה חדשה שעדיין לא מכירה אותי, את הכלבים או את אופי הפעילות."},{"id":"article-paragraph-6621a6d50b02","heading":"אתגר נוסף - כשהרכב הקבוצה משתנה ממפגש למפגש","text":"זה יוצר אתגר לא פשוט בבניית תהליך קבוצתי."},{"id":"article-paragraph-2182e0d84dc4","heading":"אתגר נוסף - כשהרכב הקבוצה משתנה ממפגש למפגש","text":"כשאנחנו מתכננים סדרה של מפגשים, אנחנו בדרך כלל רוצים שתהיה התקדמות. שנוכל להתבסס על מה שהיה במפגש הקודם, להעמיק בנושאים מסוימים ולפתח בהדרגה קשרים ומיומנויות."},{"id":"article-paragraph-1cd8adbd6da5","heading":"אתגר נוסף - כשהרכב הקבוצה משתנה ממפגש למפגש","text":"אבל מה עושים כשחלק מהמשתתפים לא היו במפגש הקודם? ומה קורה כשמגיעה נערה חדשה באמצע התהליך?"},{"id":"article-paragraph-9b92811e5965","heading":"אתגר נוסף - כשהרכב הקבוצה משתנה ממפגש למפגש","text":"אחד הדברים שלמדתי הוא שצריך למצוא את האיזון."},{"id":"article-paragraph-31ceb74d6a6b","heading":"אתגר נוסף - כשהרכב הקבוצה משתנה ממפגש למפגש","text":"מצד אחד, חשוב להחזיק בראש את המטרות ואת התהליך הרחב שאנחנו רוצים ליצור."},{"id":"article-paragraph-0d68bb3fb9e4","heading":"אתגר נוסף - כשהרכב הקבוצה משתנה ממפגש למפגש","text":"מצד שני, כל מפגש צריך להיות מסוגל לעמוד גם בפני עצמו."},{"id":"article-paragraph-fc72eda7ec92","heading":"אתגר נוסף - כשהרכב הקבוצה משתנה ממפגש למפגש","text":"כלומר, שגם נערה שמגיעה בפעם הראשונה, או כזאת שלא השתתפה בשבועות האחרונים, תוכל להיכנס לפעילות, להבין מה עושים ולהפיק ממנה משהו משמעותי."},{"id":"article-paragraph-c33321043b97","heading":"אתגר נוסף - כשהרכב הקבוצה משתנה ממפגש למפגש","text":"לכן השתדלתי לבחור פעילויות שיש להן ערך בפני עצמן, אבל גם מאפשרות להעמיק ולהתחבר לנושאים שעבדנו עליהם במפגשים קודמים."},{"id":"article-paragraph-48019860328f","heading":"אתגר נוסף - כשהרכב הקבוצה משתנה ממפגש למפגש","text":"למשל, אפשר לעסוק באמון, בשיתוף פעולה או בכוחות אישיים בלי להניח שכל המשתתפות כבר מכירות את המושגים או את התרגילים."},{"id":"article-paragraph-8968f4c4e27f","heading":"אתגר נוסף - כשהרכב הקבוצה משתנה ממפגש למפגש","text":"מי שכבר השתתפה במפגשים קודמים יכולה להמשיך ולהעמיק, ומי שהגיעה לראשונה יכולה לקחת חלק בלי להרגיש שהיא פספסה משהו."},{"id":"article-paragraph-3c3d20f070e2","heading":"אתגר נוסף - כשהרכב הקבוצה משתנה ממפגש למפגש","text":"גם כאן העבודה עם הכלבים עזרה מאוד. הפעילות המעשית מאפשרת להכניס משתתפים חדשים לתוך העשייה המשותפת, בלי צורך בהסברים ארוכים על כל מה שהיה קודם."},{"id":"article-paragraph-f333c699e3d6","heading":"אתגר נוסף - כשהרכב הקבוצה משתנה ממפגש למפגש","text":"האתגר הוא לא לוותר על התהליך בגלל התחלופה, אלא ללמוד לבנות אותו כך שיוכל להכיל אותה."},{"id":"article-heading-640910328585","heading":"מה עושים כשמגיעים לקבוצה אחרי ריב או אירוע סוער?","text":"מה עושים כשמגיעים לקבוצה אחרי ריב או אירוע סוער?"},{"id":"article-paragraph-241585c108a0","heading":"מה עושים כשמגיעים לקבוצה אחרי ריב או אירוע סוער?","text":"אחד האתגרים בעבודה עם קבוצות של נוער בסיכון הוא שלא תמיד אנחנו מגיעים לקבוצה שנמצאת במצב רגשי שמאפשר מיד להתחיל בפעילות שתכננו."},{"id":"article-paragraph-ebaff76e6b3b","heading":"מה עושים כשמגיעים לקבוצה אחרי ריב או אירוע סוער?","text":"היו מפגשים שהגעתי אליהם אחרי ריב בין נערות, עימות בין קבוצות או אירוע סוער אחר במסגרת."},{"id":"article-paragraph-b2f432b8d20d","heading":"מה עושים כשמגיעים לקבוצה אחרי ריב או אירוע סוער?","text":"במצבים כאלה, האווירה יכולה להיות מתוחה מאוד."},{"id":"article-paragraph-994bee98caf8","heading":"מה עושים כשמגיעים לקבוצה אחרי ריב או אירוע סוער?","text":"יש כעס, עלבון, חוסר אמון ולעיתים גם קושי לשבת יחד באותו החדר."},{"id":"article-paragraph-41e166c744af","heading":"מה עושים כשמגיעים לקבוצה אחרי ריב או אירוע סוער?","text":"כאן חשוב לזכור שהתוכנית שהכנו למפגש אינה חשובה יותר ממה שהקבוצה צריכה באותו רגע."},{"id":"article-paragraph-d6adf2d98994","heading":"מה עושים כשמגיעים לקבוצה אחרי ריב או אירוע סוער?","text":"לא תמיד נכון להתעקש על הפעילות המקורית."},{"id":"article-paragraph-546bbd01d5a3","heading":"מה עושים כשמגיעים לקבוצה אחרי ריב או אירוע סוער?","text":"אפשר להתחיל בפעילות פשוטה יותר עם הכלבים, לאפשר לקבוצה להירגע, ובהמשך לבדוק אם נכון להתייחס למה שקרה."},{"id":"article-paragraph-1024258b5b34","heading":"מה עושים כשמגיעים לקבוצה אחרי ריב או אירוע סוער?","text":"אפשר גם להשתמש בפעילות משותפת כדי ליצור התנסות אחרת, שבה המשתתפות צריכות לתקשר ולשתף פעולה."},{"id":"article-paragraph-b32822c86f8f","heading":"מה עושים כשמגיעים לקבוצה אחרי ריב או אירוע סוער?","text":"אבל צריך להיזהר שלא להפוך את המשימה הטיפולית לעוד זירה של מאבק."},{"id":"article-paragraph-e47b8ca046fd","heading":"מה עושים כשמגיעים לקבוצה אחרי ריב או אירוע סוער?","text":"אם הקבוצה מוצפת מאוד, או אם קיים סיכון לפגיעה בין המשתתפים, צריך להתייחס קודם כול לביטחון ולוויסות, ולתאם את המענה עם צוות המסגרת."},{"id":"article-paragraph-52dd632bf1fd","heading":"מה עושים כשמגיעים לקבוצה אחרי ריב או אירוע סוער?","text":"במצבים כאלה, ההיכרות של הצוות עם הנערות ושיתוף הפעולה איתו היו חשובים במיוחד. הם אפשרו לי להבין טוב יותר מה התרחש לפני שהגעתי, מה עובר על המשתתפות ואיך נכון להתאים את הפעילות למצבה של הקבוצה."},{"id":"article-paragraph-3a9edb3936b0","heading":"מה עושים כשמגיעים לקבוצה אחרי ריב או אירוע סוער?","text":"היכולת להתאים את עצמנו למה שקורה בקבוצה חשובה לא פחות מהיכולת לתכנן פעילות טובה."},{"id":"article-heading-6b0f9c047b8b","heading":"מה אומרים המחקרים על נוער בסיכון וטיפול בעזרת בעלי חיים?","text":"מה אומרים המחקרים על נוער בסיכון וטיפול בעזרת בעלי חיים?"},{"id":"article-paragraph-43dcd8c31480","heading":"מה אומרים המחקרים על נוער בסיכון וטיפול בעזרת בעלי חיים?","text":"המחקר על התערבויות בעזרת בעלי חיים בקרב ילדים ובני נוער מצביע על כמה כיוונים מעניינים."},{"id":"article-paragraph-d9537e957013","heading":"מה אומרים המחקרים על נוער בסיכון וטיפול בעזרת בעלי חיים?","text":"מחקר שפורסם בשנת 2015 בחן 63 מתבגרים במסגרות חוץ ביתיות, שחוו טראומות בילדות והתמודדו עם קשיים נפשיים."},{"id":"article-paragraph-8e00fd951217","heading":"מה אומרים המחקרים על נוער בסיכון וטיפול בעזרת בעלי חיים?","text":"במחקר השתתפו 39 מתבגרים בתוכנית פסיכותרפיה בעזרת בעלי חיים, לעומת 24 מתבגרים בקבוצת השוואה."},{"id":"article-paragraph-af3b9a6832f8","heading":"מה אומרים המחקרים על נוער בסיכון וטיפול בעזרת בעלי חיים?","text":"החוקרים מצאו שבני הנוער שהשתתפו בתוכנית הראו הסתגלות טובה יותר לבית הספר בהשוואה לקבוצת ההשוואה."},{"id":"article-paragraph-5908157ce646","heading":"מה אומרים המחקרים על נוער בסיכון וטיפול בעזרת בעלי חיים?","text":"סקירה שיטתית שפורסמה בשנת 2024 בחנה שבעה מחקרים על טיפול בעזרת כלבים בקרב ילדים שחוו טראומה מורכבת."},{"id":"article-paragraph-589d7a2cadd4","heading":"מה אומרים המחקרים על נוער בסיכון וטיפול בעזרת בעלי חיים?","text":"הממצאים הצביעו על אפשרות שהשילוב של כלבים יכול לתרום להתערבויות טיפוליות קיימות, אף שהחוקרים ציינו שהמחקר בתחום עדיין מוגבל."},{"id":"article-paragraph-7848655bd671","heading":"מה אומרים המחקרים על נוער בסיכון וטיפול בעזרת בעלי חיים?","text":"גם סקירה שיטתית ומטא אנליזה שפורסמה בשנת 2025 ובחנה את הקשר בין התערבויות בעזרת כלבים לרמות קורטיזול אצל ילדים ומתבגרים מצאה ירידה מובהקת במדד זה בתת קבוצה של התערבויות שנמשכו יותר מ-15 דקות."},{"id":"article-paragraph-c7dac15ccd1c","heading":"מה אומרים המחקרים על נוער בסיכון וטיפול בעזרת בעלי חיים?","text":"הממצאים האלה מציעים שהנוכחות של כלבים והפעילות איתם עשויות לתרום להפחתת תגובות דחק במצבים מסוימים."},{"id":"article-paragraph-f69421e9affd","heading":"מה אומרים המחקרים על נוער בסיכון וטיפול בעזרת בעלי חיים?","text":"חשוב להבחין בין המחקרים השונים: חלקם עוסקים בילדים שחוו טראומה, חלקם בבני נוער במסגרות טיפוליות, וחלקם בילדים ומתבגרים באופן כללי. לא כל המחקרים בוחנים דווקא נוער בסיכון או עבודה קבוצתית עם כלבים."},{"id":"article-paragraph-e2efb43d36b4","heading":"מה אומרים המחקרים על נוער בסיכון וטיפול בעזרת בעלי חיים?","text":"ועדיין, הממצאים מספקים בסיס מעניין להמשך בחינת השילוב של כלבים בעבודה טיפולית עם בני נוער."},{"id":"article-heading-2f2ef16cf86f","heading":"מה חשוב לקחת בחשבון בעבודה עם נוער בסיכון?","text":"מה חשוב לקחת בחשבון בעבודה עם נוער בסיכון?"},{"id":"article-paragraph-863ed43076c8","heading":"מה חשוב לקחת בחשבון בעבודה עם נוער בסיכון?","text":"כדי לעבוד בצורה משמעותית עם בני נוער בסיכון, לא מספיק להגיע עם כלב ועם משחקים טובים."},{"id":"article-paragraph-ed0cefc85bce","heading":"מה חשוב לקחת בחשבון בעבודה עם נוער בסיכון?","text":"צריך לדעת ליצור קשר, להיות גמישים, להבין את הדינמיקה הקבוצתית ולזהות מתי נכון להעמיק בשיחה ומתי עדיף פשוט לאפשר חוויה משותפת."},{"id":"article-paragraph-3a0aae650b4a","heading":"מה חשוב לקחת בחשבון בעבודה עם נוער בסיכון?","text":"חשוב לתת מקום לבחירה. נער או נערה שלא רוצים להשתתף בפעילות מסוימת אינם בהכרח מתנגדים לכל התהליך."},{"id":"article-paragraph-363022d7a343","heading":"מה חשוב לקחת בחשבון בעבודה עם נוער בסיכון?","text":"צריך גם לכבד את הגבולות של בני הנוער, לא ללחוץ עליהם לחשוף חוויות אישיות ולא להפוך את הקבוצה למקום שבו הם מרגישים שהם חייבים לספר דברים אינטימיים."},{"id":"article-paragraph-1ba3021c2a9e","heading":"מה חשוב לקחת בחשבון בעבודה עם נוער בסיכון?","text":"כשנערה משתפת בחוויה קשה, חשוב לדעת להקשיב, לשמור על גבולות הסודיות ולהסביר מראש גם את המקרים שבהם קיימת חובה לשתף גורמי טיפול או הגנה."},{"id":"article-paragraph-1d6ca6f6f052","heading":"מה חשוב לקחת בחשבון בעבודה עם נוער בסיכון?","text":"גם בקשר שנמשך מעבר לזמן הפעילות הפורמלית, חשוב להקפיד על גבולות ברורים ועל עבודה מתואמת עם צוות המסגרת. קשר חם ואישי אינו מחייב טשטוש של תפקיד המטפל."},{"id":"article-paragraph-f8404f265a8e","heading":"מה חשוב לקחת בחשבון בעבודה עם נוער בסיכון?","text":"ולצד כל אלה, חשוב לשמור גם על הכלבים."},{"id":"article-paragraph-dc2393ff6f04","heading":"מה חשוב לקחת בחשבון בעבודה עם נוער בסיכון?","text":"קבוצה סוערת, רעש חזק או התנהגות בלתי צפויה יכולים להיות מאתגרים עבור כלב טיפולי. לכן צריך להתאים את הפעילויות גם ליכולת של הכלב, לאפשר לו מרחב ומנוחה ולוודא שהמפגש אינו יוצר עבורו מצוקה."},{"id":"article-heading-dac798dd831a","heading":"לסיכום - זה לא ילדותי, זאת דרך אחרת ליצור קשר","text":"לסיכום - זה לא ילדותי, זאת דרך אחרת ליצור קשר"},{"id":"article-paragraph-b849dfa7ebaa","heading":"לסיכום - זה לא ילדותי, זאת דרך אחרת ליצור קשר","text":"העבודה עם נערים ונערות בסיכון חיזקה אצלי את ההבנה שהערך של הכלבנות הטיפולית לא תלוי בגיל של המשתתפים או במורכבות של הפעילות."},{"id":"article-paragraph-f65c37928622","heading":"לסיכום - זה לא ילדותי, זאת דרך אחרת ליצור קשר","text":"הכלב יכול להיות נקודת פתיחה לקשר, לשיחה, לשיתוף פעולה ולהתנסויות שקשה יותר ליצור בדרכים אחרות."},{"id":"article-paragraph-d0d2bd559735","heading":"לסיכום - זה לא ילדותי, זאת דרך אחרת ליצור קשר","text":"דרך העבודה עם הכלבים אפשר לדבר על אמון, על מערכות יחסים, על כוחות וחסמים, על השפעת הסביבה ועל הדרך שבה אנחנו מתייחסים לעצמנו ולאחרים."},{"id":"article-paragraph-821ee7915bd4","heading":"לסיכום - זה לא ילדותי, זאת דרך אחרת ליצור קשר","text":"אבל לא פחות חשוב מכך, אפשר גם לצחוק, לשחק וליהנות יחד."},{"id":"article-paragraph-6a99fd6d3f41","heading":"לסיכום - זה לא ילדותי, זאת דרך אחרת ליצור קשר","text":"הנערות שביקשו שהמפגשים יימשכו, השיתוף האישי שעלה כבר במפגש הראשון והשיחות שנמשכו גם אחרי שהפעילות הסתיימה - כל אלה המחישו לי כמה משמעותי יכול להיות הקשר שנוצר סביב העבודה עם הכלבים."},{"id":"article-paragraph-7dc6812b98ae","heading":"לסיכום - זה לא ילדותי, זאת דרך אחרת ליצור קשר","text":"לצד הקשר עם בני הנוער, למדתי גם עד כמה חשוב הקשר עם הצוות. השינשיניות, המנהלת, אם הבית ושאר אנשי הצוות במרכז עד\"י היו חלק משמעותי מהחוויה ומהאפשרות לקיים תהליך מתמשך."},{"id":"article-paragraph-6713d18fb79f","heading":"לסיכום - זה לא ילדותי, זאת דרך אחרת ליצור קשר","text":"אחד הדברים החשובים שלמדתי הוא שלא תמיד צריך להתחיל מהנושאים הכבדים."},{"id":"article-paragraph-bb03f3785239","heading":"לסיכום - זה לא ילדותי, זאת דרך אחרת ליצור קשר","text":"אפשר להתחיל מהצחוק, מהמשחק ומהכלב, ומשם להתקדם בהדרגה לשיחות אישיות יותר."},{"id":"article-paragraph-abd57e2b2c02","heading":"לסיכום - זה לא ילדותי, זאת דרך אחרת ליצור קשר","text":"הכלב לא מחליף את המטפל, והמשחק לא מחליף את הקשר הטיפולי."},{"id":"article-paragraph-e0ccc337db5b","heading":"לסיכום - זה לא ילדותי, זאת דרך אחרת ליצור קשר","text":"אבל כשהפעילות מותאמת לבני הנוער, וכשהמטפל מצליח לדבר איתם בגובה העיניים וליצור קשר משמעותי, הכלבים יכולים לפתוח דלת למפגשים ולשיחות שלא תמיד היו מתאפשרים באותה הדרך."},{"id":"article-paragraph-1df218ae3384","heading":"לסיכום - זה לא ילדותי, זאת דרך אחרת ליצור קשר","text":"השאלה היא לא אם נוער בסיכון מבוגר מדי בשביל כלבנות טיפולית, אלא איך אנחנו משתמשים בכלבים כדי ליצור עבורו חוויה שמתאימה לגילו, לצרכים שלו ולמה שהוא מביא איתו."},{"id":"article-reference-f6d2c758bffe","heading":"מקורות","text":"World Health Organization - Mental Health of Adolescents סקירה של גורמי סיכון וגורמי הגנה לבריאות הנפש בגיל ההתבגרות, הכוללת התייחסות לחוויות חיים קשות, יחסים משפחתיים, לחץ חברתי והתפתחות רגשית."},{"id":"article-reference-aa102b41c865","heading":"מקורות","text":"Centers for Disease Control and Prevention - Risk and Protective Factors for Adverse Childhood Experiences הסבר על גורמי סיכון וגורמי הגנה, כולל החשיבות של קשרים יציבים, מבוגרים משמעותיים וסביבות חברתיות תומכות."},{"id":"article-reference-2ac4ed86e296","heading":"מקורות","text":"Promoting Psychosocial Adaptation of Youths in Residential Care Through Animal-Assisted Psychotherapy (2015) מחקר בקרב 63 מתבגרים במסגרות חוץ־ביתיות, שבחן את תרומת הפסיכותרפיה בעזרת בעלי חיים להסתגלות הפסיכו־חברתית."},{"id":"article-reference-ba82a89f3741","heading":"מקורות","text":"Chapman et al. (2024) - Exploring the Benefits of Dog-Assisted Therapy for the Treatment of Complex Trauma in Children: A Systematic Review סקירה שיטתית של שבעה מחקרים על שימוש בכלבים כחלק מהתערבויות טיפוליות לילדים שחוו טראומה מורכבת."},{"id":"article-reference-4c0a2235e337","heading":"מקורות","text":"Dog Companionship and Cortisol Levels in Youth: A Systematic Review and Meta-Analysis (2025) מטא־אנליזה שבחנה את הקשר בין התערבויות בעזרת כלבים לרמות קורטיזול אצל ילדים ומתבגרים."}]}];
